; FDC (Floppy Disk Controller) handler offset table
; Used with FDC_HANDLER_DISPATCH_BASE for command dispatching
; Entry = (8A40h) value 0-11, multiplied by 2 to get offset
FDC_HANDLER_OFFSETS:	; EA98CA
	.short FDC_HANDLER_DISPATCH_BASE - FDC_HANDLER_DISPATCH_BASE	; 0: offset 0x00
	.short FDC_HANDLER_01 - FDC_HANDLER_DISPATCH_BASE	; 1: offset 0x05
	.short FDC_HANDLER_02 - FDC_HANDLER_DISPATCH_BASE	; 2: offset 0x0D
	.short FDC_HANDLER_03 - FDC_HANDLER_DISPATCH_BASE	; 3: offset 0x15
	.short FDC_HANDLER_04 - FDC_HANDLER_DISPATCH_BASE	; 4: offset 0x1D
	.short FDC_HANDLER_05 - FDC_HANDLER_DISPATCH_BASE	; 5: offset 0x25
	.short FDC_HANDLER_06 - FDC_HANDLER_DISPATCH_BASE	; 6: offset 0x2D
	.short FDC_HANDLER_07 - FDC_HANDLER_DISPATCH_BASE	; 7: offset 0x32
	.short FDC_HANDLER_08 - FDC_HANDLER_DISPATCH_BASE	; 8: offset 0x37
	.short FDC_HANDLER_09 - FDC_HANDLER_DISPATCH_BASE	; 9: offset 0x3C
	.short FDC_HANDLER_10 - FDC_HANDLER_DISPATCH_BASE	; 10: offset 0x41
	.short FDC_HANDLER_11 - FDC_HANDLER_DISPATCH_BASE	; 11: offset 0x46


