	ldio 0xED, 0x00
	ldio 0xEE, 0x00
	ldio 0xEF, 0x00
	ret

; ===========================================================================
; SubCPU_Send_Payload - Transfer 192KB Sub-CPU payload from Table Data ROM
; ===========================================================================
; Entry: None (reads from 0xFFFEEF to check if transfer should proceed)
; Exit:  XIZ restored, payload transferred to Sub-CPU RAM
; Notes: Sends the Sub-CPU firmware payload in multiple 64KB chunks:
;        - 0x830000-0x870000 (5 x 64KB) â†’ Sub-CPU 0x050000-0x090000
;        - Additional data from Table Data ROM â†’ Sub-CPU 0x00F000-0x02F000
;        - Final 256 bytes â†’ Sub-CPU 0x000400 (entry point area)
;        Uses E1 bulk transfer protocol via InterCPU_E1_Bulk_Transfer
;        Includes 0x2000 and 0x100000 iteration delay loops for timing
;        Called during boot sequence after SubCPU_Init_DMA_Channels
; ===========================================================================
SubCPU_Send_Payload:
	push xiz
	cpi8_24 0xfffeef, 0xff
	jrl nz, LABEL_EF078B
	lds32 xiz, 0

LABEL_EF0696:
	inc 1, xiz
	cp xiz, 0x2000
	jr c, LABEL_EF0696
	ld xwa, 0x830000
	ld xbc, 0x10000
	ld xde, 0x50000
	call 0xEF3457
	ld xwa, 0x840000
	ld xbc, 0x10000
	ld xde, 0x60000
	call 0xEF3457
	ld xwa, 0x850000
	ld xbc, 0x10000
	ld xde, 0x70000
	call 0xEF3457
	ld xwa, 0x860000
	ld xbc, 0x10000
	ld xde, 0x80000
	call 0xEF3457
	ld xwa, 0x870000
	ld xbc, 0x10000
	ld xde, 0x90000
	call 0xEF3457
	ld xiz, 0x800000
	cpi8_24 0xfffeed, 0xff
	jr nz, LABEL_EF072A
	ld xiz, 0x50000
	ld xwa, 0x3E0000
	ld xbc, 0x50000
	call SLIDE_Parse_Header
	cp hl, 0xFFFF
	jr nz, LABEL_EF072A
	ld xiz, 0x800000

LABEL_EF072A:
	ldmm_sriw 0xF9, 0x00, 0x01, 0x04, 0x04
	ld xwa, xiz
	add xwa, 0x100
	ld xbc, 0x10000
	ld xde, 0xF000
	call 0xEF3457
	ld xwa, xiz
	add xwa, 0x10100
	ld xbc, 0x10000
	ld xde, 0x1F000
	call 0xEF3457
	ld xwa, xiz
	add xwa, 0x20100
	ldw bc, 0xFF00
	ld xde, 0x2F000
	call 0xEF3457
	ld xwa, xiz
	ldw bc, 0x100
	ld xde, 0x400
	call 0xEF3457
	lds32 xiz, 0

LABEL_EF0781:
