	push xiy
	push xiz
	ld w, a
	ldb l, 0xC
	mul8rr l, a
	extz xhl
	add xhl, 0xEF18EB
	ldb c, 0xC
	mul8rr c, a
	add bc, 0x47D
	extz xbc
	ld xix, xbc
	ld a, (xix + 9)
	cps a, 0
	jrl nz, TaskSched_ReturnToDispatch
	ld (xix + 11), w
	ld xiy, (xhl + 4)
	sub xiy, 0x22
	ld wa, (xhl + 8)
	ld (xiy + 28), wa
	ld xwa, (xhl + 256)
	ld (xiy + 30), xwa
	ld (xix + 4), xiy
	ld a, (xhl + 10)
	ld (xix + 8), a
	ld (xix + 9), 0x4
	ld (xix + 10), 0x0
	ld a, (xhl + 10)
	sll a, 2
	extz wa
	add wa, 0x4C1
	ld iy, wa
	extz xix
	extz xiy
	xor xwa, xwa
	ld (xix + 256), iy
	ld wa, (xiy + 2)
	ld (xix + 2), wa
	ld (xwa), ix
	ld (xiy + 2), ix
	jrl TaskSched_Dispatch
	ei 6
	ld xsp, 0x1E53A
	ldda16 xix, 1159
	extz xix
	ld (xix + 9), 0x0
	ld (xix + 10), 0x0
	xor wa, wa
	stda16 1159, xwa
	extz xix
	xor xwa, xwa
	xor xhl, xhl
	ld wa, (xix + 256)
	ld hl, (xix + 2)
	ld (xhl + 256), wa
	ld (xwa + 2), hl
	jrl TaskSched_Dispatch

