; ===========================================================================
; Audio_Lock_Release - Release inter-CPU communication lock
; ===========================================================================
; Entry: A = lock index (0-7)
; Exit:  Lock released, next waiting request (if any) is signaled
; Notes: Increments counter at (0x0532 + lock_index)
;        Processes linked list at 0x0487 to wake waiting tasks
;        Must be paired with Audio_Lock_Acquire
; ===========================================================================
Audio_Lock_Release:
	push_sr
	ei 6
	push xhl
	push xwa
	push xbc
	push xde
	push xix
	push xiy
	push xiz
	ld l, a
	sll a, 2
	extz wa
	add wa, 0x4FF
	ld iy, wa
	extz xiy
	ld ix, (xiy + 256)
	cp ix, iy
	jr nz, AudioLock_Release_WakeWaiter
	extz hl
	add hl, 0x532
	extz xhl
	ld a, (xhl)
	inc 1, a
	jr z, AudioLock_Release_NoWaiter_Done
	ld (xhl), a

AudioLock_Release_NoWaiter_Done:
	jrl TaskSched_ReturnToDispatch

AudioLock_Release_WakeWaiter:
	extz xix
	xor xwa, xwa
	xor xhl, xhl
	ld wa, (xix + 256)
	ld hl, (xix + 2)
	ld (xhl + 256), wa
	ld (xwa + 2), hl
	ld (xix + 9), 0x4
	ld a, (xix + 8)
	sll a, 2
	extz wa
	add wa, 0x4C1
	ld iy, wa
	extz xix
	extz xiy
	xor xwa, xwa
	ld (xix + 256), iy
	ld wa, (xiy + 2)
	ld (xix + 2), wa
	ld (xwa), ix
	ld (xiy + 2), ix
	jrl TaskSched_Dispatch
	push xwa
	push xix
	push xiy
	push xhl
	ld l, a
	sll a, 2
	extz wa
	add wa, 0x4FF
	ld iy, wa
	extz xiy
	push_sr
	ei 6
	ld ix, (xiy + 256)
	cp ix, iy
	jr nz, AudioLock_Release_NB_WakeWaiter
	extz hl
	add hl, 0x532
	extz xhl
	ld a, (xhl)
	inc 1, a
	jr z, AudioLock_Release_NB_Saturated
	ld (xhl), a

AudioLock_Release_NB_Saturated:
	pop_sr
	pop xhl
	pop xiy
	pop xix
	pop xwa
	ret

AudioLock_Release_NB_WakeWaiter:
	extz xix
	xor xwa, xwa
	xor xhl, xhl
	ld wa, (xix + 256)
	ld hl, (xix + 2)
	ld (xhl + 256), wa
	ld (xwa + 2), hl
	ld (xix + 9), 0x4
	ld a, (xix + 8)
	sll a, 2
	extz wa
	add wa, 0x4C1
	ld iy, wa
	extz xix
	extz xiy
	xor xwa, xwa
	ld (xix + 256), iy
	ld wa, (xiy + 2)
	ld (xix + 2), wa
	ld (xwa), ix
	ld (xiy + 2), ix
	pop_sr
	pop xhl
	pop xiy
	pop xix
	pop xwa
	ret

; ===========================================================================
; Audio_Lock_Acquire - Acquire inter-CPU communication lock
; ===========================================================================
; Entry: A = lock index (0-7)
; Exit:  Lock acquired, safe to send audio commands
; Notes: Decrements counter at (0x0532 + lock_index)
;        If counter is zero, adds request to linked list at 0x0487 and waits
;        Must be paired with Audio_Lock_Release after sending commands
;        Used by audio subsystem to serialize access to Sub-CPU communication
; ===========================================================================
Audio_Lock_Acquire:
	push_sr
	ei 6
	push xhl
	push xwa
	push xbc
	push xde
	push xix
	push xiy
	push xiz
	ld e, a
	extz wa
	add wa, 0x532
	extz xwa
	cp (xwa), 0x0
	jr z, AudioLock_Acquire_Block
	decm8 1, (xwa)
	jrl TaskSched_ReturnToDispatch

AudioLock_Acquire_Block:
	ldda16 xix, 1159
	extz xix
	xor xwa, xwa
	xor xhl, xhl
	ld wa, (xix + 256)
	ld hl, (xix + 2)
	ld (xhl + 256), wa
	ld (xwa + 2), hl
	ld (xix + 9), 0x3
	sll e, 2
	extz de
	add de, 0x4FF
	ld iy, de
	extz xix
	extz xiy
	xor xwa, xwa
	ld (xix + 256), iy
	ld wa, (xiy + 2)
	ld (xix + 2), wa
	ld (xwa), ix
	ld (xiy + 2), ix
	jrl TaskSched_Dispatch

AudioLock_TryAcquire:
	extz wa
	add wa, 0x532
	extz xwa
	push_sr
	ei 6
	cp (xwa), 0x0
	jr z, AudioLock_TryAcquire_Fail
	decm8 1, (xwa)
	xor hl, hl
	jr AudioLock_TryAcquire_Return

AudioLock_TryAcquire_Fail:
	ldw hl, 0xFFFF

AudioLock_TryAcquire_Return:
	pop_sr
	ret

AudioLock_GetCount:
	extz wa
	add wa, 0x532
	extz xwa
	ld l, (xwa)
	extz hl
	ret

