	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	lda_dd8l XBC, 0xF0
	ld a, (xbc)
	and a, 0xF8
	set 0, a
	ld (xbc), a
	ldio 0x8A, 0x07
	lda_24 xwa, 0x140000
	ldc_cr32 xwa, 0x28
	ldb a, 0x8
	ldc_cr8 a, 0x4A
	lda_24 xwa, 0x140000
