	stdi8 1504, 1
	sti8_24 0x140000, 0xe2
	lds ix, 0

LABEL_EF33D4:
	bit_dd8 3, 0x68	; SSTAT1 - wait for Sub CPU to acknowledge (goes low)
	jr nz, LABEL_EF340D
	set_dd8 0, 0x68	; MSTAT0 - set to signal E2 header data ready
