; ===========================================================================
; HDAE5000_Detect - Detect presence of HDAE5000 expansion board
; ===========================================================================
; Entry: None
; Exit:  XWA at (XSP+8) = 0 if detected, 0xFFFFFFFF if not present
; Notes: Probes Table Data ROM at 0x800000 using flash command sequence
;        Sends AMD/Atmel flash ID command (0xAA, 0x55, 0x90)
;        Checks for valid response to confirm hardware presence
; ===========================================================================
HDAE5000_Detect:
	dec 8, xsp
	push xiz
	ld xwa, 0xFFFFFFFF
	ld (xsp + 8), xwa
	ei 6
	ld xwa, 0xAA00AA
	st32_24 0x815554, xwa
	ld xwa, 0x550055
	st32_24 0x80aaa8, xwa
	ld xwa, 0x900090
	st32_24 0x815554, xwa
	ld32_24 xwa, 0x800000
	ld (xsp + 4), xwa
	ld xwa, 0x800000
	ld xiz, (xwa + 4)
	ei 0
	ld xwa, (xsp + 4)
	cp xwa, 0x10001
	jr z, LABEL_EF3D5E
	cp xwa, 0x40004
	jr nz, LABEL_EF3D74

LABEL_EF3D5E:
	cp xiz, 0x22D622D6
	jr z, LABEL_EF3D6E
	cp xiz, 0x22582258
	jr nz, LABEL_EF3D71

LABEL_EF3D6E:
	ld (xsp + 8), xiz

LABEL_EF3D71:
