SLIDE_Decompress_8K_CheckLiteral:
	ldto_werp WA, 0x30
	bit 0, wa
	jr z, SLIDE_Decompress_8K_CopyMatch
	cp xhl, xix
	jrl nc, SLIDE_Decompress_8K_Done
	ld_spib E, 0x34
	ld a, e
	extz wa
	ld e, a
	lda_dpi XIY, 0x38
	inc 1, xhl
	ld wa, bc
	inc 1, bc
	extz xwa
	addda32 xwa, 1570
	ld (xwa), e
	and bc, 0x1FFF
	jr SLIDE_Decompress_8K_Continue

SLIDE_Decompress_8K_CopyMatch:
	cp xhl, xix
	jr nc, SLIDE_Decompress_8K_Done
	ld_spib A, 0x34
	extz wa
	ldfr_werp WA, 0x32
	cp xhl, xix
	jr nc, SLIDE_Decompress_8K_Done
	ld_spib A, 0x34
	ldfr_berp A, 0xF8
	extz iz
	ld wa, iz
	and wa, 0xF8
	sll wa, 5
	ex_werp WA, 0x32
	or_werp WA, 0x32
	ex_werp WA, 0x32
	and iz, 0x7
	inc 2, iz
	lds iy, 0
	cps iz, 0
	jr c, SLIDE_Decompress_8K_Continue

SLIDE_Decompress_8K_CopyLoop:
	ldto_werp WA, 0x32
	add wa, iy
	and wa, 0x1FFF
	extz xwa
	addda32 xwa, 1570
	ld a, (xwa)
	extz wa
	ld e, a
	lda_dpi XIY, 0x38
	inc 1, xhl
	ld wa, bc
	inc 1, bc
	extz xwa
	addda32 xwa, 1570
	ld (xwa), e
	and bc, 0x1FFF
	inc 1, iy
	cp iy, iz
	jr ule, SLIDE_Decompress_8K_CopyLoop

SLIDE_Decompress_8K_Continue:
	cp xhl, xix
	jrl c, SLIDE_Decompress_8K_MainLoop

SLIDE_Decompress_8K_Done:
	ldda32 xwa, 1570
	push xwa
	call Free
	inc 4, xsp
	popw iz
	ret

SLIDE_Parse_Header:
	lda xsp, (xsp - 10)
	push xiz
	ld (xsp + 10), xbc
	ld xiz, xwa
	ld xiy, 0xE00032	; "SLIDE"
	lda xix, (xsp + 4)
	lds bc, 3
	ldirw
	pushw 0x5	; string length: 5 bytes
	lda xwa, (xsp + 6)
	push xwa
	push xiz
	call 0xFF0CC1
	add xsp, 0xA
	cps hl, 0
	jr nz, SLIDE_Parse_NotFound
	lda xwa, (xiz + 5)
	ld xiz, xwa
	ld a, (xwa)
	cp a, 0x34
	jr nz, SLIDE_Parse_Check8K
	inc 2, xiz
	ld xwa, xiz
	ld xbc, (xsp + 10)
	calr SLIDE_Decompress_4K_Init

SLIDE_Parse_ReturnOK:
	lds hl, 0
	jr SLIDE_Parse_Return

SLIDE_Parse_Check8K:
	cp a, 0x38
	jr nz, SLIDE_Parse_ReturnOK
	inc 2, xiz
	ld xwa, xiz
	ld xbc, (xsp + 10)
	calr SLIDE_Decompress_8K_Init
	jr SLIDE_Parse_ReturnOK

SLIDE_Parse_NotFound:
	ldw hl, 0xFFFF

SLIDE_Parse_Return:
	pop xiz
	lda xsp, (xsp + 10)
	ret

FDC_InitRecalibrate:
	lda xsp, (xsp - 16)
	lda xbc, (xsp)
	ldw (xbc), 0x0
	ldw (xbc + 2), 0x0
	ldw (xbc + 4), 0x0
	ldw (xbc + 6), 0xD3
	ldw (xbc + 8), 0x1
	ldw (xbc + 10), 0x1
	lds32 xwa, 0
	ld (xbc + 12), xwa
	push xbc
	call FDC_CommandEntry
	lda xsp, (xsp + 20)
	ret

FDC_SetupSectorParams:
	lda xsp, (xsp - 14)
	push xiz
	ld (xsp + 8), xde
	ld (xsp + 12), bc
	ld (xsp + 14), xwa
	ld xwa, (xsp + 14)
	ld xbc, 0x12
	call Math_DivideU32
	ldada xiz, 1582
	ldw (xiz + 2), 0x0
	ld wa, hl
	srl wa, 1
	ld (xiz + 6), wa
	and hl, 0x1
	ld (xiz + 4), hl
	lda xwa, (xiz + 8)
	ld (xsp + 4), xwa
	ld xwa, (xsp + 14)
	ld xbc, 0x12
	call DivMod32
	inc 1, xhl
	ld xwa, (xsp + 4)
	ld (xwa), hl
	ld wa, (xsp + 12)
	ld (xiz + 10), wa
	ld xwa, (xsp + 8)
	ld (xiz + 12), xwa
	pop xiz
	lda xsp, (xsp + 14)
	ret

FDC_ReadSectors:
	dec 6, xsp
	push xiz
	ld (xsp + 4), xde
	ld (xsp + 8), bc
	ld xiz, xwa

FDC_ReadSectors_Retry:
	ld xwa, xiz
	ld bc, (xsp + 8)
	ld xde, (xsp + 4)
	calr FDC_SetupSectorParams
	ldada xwa, 1582
	ldw (xwa), 0x3
	push xwa
	call FDC_CommandEntry
	inc 4, xsp
	cps hl, 0
	jr z, FDC_ReadSectors_Done
	calr FDC_InitRecalibrate
	jr FDC_ReadSectors_Retry

FDC_ReadSectors_Done:
	pop xiz
	inc 6, xsp
	ret

Detect_Disk_Type:	; EF42FE
	dec 2, xsp
	push xiz
	ld (xsp + 4), 0xFF
	pushw 0x200
	call Malloc
	inc 2, xsp
	ld xiz, xhl
	ld xwa, 0x21
	lds bc, 1
	ld xde, xiz
	calr FDC_ReadSectors
	pushw 0x26	; string length
	pushw 0xE0
	pushw 0x38	; "Technics KN5000 Program  DATA FILE 1/2"
	push xiz
	call 0xFF0CC1
	add xsp, 0xA
	cps hl, 0
	jr nz, DetectDisk_CheckProgram2of2
	ld (xsp + 4), 0x1
	jrl DetectDisk_FreeBufAndReturn

DetectDisk_CheckProgram2of2:
