	pushw 0xE0
	pushw 0x60	; "Technics KN5000 Program  DATA FILE 2/2"
	push xiz
	call 0xFF0CC1
	add xsp, 0xA
	cps hl, 0
	jr nz, DetectDisk_CheckTable1of2
