FDC_WriteSectors:
	lda xsp, (xsp - 16)
	push xiz
	ld (xsp + 14), xbc
	ld (xsp + 18), wa
	ld wa, (xsp + 18)
	ld (xsp + 6), wa
	ld wa, (xsp + 6)
	extz xwa
	div wa, 0x12
	ldto_werp WA, 0xE2
	lds iz, 0
	cps wa, 0
	jr z, FDC_WriteSectors_FullTracks
	ldw iz, 0x12
	sub iz, wa
	ld wa, (xsp + 6)
	extz xwa
	ld bc, iz
	ld xde, 0x69800
	calr FDC_ReadSectors
	lda_24 xwa, 0x069800
	ld (xsp + 10), xwa
	ldi_werp 0xFA, 0
	jr FDC_WriteSectors_TrackLoopCheck

FDC_WriteSectors_TrackLoop:
	ld xwa, (xsp + 14)
	st_dpib A, 0xE2
	ld (xsp + 14), xwa
	ld xwa, xbc
	ld xde, (xsp + 10)
	ld_spil XBC, 0xEA
	ld (xsp + 10), xde
	call Flash_ProgramByte
	inc1_werp 0xFA

FDC_WriteSectors_TrackLoopCheck:
	ld bc, iz
	sla bc, 7
	ldto_werp WA, 0xFA
	cp wa, bc
	jr c, FDC_WriteSectors_TrackLoop

FDC_WriteSectors_FullTracks:
	add (xsp + 6), iz
	ldw (xsp + 8), 0x800
	sub (xsp + 8), iz
	ld wa, (xsp + 8)
	exts xwa
	divs wa, 0x12
	ld (xsp + 8), wa
	ldw (xsp + 4), 0x0
	ld wa, (xsp + 8)
	cps wa, 0
	jr ule, FDC_WriteSectors_Remainder

FDC_WriteSectors_FullTrackOuter:
	ld wa, (xsp + 6)
	extz xwa
	ldw bc, 0x12
	ld xde, 0x69800
	calr FDC_ReadSectors
	addmi16 (xsp + 6), 0x12
	lda_24 xwa, 0x069800
	ld (xsp + 10), xwa
	ldi_werp 0xFA, 0

FDC_WriteSectors_FullTrackInner:
	ld xwa, (xsp + 14)
	st_dpib A, 0xE2
	ld (xsp + 14), xwa
	ld xwa, xbc
	ld xde, (xsp + 10)
	ld_spil XBC, 0xEA
	ld (xsp + 10), xde
	call Flash_ProgramByte
	inc1_werp 0xFA
	cp_erpw 0xFA, 0x00, 0x09
	jr c, FDC_WriteSectors_FullTrackInner
	incm 1, (xsp + 4)
	ld wa, (xsp + 8)
	cp (xsp + 4), wa
	jr c, FDC_WriteSectors_FullTrackOuter

FDC_WriteSectors_Remainder:
	ld wa, (xsp + 18)
	add wa, 0x800
	sub wa, (xsp + 6)
	ld iz, wa
	cps iz, 0
	jr z, FDC_WriteSectors_Return
	ld wa, (xsp + 6)
	extz xwa
	ld bc, iz
	ld xde, 0x69800
	calr FDC_ReadSectors
	lda_24 xwa, 0x069800
	ld (xsp + 10), xwa
	ldi_werp 0xFA, 0
	jr FDC_WriteSectors_RemainderCheck

FDC_WriteSectors_RemainderLoop:
	ld xwa, (xsp + 14)
	st_dpib A, 0xE2
	ld (xsp + 14), xwa
	ld xwa, xbc
	ld xde, (xsp + 10)
	ld_spil XBC, 0xEA
	ld (xsp + 10), xde
	call Flash_ProgramByte
	inc1_werp 0xFA

FDC_WriteSectors_RemainderCheck:
	ld bc, iz
	sla bc, 7
	ldto_werp WA, 0xFA
	cp wa, bc
	jr c, FDC_WriteSectors_RemainderLoop

FDC_WriteSectors_Return:
	pop xiz
	lda xsp, (xsp + 16)
	ret

FDC_WriteSectors_Compressed:
	lda xsp, (xsp - 18)
	push xiz
	ld (xsp + 14), xde
