	add xde, xbc
	ldw bc, 0x12
	calr FDC_ReadSectors
	adddi16 1618, 18
	inc 1, iz
	cps iz, 4
	jr c, Parport_RefillBuffer_Loop
	lda_24 xwa, 0x069800
	stda32 1610, xwa

Parport_ReadByte_Emit:
	ldda32 xwa, 1610
	st_dpib A, 0xE0
	stda32 1610, xwa
	ld l, (xbc)
	extz hl

Parport_ReadByte_Return:
	popw iz
	ret

Flash_AccumWrite_Byte:
	ldda8 e, 1620
	extz de
	ldada xbc, 1576
	extz xde
	add xde, xbc
	ld (xde), a
	ldda8 a, 1620
	ld e, a
	inc 1, a
	stda8 1620, a
	cps e, 3
	jr nz, Flash_AccumWrite_ByteDone
	ldda32 xwa, 1606
	st_dpib B, 0xE2
	stda32 1606, xwa
	ld xbc, (xbc)
	ld xwa, xde
	call Flash_ProgramByte
	stdi8 1620, 0

Flash_AccumWrite_ByteDone:
	lds32 xwa, 1
	adddm32 1602, xwa
	ret

Flash_AccumWrite_Word:
	ldda8 c, 1620
	extz bc
	ldada xde, 1580
	extz xbc
	add xbc, xde
	ld (xbc), a
	ldda8 a, 1620
	ld c, a
	inc 1, a
	stda8 1620, a
	cps c, 1
	jr nz, Flash_AccumWrite_WordDone
	ldda32 xwa, 1622
	st_dpib A, 0xE1
	stda32 1622, xwa
	ld de, (xde)
	lds wa, 1
	call Flash_ProgramWord
	stdi8 1620, 0

Flash_AccumWrite_WordDone:
	lds32 xwa, 1
	adddm32 1602, xwa
	ret

LZSS_Decompress_ToFlash:
	dec 6, xsp
	pushw iz
	stdi8 1620, 0
	lda_24 xwa, 0x300000
	add xwa, 0xE0000
	stda32 1622, xwa
	ld xwa, 0x20000
	adddm32 1598, xwa
	lds iz, 0

LZSS_Decompress_ReadHeader:
	calr Parport_ReadNextByte
	ld bc, iz
	extz xbc
	lda xwa, (xsp + 2)
	ld xde, xwa
	add xde, xbc
	ld (xde), l
	inc 1, iz
	cps iz, 6
	jr c, LZSS_Decompress_ReadHeader
	pushw 0x5	; lenght: 5 bytes
	pushw 0xE0
	pushw 0x188	; "SLIDE"
	push xwa
	call 0xFF0CC1
	add xsp, 0xA
	cps hl, 0
	jr z, LZSS_Decompress_HeaderOK
	ldw hl, 0xFFFF
	jr LZSS_Decompress_Return

LZSS_Decompress_HeaderOK:
	lds iz, 0

LZSS_Decompress_StreamHeaderBytes:
	ld bc, iz
	extz xbc
	lda xwa, (xsp + 2)
	add xwa, xbc
	ld a, (xwa)
	extz wa
	calr Flash_AccumWrite_Word
	inc 1, iz
	cps iz, 6
	jr c, LZSS_Decompress_StreamHeaderBytes
	stdi16 1614, 42
	stdi16 1616, 200
	ldda32 xwa, 1602
	cpda32 xwa, 1598
	jr nc, LZSS_Decompress_ReturnOK

LZSS_Decompress_StreamData:
	calr Parport_ReadNextByte
	extz hl
	ld wa, hl
	calr Flash_AccumWrite_Word
	ldda32 xwa, 1602
	cpda32 xwa, 1598
	jr c, LZSS_Decompress_StreamData

LZSS_Decompress_ReturnOK:
	lds hl, 0

LZSS_Decompress_Return:
	popw iz
	inc 6, xsp
	ret

LZ_Decompress_Init:
	lda xsp, (xsp - 16)
	push xiz
	pushw 0x1000
	call Malloc
	inc 2, xsp
	ld (xsp + 16), xhl
	ld xwa, (xsp + 16)
	ld (xsp + 12), xwa
	lds32 xwa, 0
	stda32 1602, xwa

LZ_Decompress_ClearRing:
	ldda32 xwa, 1602
	ld xbc, (xsp + 16)
	add xbc, xwa
	ld (xbc), 0x0
	ldda32 xwa, 1602
	inc 1, xwa
	stda32 1602, xwa
	cp xwa, 0xFEE
	jr c, LZ_Decompress_ClearRing
	ldw (xsp + 10), 0xFEE
	ldw (xsp + 4), 0x0
	stdi8 1620, 0
	lds32 xwa, 0
	stda32 1602, xwa
	lda_24 xwa, 0x069800
	stda32 1610, xwa
	ld xwa, 0x800000
	stda32 1606, xwa
	stdi16 1614, 50
	stdi16 1616, 180
	ldw wa, 0x32
	ldw bc, 0xB4
	lds de, 6
	call VRAM_FillRect
	ld xwa, 0x3E8
	stda32 1598, xwa
	stdi16 1618, 36
	ldi_werp 0xFA, 0

LZ_Decompress_ReadTracks:
	ldda16 xwa, 1618
	extz xwa
	ldw bc, 0x2400
	mul_werp BC, 0xFA
	ld xde, 0x69800
	add xde, xbc
	ldw bc, 0x12
	calr FDC_ReadSectors
	adddi16 1618, 18
	inc1_werp 0xFA
	cpi_werp 0xFA, 4
	jr c, LZ_Decompress_ReadTracks
	ldi_werp 0xFA, 0

LZ_Decompress_ReadSizeField:
	calr Parport_ReadNextByte
	inc1_werp 0xFA
	cp_erpw 0xFA, 0x08, 0x00
	jr c, LZ_Decompress_ReadSizeField
	calr Parport_ReadNextByte
	extz xhl
	sla xhl, 0
	stda32 1598, xhl
	calr Parport_ReadNextByte
	sll hl, 8
	extz xhl
	adddm32 1598, xhl
	calr Parport_ReadNextByte
	extz xhl
	ldda32 xwa, 1598
	add xwa, xhl
	stda32 1598, xwa
	cpdm32 1602, xwa
	jrl nc, LZ_Decompress_Done

LZ_Decompress_MainLoop:
	mrdw3 0x9F, 0x04, 0x7F
	ld wa, (xsp + 4)
	bit 8, wa
	jr nz, LZ_Decompress_LiteralByte
	calr Parport_ReadNextByte
	ld iz, hl
	cp iz, 0xFFFF
	jrl z, LZ_Decompress_Done
	ld (xsp + 4), iz
	ormi16 (xsp + 4), 0xFF00

LZ_Decompress_LiteralByte:
	ld wa, (xsp + 4)
	bit 0, wa
	jr z, LZ_Decompress_MatchRef
	calr Parport_ReadNextByte
	ld iz, hl
	cp iz, 0xFFFF
	jrl z, LZ_Decompress_Done
	ldto_berp A, 0xF8
	extz wa
	calr Flash_AccumWrite_Byte
	ld bc, (xsp + 10)
	incm 1, (xsp + 10)
	extz xbc
	add xbc, (xsp + 16)
	ldto_berp A, 0xF8
	ld (xbc), a
	andmi16 (xsp + 10), 0xFFF
	jr LZ_Decompress_LoopCheck

LZ_Decompress_MatchRef:
	calr Parport_ReadNextByte
	ldfr_werp HL, 0xFA
	cp_erpw 0xFA, 0xFF, 0xFF
	jr z, LZ_Decompress_Done
	calr Parport_ReadNextByte
	ld (xsp + 8), hl
	cpw (xsp + 8), 0xFFFF
	jr z, LZ_Decompress_Done
	ld bc, (xsp + 8)
	and bc, 0xF0
	sll bc, 4
	ldto_werp WA, 0xFA
	or wa, bc
	ldfr_werp WA, 0xFA
	andmi16 (xsp + 8), 0xF
	incm 2, (xsp + 8)
	ldw (xsp + 6), 0x0
	cpw (xsp + 8), 0x0
	jr c, LZ_Decompress_LoopCheck

LZ_Decompress_CopyMatchLoop:
	ldto_werp WA, 0xFA
	add wa, (xsp + 6)
	and wa, 0xFFF
	extz xwa
	add xwa, (xsp + 12)
	ld a, (xwa)
	ldfr_berp A, 0xF8
	extz iz
	ldto_berp A, 0xF8
	extz wa
	calr Flash_AccumWrite_Byte
	ld bc, (xsp + 10)
	incm 1, (xsp + 10)
	extz xbc
	add xbc, (xsp + 12)
	ldto_berp A, 0xF8
	ld (xbc), a
	andmi16 (xsp + 10), 0xFFF
	incm 1, (xsp + 6)
	ld wa, (xsp + 6)
	cp wa, (xsp + 8)
	jr ule, LZ_Decompress_CopyMatchLoop

LZ_Decompress_LoopCheck:
	ldda32 xwa, 1602
	cpda32 xwa, 1598
	jrl c, LZ_Decompress_MainLoop

LZ_Decompress_Done:
	ld xwa, (xsp + 16)
	push xwa
	call Free
	inc 4, xsp
	pop xiz
	lda xsp, (xsp + 16)
	ret

FLASH_MEM_UPDATE:	; EF4F6F
	push_werp 0xFA
	call Check_for_Floppy_Disk_Change
	cps l, 0
	jrl z, flash_update__not_today
	calr FDC_InitRecalibrate
	calr Detect_Disk_Type
	ldfr_berp L, 0xFB
	call 0xEF0865
	cps l, 4
	jr z, LABEL_EF4FE4
	call 0xEF3D0E
	cp xhl, 0xFFFFFFFF
	jr z, LABEL_EF4FE4
	cpi_berp 0xFB, 6	; Is it "HD-AEPRG DATA FILE"?
	jr z, LABEL_EF4FE4	; yes, it is.
	pushw 0x8
	pushw 0x2
	ld xwa, 0xE0018E	; "Flash Memory Update"
	ldw bc, 0x30
	ldw de, 0x50
	call Draw_FlashMemUpdate_message_bitmap
	ldto_berp A, 0xFB
	extz wa
	calr Erase_and_Burn____when_disk_is_valid
	pushw 0x8
	pushw 0x1
	ld xwa, 0xE008C6	; "Completed!"
	ldw bc, 0x30
	ldw de, 0xA0
	call Draw_FlashMemUpdate_message_bitmap
	pushw 0x8
	pushw 0x1
	ld xwa, 0xE01266	; "Turn On AGAIN !!"
	ldw bc, 0x30
	ldw de, 0xC8
	call Draw_FlashMemUpdate_message_bitmap

LABEL_EF4FE4:
	lds wa, 2
	call Flash_IdentifyAndValidateChip
	cp hl, 0xFFFF
	jr z, flash_update__not_today
	cpi_berp 0xFB, 6	; Is it "HD-AEPRG DATA FILE"?
	jr nz, flash_update__not_today
	pushw 0x8
	pushw 0x2
	ld xwa, 0xE0018E	; "Flash Memory Update"
	ldw bc, 0x30
	ldw de, 0x50
	call Draw_FlashMemUpdate_message_bitmap
	ldto_berp A, 0xFB
	extz wa
	calr Erase_and_Burn____when_disk_is_valid
	pushw 0x8
	pushw 0x1
	ld xwa, 0xE008C6	; "Completed!"
	ldw bc, 0x30
	ldw de, 0xA0
	call Draw_FlashMemUpdate_message_bitmap
	pushw 0x8
	pushw 0x1
	ld xwa, 0xE01266	; "Turn On AGAIN !!"
	ldw bc, 0x30
	ldw de, 0xC8
	call Draw_FlashMemUpdate_message_bitmap

flash_update__not_today:	; EF503C
	pop_werp 0xFA
	ret

; =============================================================================
; Draw_FlashMemUpdate_message_bitmap - Draw 224x22 monochrome bitmap
;
; Renders a 1bpp monochrome bitmap (224 pixels wide Ã— 22 pixels tall) to the
; offscreen buffer at 0x43C00, then blits the entire buffer to VRAM.
; Used to display firmware update status messages on the LCD.
;
; The bitmap is stored as packed 1bpp data (28 bytes per row Ã— 22 rows = 616
; bytes total). Each bit is unpacked to an 8bpp pixel using a bit mask table.
;
; Input:
;   XWA = pointer to bitmap data (24-bit, in ROM)
;   BC  = X start coordinate (left edge)
;   DE  = Y start coordinate (top edge)
;   Stack: foreground color (byte), background color (byte)
;
; Output:
;   Screen updated with rendered bitmap
; =============================================================================
Draw_FlashMemUpdate_message_bitmap:	; EF5040
	dec 4, xsp
	pushw iz
	ld hl, bc
	ld (xsp + 2), xwa
	ld iy, hl
	ld ix, de
	inc 1, ix
	lds iz, 0

LABEL_EF5050:
	ld wa, iz
	extz xwa
	div wa, 0x1C	; 28 bytes = 224 pixels de largura da imagem a ser desenhada
	ldto_werp WA, 0xE2
	cps wa, 0
	jr nz, LABEL_EF5063
	ld iy, hl	; IY = coordanada X do canto esquerdo da imagem a ser desenhada
	dec 1, ix

LABEL_EF5063:
	ldi_werp 0xEE, 0

LABEL_EF5066:
	ld de, iz
	extz xde
	add xde, (xsp + 2)
	ldada xwa, 58218	; table of bit masks (equivalent to 1044h on boot "table_data" rom)
	ldto_werp BC, 0xEE
	extz xbc
	add xbc, xwa	; indexing bit masks with value of QHL
	ld a, (xbc)
	and a, (xde)	; here XDE points at one of the bytes of the image we're drawing and we select the bit we need
	ldfr_berp A, 0xF2
	ld de, ix
	extz xde
	lda_24 xbc, 0x043c00                  ; aparentemente isso Ã© um buffer offscreen

; Convert Y coordinate to framebuffer row offset: XWA = XDE * 320
; Uses shift-add: (XDE << 2 + XDE) << 6 = XDE * 5 * 64 = XDE * 320
Set_XWA_to_320_times_XDE:
	ld xwa, xde
	sll xwa, 2		; XWA = Y * 4
	add xwa, xde		; XWA = Y * 5
	sll xwa, 6		; XWA = Y * 320
	cpi_berp 0xF2, 0
	jr z, LABEL_EF50AA
	ld de, iy
	inc 1, iy
	extz xde
	add xwa, xde
	ld xde, xbc
	add xde, xwa
	ld a, (xsp + 10)
	ld (xde), a
	jr LABEL_EF50BB

LABEL_EF50AA:
	ld de, iy
	inc 1, iy
	extz xde
	add xwa, xde	; XWA = 320*y + x
	ld xde, xbc
	add xde, xwa	; XDE = offscreen_buffer[320*y + x]
	ld a, (xsp + 12)
	ld (xde), a

LABEL_EF50BB:
	inc1_werp 0xEE
	cp_erpw 0xEE, 0x08, 0x00
	jr c, LABEL_EF5066
	inc 1, iz
	cp iz, 0x268	; 28 bytes (224 pixels/line) * 22 lines = 0268h bytes
	jr c, LABEL_EF5050
	lda_24 xwa, 0x1a0000
	ldw de, 0x9600	; 2 pixels per word
	call Copy_DE_words_from_XBC_to_XWA	; <-- "blit-screen"
	popw iz
	inc 4, xsp
	retd 0x4

;=============================================================================
; VRAM_FillRect - Fill a rectangular region in video RAM with a color
;
; Fills a 12-pixel tall rectangle in video RAM (0x1A0000) with the specified
; color value. Used for clearing or highlighting UI regions.
;
; Input:
;   BC = Y start coordinate (row)
;   WA = X start coordinate (column)
;   E  = Color/pattern value (8-bit, duplicated to 16-bit)
;
; Output:
;   None (VRAM modified)
;
; Clobbers: XIZ, XHL, XWA, XDE, IX, IY
;=============================================================================
VRAM_FillRect:	; EF50DF
	dec 6, xsp
	push xiz
	ld (xsp + 6), e	; Save color value
	ld (xsp + 8), wa	; Save X start
	ld ix, bc	; IX = Y start
	ld (xsp + 4), bc
	addmi16 (xsp + 4), 0xC	; End Y = start + 12
	cp ix, (xsp + 4)
	jr nc, VRAM_FillRect_Done

VRAM_FillRect_RowLoop:
	ld iy, (xsp + 8)	; IY = X start
	ld bc, iy
	inc 6, bc	; BC = X end (start + 6)
	cp iy, bc
	jr nc, VRAM_FillRect_NextRow

VRAM_FillRect_ColLoop:
	ld de, iy
	extz xde
	ld wa, ix
	extz xwa
	ld xhl, xwa
	sll xhl, 2
	add xhl, xwa
	sll xhl, 6
	add xhl, xde
	srl xhl, 1
	add xhl, xhl
	ld xiz, 0x1A0000
	add xiz, xhl
	ld a, (xsp + 6)
	extz wa
	ld de, wa
	sll de, 8
	or wa, de
	ld (xiz), wa
	inc 2, iy	; X += 2 (word increment)
	cp iy, bc
	jr c, VRAM_FillRect_ColLoop

VRAM_FillRect_NextRow:
	inc 1, ix	; Y++
	cp ix, (xsp + 4)
	jr c, VRAM_FillRect_RowLoop

VRAM_FillRect_Done:
	pop xiz
	inc 6, xsp
	ret

; =============================================================================
; VGA Register I/O Routines - Shared with table_data ROM
; =============================================================================
	.include "shared/vga_io.s"

; =============================================================================
; VGA Initialization Code - Shared with table_data ROM
; Uses macros and code from ../shared/vga_init.asm
; =============================================================================
	.include "shared/vga_init.s"
; Aliases for external references using original label names
.equ LABEL_EF5163, VGA_Extended_Init
.equ Some_VGA_setup, VGA_Setup

	; === ROM-specific ending: initialize video buffers ===
	call Fill_memory_at_XWA_with_DE_words_of_BC_value
	lda_24 xwa, 0x1a0000
	ld xbc, 0x43C00
	ldw de, 0x9600
	call Copy_DE_words_from_XBC_to_XWA	; Blit video buffer

	RET_VGA_SEQUENCER 0x1, 0x1	; Clocking Mode (screen on)


;=============================================================================
; Display_ResetDirtyFlags - Reset all display dirty flags
;
; Clears both the enable flag (0x205E6) and dirty bitmap (0x205E4) to zero.
; Call this to initialize display state or force a full refresh.
;=============================================================================
Display_ResetDirtyFlags:	; EF5B27
	sti16_24 0x0205e6, 0x0000
	sti16_24 0x0205e4, 0x0000
	ret

;=============================================================================
; Display_UpdateDirtyRegions - Update all dirty display regions
;
; Sets enable flag and checks each dirty bit. For each dirty region,
; calls the corresponding update routine. Used during main loop to
; refresh only changed portions of the display.
;
; Uses:
;   0x205E4 - DISPLAY_DIRTY_FLAGS: Bitmap of dirty regions
;   0x205E6 - DISPLAY_ENABLE_FLAG: Update enable flag
;=============================================================================
Display_UpdateDirtyRegions:	; EF5B36
	sti8_24 0x0205e6, 0x01
	cpdi16_24 132580, 0
	jr z, Display_MarkClean
	call Display_UpdateRegion0	; Status bar area
	call Display_UpdateRegion5	; Menu area
	call Display_UpdateRegion7	; Parameter display
	call Display_UpdateRegion8	; Value display
	call Display_UpdateRegion9	; Indicator area
	call Display_UpdateRegion1	; Title bar
	call Display_UpdateRegion10	; Footer area
	call Display_UpdateRegion6	; Button labels
	call Display_UpdateRegion3	; Main content area
	call Display_UpdateRegion4	; Side panel
	call Display_UpdateRegion2	; Selection highlight

Display_MarkClean:	; EF5B71
	sti16_24 0x0205e4, 0xffff
	ret

; Undisassembled data block (18 bytes) - possibly lookup table
Display_Data_EF5B79:	; EF5B79
	.byte 0x21, 0xff, 0xf2, 0xea, 0x05, 0x02, 0x41, 0xf2
	.byte 0xe8, 0x05, 0x02, 0x41, 0xf2, 0xec, 0x05, 0x02
	.byte 0x41, 0x0e

;-----------------------------------------------------------------------------
; Display_UpdateRegion0 - Update status bar region (bit 0)
;
; Checks if status bar needs refresh by comparing cached values.
; If changed, calls the status bar redraw routine.
;-----------------------------------------------------------------------------
Display_UpdateRegion0:	; EF5B8B
	bitda_24 0, 132582
	jr nz, Display_UpdateRegion0_Check
	setda_24 0, 132580
	ret

Display_UpdateRegion0_Check:	; EF5B98
	bitda_24 0, 132580
	jr z, Display_UpdateRegion0_Done
	pushw wa
	ldda8 a, 3429
	cpda8_24 a, 132586
	jr nz, Display_UpdateRegion0_Changed
	ldda8 a, 3567
	cpda8_24 a, 132584
	jr nz, Display_UpdateRegion0_Changed
	ldda8 a, 3424
	cpda8_24 a, 132588
	jr z, Display_UpdateRegion0_NoChange

Display_UpdateRegion0_Changed:	; EF5BC1
	bitda 0, 3927
	jrl nz, Display_UpdateRegion0_NoChange
	call Display_RedrawStatusBar
	ldda8 a, 3429
	st8_24 0x0205ea, a
	ldda8 a, 3567
	st8_24 0x0205e8, a
	ldda8 a, 3424
	st8_24 0x0205ec, a

Display_UpdateRegion0_NoChange:	; EF5BE7
	popw wa

Display_UpdateRegion0_Done:	; EF5BE8
	ret

;-----------------------------------------------------------------------------
; Display_UpdateRegion1 - Update title bar region (bit 1)
;-----------------------------------------------------------------------------
Display_UpdateRegion1:	; EF5BE9
	bitda_24 0, 132582
	jr nz, Display_UpdateRegion1_Check
	setda_24 1, 132580
	ret

Display_UpdateRegion1_Check:	; EF5BF6
	bitda_24 1, 132580
	jr z, Display_UpdateRegion1_Done
	call Display_RedrawTitleBar

Display_UpdateRegion1_Done:	; EF5C01
	ret

Display_UpdateRegion1_Alt:	; EF5C02
	call Display_RedrawAltContent
