SeMenu_SendEvent:
	dec 2, xsp
	ld (xsp), c
	cp (xsp), 0x0
	jr nz, SeMenu_SendEvent_Indirect
	extz wa
	call 0xF99490
	jr SeMenu_SendEvent_StoreAndReturn

SeMenu_SendEvent_Indirect:
	call LABEL_F994EA

SeMenu_SendEvent_StoreAndReturn:
	ld a, (xsp)
	extz wa
	calr SeMenu_StoreEventId
	inc 2, xsp
	ret

SeMenu_LoadRawAddr:
	ldmi16 (xwa), 0x8D38
	ret

SeMenu_TriggerNotification:
	stda8 32578, a
	stdi8 58332, 238
	setda 6, 58334
	ret

SeMenu_ClearNotification:
	stda8 58332, a
	setda 1, 58334
	ret

SeMenu_StoreEventId:
	stda8 1688, a
	ret

SeMenu_LoadObjectPtr_Data:
	.byte 0xb0, 0x14, 0x98, 0x06, 0x0e

SeMenu_LoadMasterPtr:
	ld8_24 c, 0x008d3a
	ld (xwa), c
	ret

SeMenu_FlushDisplayObj:
	ld xde, xwa
	ld xbc, xde
	ldada xhl, 1689
	lda xix, (xde + 9)

SeMenu_FlushDisplayObj_CopyLoop:
	ld_spib A, 0xE4
	lda_dpi XBC, 0xEC
	cp xbc, xix
	jr c, SeMenu_FlushDisplayObj_CopyLoop
	lds wa, 0
	lds bc, 6
	jp sendCOMM

SeMenu_RegisterElement_Extended:
	lda xsp, (xsp - 20)
	ld (xsp + 12), xde
	ld (xsp + 16), c
	ld (xsp + 18), a
	lda xbc, (xsp)
	ld xwa, xbc
	lda xbc, (xbc + 9)

SeMenu_RegisterElement_ClearLoop:
	stib_dpi 0xE0, 0x00
	cp xwa, xbc
	jr c, SeMenu_RegisterElement_ClearLoop
