SeMenu_InitObjEntry:
	dec 2, xsp
	push xiz
	ld xiz, xwa
	lda xwa, (xsp + 4)
	calr SeMenu_ValidatePartNumber
	ld a, (xsp + 4)
	ld (xiz), a
	sll a, 4
	ld (xiz), a
	incm8 1, (xiz)
	pop xiz
	inc 2, xsp
	ret

