	ld ix, de
	ldw bc, 0xFFFA
	add ix, bc
	ld bc, de
	ld_srib3 C, 0x07, 0xEC, 0xE4
	lda_dri3 XHL, 0x07, 0xE0, 0xF0
	inc1_berp 0xEA
	inc 1, de
	ldto_berp C, 0xEA
	cp_berp C, 0xE6
	jr c, SeMenu_FillEntryTable_Loop
	ret

SeMenu_FillObjTable:
	ld xhl, xwa
	lda_24 xde, 0x020c39
	ld xbc, xde
	lda xde, (xde + 25)

SeMenu_FillObjTable_Loop:
	ld_spib A, 0xE4
	lda_dpi XBC, 0xEC
	cp xbc, xde
	jr c, SeMenu_FillObjTable_Loop
	ret

