	lda xsp, (xsp - 38)
	push_werp 0xFA
	lda xwa, (xsp + 38)
	call SeMenu_ReadObjData
	cp (xsp + 38), 0x0
	jr nz, SeMenu_AltUpdate_Step1
	ldi_berp 0xFB, 1

SeMenu_AltUpdate_RegLoop:
	ldto_berp A, 0xFB
	extz wa
	pushw 0x22
	ldw bc, 0x17
	lds de, 1
	call SeMenu_RegisterElement_Type1
	ldto_berp A, 0xFB
	extz wa
