	push xhl
	ldda32 xhl, 6701
	stda16 6699, xhl
	pop xhl
	call Vga_RestoreMultiPlaneDisplay
	ldda8 a, 4599
	st8_24 0x00ffe3, a
	call SoundBank_LoadToWorkRAM
	call SeqPlay_StartWithDisplay
	jr __jrt_nop_F28238
