TrAsGridChk_HandleResizeEvent:
	lda xbc, (xsp + 14)
	ld xwa, xiz
	srl xwa, 0
	ldi_werp 0xE2, 0
	ld (xbc), wa
	lda xwa, (xbc + 2)
	ld de, iz
	ld (xwa), de
	lda xde, (xsp + 4)
	ld (xbc + 4), xde
	ld bc, (xbc)
	ld wa, (xwa)
	cps bc, 3
	jrl z, TrAsGridChk_Part3_Start
	cps bc, 2
	jr z, TrAsGridChk_Part2_Start
	cps bc, 1
	jrl nz, TrAsGridChk_ReturnZero
	call 0xFA44D0
	ld xwa, xhl
	ld xbc, 0x1E0008F
	lds32 xde, 0
	call 0xFA9660
	ld wa, (xsp + 16)
	ld bc, wa
	cp bc, hl
	jr nz, TrAsGridChk_Part1_AdjustDown
	ld8_24 l, 0x021082
	jr TrAsGridChk_Part1_SendAudio

TrAsGridChk_Part1_AdjustDown:
	bitda 0, 3296
	jr nz, TrAsGridChk_Part1_AdjustUp
	dec 2, a
	extz wa
	calr TrAsGrid_LookupByteTable
	jr TrAsGridChk_Part1_SendAudio

TrAsGridChk_Part1_AdjustUp:
	inc 6, a
	extz wa
	calr TrAsGrid_LookupByteTable

TrAsGridChk_Part1_SendAudio:
	extz hl
	sla hl, 2
	ld xbc, 0xE262CA
	ld_sril3 XWA, 0x07, 0xE4, 0xEC
	push xwa
	lda xwa, (xsp + 8)
	push xwa
	call Audio_SendCommand
	inc 8, xsp
	call 0xFA44D0
	ld xwa, xhl
	lda xde, (xsp + 14)
	ld xbc, 0x1E0008C
	jrl TrAsGridChk_DispatchAndReturn

