SeqPart_CountEventsInRange:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xbc
	ld xiz, xwa
	stdi8 10362, 0
	call SeqVoice_FindDrumPartIndex
	ldda8 a, 9810
