	ld xwa, (xsp + 4)
	incm 1, (xwa)
	call PartCtrl_AdvanceReadPos
	cpdi8 10362, 0
	jr z, SeqPart_CountCheckEnd
	jr SeqPart_CountBoundary

SeqPart_CountError:
