	cp l, 0x82
	jr nz, SeqPart_StepCountCheck
	ld bc, iz
	extz xbc
	lds32 xwa, 0
	ldda8 a, 10382
	sub xwa, xbc
	stda32 9690, xwa
	lds iz, 0
	cpdi16 10228, 0
	jr z, SeqPart_StepCountError

SeqPart_StepCountAdvance:
