	ldada xbc, 3311
	ldmm_sriw 0x07, 0xE4, 0xE0, 0xAF, 0x28
	ldmm16 9820, 10415
	ldda8 a, 9810
	dec 1, a
	extz wa
	add wa, wa
	ldada xbc, 3343
	ldmm_sriw 0x07, 0xE4, 0xE0, 0x66, 0x26
	ldmm16 9822, 9830
	ldw wa, 0x82
	call PartCtrl_WriteByte_Indexed
	ldda8 a, 9810
	extz wa
	stda16 10365, xwa
	ldda16 xwa, 9822
	ld c, a
