DrumSlot_Dispatch:
	cp hl, 0xA
	jr c, DrumSlot_ClampAndLookup
	lds hl, 0

DrumSlot_ClampAndLookup:
	ld xiy, 0xF64D75
	pushw hl
	sll hl, 2
	ld_sril3 XWA, 0x07, 0xF4, 0xEC
	popw hl
	call (xwa)
