; --- Bitmap_QueryProperties: Return dimensions/data for 3 bitmap resources ---
; Three identical query handlers. Each checks XBC for property ID:
;   0x1E000A1 -> return data pointer (lda_24 xhl, addr)
;   0x1E000A2 -> return width  (XHL = 22)
;   0x1E000A3 -> return height (XHL = 222)
;   other     -> return 0 (not handled)
; The three copies reference different bitmap data addresses:
;   0xE8E66A, 0xE8F97E, 0xE90C92 (in Table Data ROM).
LABEL_F7B4F1:
	cp	xbc, 31457443
	jr	z, 31
	cp	xbc, 31457442
	jr	z, 17
	cp	xbc, 31457441
	jr	z, 3
	lds32	xhl, 0
	ret
	lda_24	xhl, 15255146
	ret
	ld	xhl, 22
	ret
	ld	xhl, 222
	ret
	cp	xbc, 31457443
	jr	z, 31
	cp	xbc, 31457442
	jr	z, 17
	cp	xbc, 31457441
	jr	z, 3
	lds32	xhl, 0
	ret
	lda_24	xhl, 15260030
	ret
	ld	xhl, 22
	ret
	ld	xhl, 222
	ret
	cp	xbc, 31457443
	jr	z, 31
	cp	xbc, 31457442
	jr	z, 17
	cp	xbc, 31457441
	jr	z, 3
	lds32	xhl, 0
	ret
	lda_24	xhl, 15264914
	ret
	ld	xhl, 22
	ret
	ld	xhl, 222
	ret


