	cp xwa, (xsp + 8)
	jrl nz, LABEL_F84332
	ld xwa, (xhl + 42)
	cpw (xwa), 0x1
	jrl nz, LABEL_F84332
	lds32 xhl, 1
	jr LABEL_F84506

LABEL_F844FA:
	ld xwa, (xsp + 12)
	ld xbc, xiz
	ld xde, (xsp + 8)

LABEL_F84502:
	call 0xFA4409

LABEL_F84506:
	pop xiz
	lda xsp, (xsp + 12)
	ret

AcPresentationControlProc:
	dec 8, xsp
	push xiz
	ld (xsp + 4), xde
	ld (xsp + 8), xbc
	ld xiz, xwa
	ld xbc, (xsp + 8)
	cp xbc, 0x1C0001C
	jrl z, AcPresentCtrl_CheckSSFStart
	ld xwa, (xsp + 8)
	cp xwa, 0x1C10006
	jrl z, LABEL_F845F6
	cp xwa, 0x1C10005
	jrl z, LABEL_F845D8
	sub xbc, 0x1C00002
	cp xbc, 0x0
	jrl lt, LABEL_F8468B
	cp xbc, 0xA
	jrl gt, LABEL_F8468B
	add xbc, xbc
	add xbc, 0xE9F9B2
	ld bc, (xbc)
	lda_24 xix, 0xf84563
	jp_dri 8, 0x07, 0xF0, 0xE4
LABEL_F84563:
	; --- AcPresentationControlProc jump table handler body ---
	; Handles events 0x1C00002-0x1C0000C via jump table at 0xE9F9B2.
	; Dispatches presentation control events: start, register handlers,
	; broadcast state changes.
	ld xwa, xiz				; workspace
	ld xbc, (xsp + 8)			; event code
	ld xde, (xsp + 4)			; event param
	call 0xFA4409				; forward event to handler
	call 0xFA4D1F				; additional processing
	cp xhl, 0x01800013			; check return code
	jrl z, LABEL_F84687			; matched -- exit
	lds	wa, 2
	jr LABEL_F845D1				; skip to call FAF2C7
	ld xwa, 0x02600024			; workspace for SendEvent
	ld xbc, 0x01E00029			; presentation control event
	ld xde, (xsp + 4)			; event param
	call 0xFA9660				; SendEvent (direct)
	cp hl, 0x000F				; check result count
	jrl nz, LABEL_F84687			; exit if not 0x0F
	ld xwa, 0x0120000B			; register event handler workspace
	ld xbc, 0x01E000AC			; register event code AC
	lds32	xde, 0
	call 0xFA49B7				; register event handler
	call 0xF86A47				; additional presentation setup
	ld xwa, 0x0120000B
	ld xbc, 0x01E000AD			; register event code AD
	lds32	xde, 0
	call 0xFA49B7				; register event handler
	ld xwa, 0xFFFFFFFF			; broadcast target
	ld xbc, 0x01C00015			; presentation state event
	ld xde, 0x01A000E0			; event param
	call 0xFA9752				; dispatch event
	lds	wa, 2
LABEL_F845D1:
	call 0xFAF2C7				; presentation helper
	jrl LABEL_F84687			; exit


LABEL_F845D8:
	ld xwa, xiz
	ld xbc, (xsp + 8)
	ld xde, (xsp + 4)
	call 0xFA4409
	ld xwa, 0x1210028
	ld xbc, (xsp + 8)
	ld xde, (xsp + 4)
	call 0xFA49B7
	jrl LABEL_F84687

LABEL_F845F6:
	ld xwa, xiz
	ld xbc, (xsp + 8)
	ld xde, (xsp + 4)
	call 0xFA4409
	ld xwa, 0x1210028
	ld xbc, (xsp + 8)
	ld xde, (xsp + 4)
	call 0xFA49B7
	lds wa, 2
	call 0xFAF2C7
	ld xwa, 0xE40000
	ld xbc, 0x1C00001
	lds32 xde, 0
	jr LABEL_F8464A

; Handler for event 0x1C0001C within AcPresentationControlProc.
; Checks the workspace type-tag: *(XDE) must equal 0x0000B80A for SSF to start.
; If the check passes, sends event 0x1C00006 to begin SSF presentation parsing.
; If it fails (wrong type-tag), the SSF system never starts and no demo images appear.
;
; MAME investigation (Feb 2026): this check ALWAYS fails because the workspace
; value 0x0000B80A is only produced by GroupBoxProc_StartSSFPresentation (FA9660
; direct path), which is not reached during Feature Demo navigation in MAME.
; The events that DO arrive here come from DemoMenu_BuildItemWorkspace (queued via
; FA9D58), whose workspace values are in the 0x82xx-range and never equal 0xB80A.
AcPresentCtrl_CheckSSFStart:
	ld xwa, xiz
	ld xbc, (xsp + 8)
	ld xde, (xsp + 4)
	call 0xFA4409
	ld xbc, (xsp + 4)
	ld xwa, (xbc)
	cp xwa, 0xB80A
	jr nz, LABEL_F84687
	ld de, (xbc + 4)
	exts xde
	ld xwa, xiz
	ld xbc, 0x1C00006

LABEL_F8464A:
	call 0xFA9660
	jr LABEL_F84687
	ld xwa, xiz
	ld xbc, (xsp + 8)
	ld xde, (xsp + 4)
	call 0xFA4409
	sti16_24 0x0340fc, 0x0000
	sti16_24 0x0340fa, 0x0000
	sti16_24 0x0340fe, 0x0000
	ld xwa, 0x1210028
	ld xbc, (xsp + 8)
	ld xde, (xsp + 4)
	call 0xFA49B7
	ldw wa, 0x8
	call Audio_DispatchCommand

LABEL_F84687:
	lds32 xhl, 0
	jr LABEL_F84697

LABEL_F8468B:
	ld xwa, xiz
	ld xbc, (xsp + 8)
	ld xde, (xsp + 4)
	call 0xFA4409

LABEL_F84697:
	pop xiz
	inc 8, xsp
	ret

LABEL_F8469B:
	ld de, wa
	exts xde
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C10005
	jp 0xFA9D58

LABEL_F846AD:
	ld de, wa
	exts xde
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C10006
	jp 0xFA9D58

