	jr z, FDemoText_ParseCtrl_SecondHalf
	cp a, 0x82
	ret nz
	ld e, (xbc + 2)
	ld c, (xbc + 7)
	and c, 0xF
	extz bc
	cp e, 0x82
	jr z, FDemoText_ParseCtrl_Type82
	cps e, 2
	jr nz, FDemoText_ParseCtrl_SecondHalf
	lds wa, 6
	call DemoMenu_BuildItemWorkspace
	ld8_24 a, 0x020c39
	srl a, 4
	and a, 0xF
	ld c, a
	extz bc
	lds wa, 2
	call DemoMenu_BuildItemWorkspace
	ld8_24 c, 0x020c39
	and c, 0xF
	extz bc
	lds wa, 0
	jr FDemoText_ParseCtrl_BuildWorkspace

