FDemoText_ScaleDownCoords:
	ld de, (xwa)
	exts xde
	divs de, 0x8
	ld (xbc), de
	ld wa, (xwa + 2)
	exts xwa
	divs wa, 0x4
	ld (xbc + 2), wa
	ret

FDemoText_ScaleUpCoords:
	ld de, (xwa)
	sla de, 3
	ld (xbc), de
	ld wa, (xwa + 2)
	sla wa, 2
	inc 3, wa
	ld (xbc + 2), wa
	ret

FDemoText_CalcTextExtent:
	dec 8, xsp
	push xiz
	ld xiz, xwa
	lda xbc, (xsp + 8)
	ld xwa, xiz
	calr FDemoText_ScaleDownCoords
	lda xwa, (xsp + 8)
	lda xbc, (xsp + 4)
	calr FDemoText_ScaleUpCoords
	lda xwa, (xsp + 8)
	ld ix, (xwa)
	inc 1, ix
	ld hl, (xsp + 4)
	inc 8, hl
	sub hl, (xiz)
	cp ix, 0x28
	jr ge, FDemoText_CalcExtent_Done
	ld wa, (xwa + 2)
	muls wa, 0x28
	lda_24 xde, 0x0251da

FDemoText_CalcExtent_ScanLoop:
	ld bc, wa
	add bc, ix
	cp_srib_im 0x07, 0xE8, 0xE4, 0x54
	jr nz, FDemoText_CalcExtent_Done
	inc 8, hl
	inc 1, ix
	cp ix, 0x28
	jr lt, FDemoText_CalcExtent_ScanLoop

FDemoText_CalcExtent_Done:
	pop xiz
	inc 8, xsp
	ret

FDemoText_UpdateCursorPosition:
	dec 4, xsp
	pushw iz
	lda xbc, (xsp + 2)
	ld xwa, 0x25B3A
	calr FDemoText_ScaleDownCoords
	ld16_24 xwa, 0x025b3e
	sla wa, 2
	lda_24 xbc, 0x025b40
	ld_sril3 XWA, 0x07, 0xE4, 0xE0
	call 0xFB2624
	ld iz, hl
	ld16_24 xwa, 0x025b3e
	sla wa, 2
	lda_24 xbc, 0x025b40
	ld_sril3 XWA, 0x07, 0xE4, 0xE0
	call 0xFB260A
	add hl, iz
	exts xhl
	divs hl, 0x4
	inc 1, hl
	lda xwa, (xsp + 2)
	lda xde, (xwa + 2)
	ld bc, (xde)
	add bc, hl
	ld (xde), bc
	cp bc, 0x3C
	jr ge, FDemoText_FindCursor_NotFound
	ldw iy, 0xFFFF
	ld iz, (xwa)
	lda_24 xix, 0x0251da
	muls bc, 0x28
	ld hl, bc
	cps iz, 0
	jr le, FDemoText_FindCursor_LeftDone
	ld bc, iz
	ld de, hl
	add de, bc

FDemoText_FindCursor_SearchLeft:
	dec 1, iz
	dec 1, de
	cp_srib_im 0x07, 0xF0, 0xE8, 0x54
	jr nz, FDemoText_FindCursor_LeftDone
	ld iy, iz
	cps iz, 0
	jr gt, FDemoText_FindCursor_SearchLeft

FDemoText_FindCursor_LeftDone:
	cp iy, 0xFFFF
	jr nz, FDemoText_FindCursor_StoreResult
	cp iz, 0x28
	jr ge, FDemoText_FindCursor_StoreResult

FDemoText_FindCursor_SearchRight:
	ld bc, hl
	add bc, iz
	cp_srib_im 0x07, 0xF0, 0xE4, 0x54
	jr nz, FDemoText_FindCursor_RightNext
	ld iy, iz
	jr FDemoText_FindCursor_StoreResult

FDemoText_FindCursor_RightNext:
	inc 1, iz
	cp iz, 0x28
	jr lt, FDemoText_FindCursor_SearchRight

FDemoText_FindCursor_StoreResult:
	cp iy, 0xFFFF
	jr z, FDemoText_FindCursor_NotFound
	ld (xwa), iy
	ld xbc, 0x25B3A
	calr FDemoText_ScaleUpCoords
	lds hl, 1
	jr FDemoText_FindCursor_Return

FDemoText_FindCursor_NotFound:
	lds hl, 0

FDemoText_FindCursor_Return:
	popw iz
	inc 4, xsp
	ret

FDemoText_RenderTextLine:
	lda xsp, (xsp - 32)
	push xiz
	ld (xsp + 32), xwa
	ld xiy, 0xE9FFFC
	lda xix, (xsp + 24)
	lds bc, 4
	ldirw
	ld16_24 xwa, 0x025b3e
	sla wa, 2
	lda_24 xbc, 0x025b40
	ld_sril3 XWA, 0x07, 0xE4, 0xE0
	call 0xFB260A
	ld iz, hl
	ld16_24 xwa, 0x025b3e
	sla wa, 2
	lda_24 xbc, 0x025b40
	ld_sril3 XWA, 0x07, 0xE4, 0xE0
	call 0xFB2617
	sub iz, hl
	lda_24 xde, 0x025b3c
	ld bc, (xde)
	ld wa, bc
	sub wa, iz
	jr ge, FDemoText_Layout_Setup
	neg wa
	inc 3, wa
	exts xwa
	divs wa, 0x4
	sla wa, 2
	add bc, wa
	ld (xde), bc

FDemoText_Layout_Setup:
	ld xiy, 0x25B3A
	lda xix, (xsp + 20)
	ldiw
	ldiw
	sub (xsp + 22), iz
	ld xwa, (xsp + 32)
	push xwa
	call Strlen
	ldfr_werp HL, 0xFA
	ldto_werp WA, 0xFA
	inc 1, wa
	pushw wa
	call Malloc
	ld (xsp + 22), xhl
	ld xwa, (xsp + 38)
	push xwa
	ld xwa, (xsp + 26)
	push xwa
	call Strcpy
	lda xsp, (xsp + 14)
	ld xwa, (xsp + 16)
	ld (xsp + 6), xwa
	lda xwa, (xsp + 20)
	calr FDemoText_CalcTextExtent
	ld (xsp + 4), hl
	ld16_24 xwa, 0x025b3e
	sla wa, 2
	lda_24 xbc, 0x025b40
	ld_sril3 XBC, 0x07, 0xE4, 0xE0
	ld xwa, (xsp + 16)
	ld de, (xsp + 4)
	call 0xFB275A
	ld iz, hl
	cp_werp IZ, 0xFA
	jr z, FDemoText_Layout_NoWrap
	ldw (xsp + 14), 0x1
	ld xwa, (xsp + 16)
	st_dri3b W, 0x07, 0xE0, 0xF8
	ld (xsp + 10), xwa
	lds32 xwa, 1
	sub (xsp + 10), xwa
	cps iz, 0
	jr z, FDemoText_Layout_ProcessLine
	ld xwa, (xsp + 10)
	ld (xwa), 0x0
	jr FDemoText_Layout_ProcessLine

FDemoText_Layout_NoWrap:
	ldw (xsp + 14), 0x0

FDemoText_Layout_ProcessLine:
	ld16_24 xwa, 0x025b3e
	sla wa, 2
	lda_24 xbc, 0x025b40
	ld_sril3 XBC, 0x07, 0xE4, 0xE0
	ld xwa, (xsp + 6)
	call 0xFB26D1
	ld (xsp + 8), hl
	cps iz, 0
	jr z, FDemoText_Layout_UpdatePosition
	lda_24 xbc, 0x025b74
	ld16_24 xwa, 0x025b72
	ld_srib3 A, 0x07, 0xE4, 0xE0
	lda xbc, (xsp + 20)
	cps a, 2
	jr z, FDemoText_Layout_AlignRight
	cps a, 1
	jr z, FDemoText_Layout_DrawText
	cps a, 0
	jr nz, FDemoText_Layout_DrawText
	ld de, (xsp + 4)
	exts xde
	divs de, 0x2
	add de, (xbc)
	ld wa, (xsp + 8)
	exts xwa
	divs wa, 0x2
	sub de, wa
	ld (xbc), de
	jr FDemoText_Layout_DrawText

FDemoText_Layout_AlignRight:
	ld wa, (xbc)
	add wa, (xsp + 4)
	sub wa, (xsp + 8)
	ld (xbc), wa

FDemoText_Layout_DrawText:
	lda xwa, (xsp + 24)
	lda xbc, (xsp + 20)
	ld16_24 xde, 0x025b3e
	sla de, 2
	lda_24 xhl, 0x025b40
	ld_sril3 XDE, 0x07, 0xEC, 0xE8
	push xde
	ld16_24 xde, 0x025b60
	sla de, 1
	lda_24 xhl, 0x025b62
	push_sriw 0x07, 0xEC, 0xE8
	pushw 0xF7
	ld xde, (xsp + 24)
	call 0xFACACA

FDemoText_Layout_UpdatePosition:
	ld wa, (xsp + 20)
	add wa, (xsp + 8)
	st16_24 0x025b3a, xwa
	cpw (xsp + 14), 0x0
	jr z, FDemoText_Layout_FreeBuffer
	calr FDemoText_UpdateCursorPosition
	cps hl, 0
