; =============================================================================
; Display region save/restore functions (F87AF6-F87EAC)
;
; 8 functions that save display region data to external memory or VRAM.
; Each follows the pattern: check available space via F89556, open resource
; via F891AB/F88BC7, configure ranges via F88E28, finalize via F88C48.
; Plus 1 simpler function (F87E00) that calls F187F3.
; Resource IDs: 0xEA01F0 through 0xEA020C (one per region).
; Returns HL=0xFF9B on insufficient space.
; =============================================================================
LABEL_F87AF6:
	; --- Save region 0: VRAM F980-FFC0, ext mem 1E7800-1E8000 ---
	lda xsp, (xsp - 22)
	push xiz
	ld (xsp + 22), xwa			; save arg
	ldada	xbc, 65472
	ldada	xwa, 63872
	ld (xsp + 4), xbc			; save end address
	sub (xsp + 4), xwa			; size = end - start
	lda_24 xbc, 0x1E7800
	lda_24 xiz, 0x1E8000
	sub xiz, xbc				; VRAM size
	call 0xF89556				; get available space
	ld xwa, (xsp + 4)			; total size needed
	add xwa, xiz
	cp xhl, xwa				; enough space?
	jr ge, LABEL_F87B29			; yes
	ldw hl, 0xFF9B				; error: insufficient space
	jr LABEL_F87B83				; return error
LABEL_F87B29:
	lda xwa, (xsp + 8)			; local buffer
	ld xbc, (xsp + 22)			; saved arg
	lds	de, 0
	call 0xF891AB				; init region
	lda xwa, (xsp + 8)			; buffer
	ld xbc, 0x00EA01F0			; resource ID region 0
	call 0xF88BC7				; open resource
	cps hl, 0
	jr ge, LABEL_F87B4B			; success
	call 0xF88BC2				; close/cleanup
	jr LABEL_F87B83				; return error
LABEL_F87B4B:
	call 0xFDB48E				; pre-save hook
	ld xwa, 0x0000F980			; VRAM start
	ld xbc, (xsp + 4)			; VRAM size
	call 0xF88E28				; save range 1
	ld xwa, 0x001E7800			; ext mem start
	ld xbc, xiz				; ext mem size
	call 0xF88E28				; save range 2
	call 0xF88BC2				; close
	ld iz, hl				; save status
	ld wa, iz
	call 0xFDB48F				; post-save hook
	call FileIO_CloseHandle			; finalize
	cps iz, 0
	jr ge, LABEL_F87B81			; success
	lda xwa, (xsp + 8)
	call 0xF88C60				; error cleanup
LABEL_F87B81:
	ld hl, iz				; return status
LABEL_F87B83:
	pop xiz
	lda xsp, (xsp + 22)
	ret

LABEL_F87B88:
	; --- Save region 1: VRAM at 1ED350, conditional size ---
	lda xsp, (xsp - 18)
	push xiz
	ld (xsp + 18), xwa			; save arg
	call 0xF893AB				; get display mode
	lda_24 xbc, 0x1ED350			; base address
	cps l, 0				; check mode
	jr z, LABEL_F87BAC			; mode 0 path
	ld iz, (xbc + 13)			; get size param
	extz xiz
	sla xiz, 3				; * 8
	add xiz, 0x000000B0			; + 0xB0 base size
	jr LABEL_F87BB3
LABEL_F87BAC:
	lda_24 xiz, 0x200000			; full range
	sub xiz, xbc				; size = 0x200000 - 0x1ED350
LABEL_F87BB3:
	call 0xF89556				; get available space
	cp xhl, xiz				; enough?
	jr ge, LABEL_F87BC0
	ldw hl, 0xFF9B
	jr LABEL_F87C3B
LABEL_F87BC0:
	lda xwa, (xsp + 4)			; buffer
	ld xbc, (xsp + 18)			; arg
	lds	de, 1
	call 0xF891AB
	lda xwa, (xsp + 4)
	ld xbc, 0x00EA01F4			; resource ID region 1
	call 0xF88BC7
	cps hl, 0
	jr ge, LABEL_F87BE2
	call 0xF88BC2
	jr LABEL_F87C3B
LABEL_F87BE2:
	call 0xF893AB				; re-check mode
	cps l, 0
	jr z, LABEL_F87C0F			; mode 0 path
	ld xwa, 0x001ED350
	ld xbc, xiz
	call 0xF88E28				; save VRAM range
	ld xwa, 0x0000000F			; param
	lds	bc, 0
	call 0xF88EE0				; set region param
	ldw wa, 0x0008
	call 0xF88D2C				; configure
	call 0xF88BC2
	ld iz, hl
	jr LABEL_F87C2A
LABEL_F87C0F:
	call 0xFDB49E				; alternate pre-save
	ld xwa, 0x001ED350
