	stda32 32580, xhl
	or xhl, xhl
	jr nz, FileIO_OpenMode_Success
	cp (xiz), 0x72
	jr nz, FileIO_OpenMode_CheckWrite
	stdi16 32584, 65534
	ldw hl, 0xFFFE
