; =============================================================================
; IvOneShotTimerProc - Single-shot timer event processor
;
; Manages timer-driven animation events. Used for delayed UI updates,
; animation frame ticks, and timed transitions.
;
; Events handled:
;   0x1C00001 - Create: set up timer, register tick event (0x1E50008)
;   0x1C0000D - Destroy: cancel timer (event 0x1C0000F)
;   0x1E0003A - Timer query: call Strcpy with params (0x9894, 0xEA)
;   0x1E50009 - Schedule next tick: queue event 0x1E5000A
;   0x1E5000A - Timer fired: invoke registered callback via workspace +22
;
; Workspace layout:
;   +22: long - callback function pointer
; =============================================================================
IvOneShotTimerProc:
	lda xsp, (xsp - 12)
	push xiz
	ld (xsp + 8), xde
	ld xiz, xbc
	ld (xsp + 12), xwa
	cp xiz, 0x1E5000A
	jrl z, IvTimer_HandleEvent0A
	cp xiz, 0x1E50009
	jr z, IvTimer_HandleEvent09
	cp xiz, 0x1E0003A
	jr z, IvTimer_HandleEvent3A
	cp xiz, 0x1C0000D
	jr z, IvTimer_HandleDestroy
	cp xiz, 0x1C00001
	jr z, IvTimer_HandleCreate
	ld xwa, (xsp + 12)
	ld xbc, xiz
	ld xde, (xsp + 8)
	call 0xFA4409
	jrl IvTimer_Cleanup

IvTimer_HandleCreate:
	ld xwa, (xsp + 12)
	ld xbc, xiz
	ld xde, (xsp + 8)
	call 0xFA4409
	ld xwa, (xsp + 12)
	call 0xFA6266
	ld xde, (xsp + 12)
	ld xwa, (xhl + 22)
	ld xbc, 0x1E50008
	jr IvTimer_CallMainFunc

IvTimer_HandleDestroy:
	ld xwa, (xsp + 12)
	ld xbc, xiz
	ld xde, (xsp + 8)
	call 0xFA4409
	ld xwa, (xsp + 12)
	ld xbc, 0x1C0000F
	lds32 xde, 0
	call 0xFA9660
	jr IvTimer_ReturnZero

IvTimer_HandleEvent3A:
	pushw 0xEA
	pushw 0x9894
	ld xwa, (xsp + 12)
	push xwa
	call Strcpy
	inc 8, xsp
	jr IvTimer_ReturnZero

IvTimer_HandleEvent09:
	ld xwa, 0x1E5000A
	push xwa
	lds32 xwa, 0
	push xwa
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 20)
	ld xde, (xsp + 20)
	call 0xFAA135
	jr IvTimer_ReturnZero

IvTimer_HandleEvent0A:
	ld xwa, (xsp + 12)
	call 0xFA6266
	ld (xsp + 4), xhl
	push xiz
	ld xwa, (xsp + 12)
	push xwa
	lds32 xwa, 0
	ld xbc, (xsp + 20)
	ld xde, (xsp + 20)
	call 0xFAA257
	ld xwa, (xsp + 4)
	ld xwa, (xwa + 22)
	ld xbc, xiz
	ld xde, (xsp + 8)

IvTimer_CallMainFunc:
	call 0xFA4A63

IvTimer_ReturnZero:
	lds32 xhl, 0

IvTimer_Cleanup:
	pop xiz
	lda xsp, (xsp + 12)
	ret

