	jrl z, Slider_Event1E00068
	cp xiz, 0x1C50002
	jrl z, Slider_Event1E00068
	cp xiz, 0x1C0001A
	jrl z, Slider_Event1E00069
	cp xiz, 0x1C00019
	jrl z, Slider_Event1E00069
	cp xiz, 0x1C00018
	jr z, Slider_Case1E0006B
