	ld (xsp + 4), xhl
	ld xbc, (xsp + 4)
	ld wa, (xbc + 22)
	extz xwa
	cp (xsp + 8), xwa
	jrl c, Slider_NoChange
	ld wa, (xbc + 24)
	extz xwa
	cp (xsp + 8), xwa
	jrl ugt, Slider_NoChange
	cpw (xbc + 30), 0x0
	jr z, Slider_AtMax
	ld xwa, xiz
	cp xwa, 0x1C00017
	jr nz, Slider_Increment
	ld xwa, (xsp + 12)
	ld xbc, 0x1C00019
	ld xde, (xsp + 8)
	jr Slider_IncrDone

Slider_Increment:
