Slider_AtMax:
	ld xwa, (xsp + 4)
	cpw (xwa + 26), 0x0
	jrl z, Slider_NoChange
	cpw (xwa + 28), 0x0
	jr z, Slider_Decrement
	ld xwa, (xsp + 12)
	ld xbc, 0x1C50003
	ld xde, (xsp + 8)
	call 0xF9A579
	ld xwa, (xsp + 12)
	ld xbc, 0x1C50002
	ld xde, (xsp + 8)
	jr Slider_DecrDone

Slider_Decrement:
