	call 0xF9A579
	ld xwa, (xsp + 12)
	ld xbc, 0x1C50003
	ld xde, (xsp + 8)

Slider_DecrDone:
	call 0xF9A58A
	lds wa, 1

Slider_ReturnZero:
	call 0xF9A53B
