Slider_Event1E00069:
	ld xwa, (xsp + 12)
	ld xbc, xiz
	ld xde, (xsp + 8)
	call 0xFA4409
	ld xwa, (xsp + 12)
	call 0xFA6266
	ld wa, (xhl + 22)
	extz xwa
