	jrl c, Slider_NoChange
	ld wa, (xhl + 24)
	extz xwa
	cp (xsp + 8), xwa
	jrl ugt, Slider_NoChange
	cpw (xhl + 30), 0x0
	jrl z, Slider_NoChange
	ld xwa, xiz
	cp xwa, 0x1C00019
	jr nz, Slider_DragIncr
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00017
	ld xde, (xsp + 8)
	jr Slider_UpdateDone

Slider_DragIncr:
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00018
	ld xde, (xsp + 8)
	jr Slider_UpdateDone

Slider_Event1E00068:
	ld xwa, (xsp + 12)
	ld xbc, xiz
	ld xde, (xsp + 8)
	call 0xFA4409
	ld xwa, (xsp + 12)
	call 0xFA6266
	ld wa, (xhl + 22)
