; =============================================================================
; AcRotStrBoxProc - Scrollbar/rotary control animation handler
;
; Event-driven handler for smooth scrollbar and rotary encoder UI animations.
; Manages timer-based scrolling with auto-repeat functionality.
;
; Events handled:
;   0x1C00001 - Create: initialize scrollbar, set workspace +44 flag to 1
;   0x1C00002 - Re-enable: reset tracking state at +44 to 0
;   0x1C0000B - Suspend: forward event to parent
;   0x1C0000F - Timer tick: auto-scroll if flag at +44 is set
;   0x1C50000 - Init: set workspace +44 flag based on DE parameter
;   0x1E5000A - Timer event: schedule next auto-scroll tick
;
; Workspace layout:
;   +36: long - child widget pointer (forwarded events)
;   +40: word - scroll step size / timer interval
;   +42: word - scroll direction
;   +44: long - pointer to auto-repeat flag (0=stopped, 1=running)
; =============================================================================
AcRotStrBoxProc:
	lda xsp, (xsp - 16)
	push xiz
	ld (xsp + 8), xde
	ld (xsp + 12), xbc
	ld (xsp + 16), xwa
	ld xwa, (xsp + 12)
	cp xwa, 0x1C50000
	jrl z, Scrollbar_Case1C00001
	cp xwa, 0x1C0000F
	jrl z, Scrollbar_Case1E5000A
	cp xwa, 0x1E5000A
	jrl z, Scrollbar_Case1E00068
	cp xwa, 0x1C0000B
	jr z, Scrollbar_Case1E00069
	cp xwa, 0x1C00002
	jr z, Scrollbar_Case1E00067
	cp xwa, 0x1C00001
	jrl nz, Scrollbar_Error
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld xiz, xhl
	ld xwa, (xiz + 44)
	ldw (xwa), 0x1
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 12)
	ld xde, (xsp + 8)
	call 0xFA4409
	ld de, (xiz + 42)
	extz xde
	ld xwa, (xiz + 36)
	ld xbc, (xsp + 12)
	jr Scrollbar_Update

Scrollbar_Case1E00067:
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld xiz, xhl
	ld xwa, (xiz + 44)
	ldw (xwa), 0x0
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 12)
	ld xde, (xsp + 8)
	call 0xFA4409
	ld wa, (xiz + 40)
	extz xwa
	ld xbc, 0x1E5000A
	push xbc
	lds32 xbc, 0
	push xbc
	ld xbc, (xsp + 24)
	ld xde, (xsp + 24)
	call 0xFAA257
	jrl Scrollbar_Done

Scrollbar_Case1E00069:
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 12)
	ld xde, (xsp + 8)
	call 0xFA4409
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld xde, (xsp + 16)
	ld xwa, (xhl + 36)
	ld xbc, (xsp + 12)
	jr Scrollbar_Update

Scrollbar_Case1E00068:
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld xde, (xsp + 16)
	ld xwa, (xhl + 36)
	ld xbc, 0x1C0000B

Scrollbar_Update:
	call 0xFA49B7
	jr Scrollbar_Done

Scrollbar_Case1E5000A:
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld (xsp + 4), xhl
	ld xwa, (xsp + 4)
	ld wa, (xwa + 40)
	extz xwa
	ld xbc, 0x1E5000A
	push xbc
	lds32 xbc, 0
	push xbc
	ld xbc, (xsp + 24)
	ld xde, (xsp + 24)
	call 0xFAA257
	ld xwa, (xsp + 4)
	ld xwa, (xwa + 44)
	cpw (xwa), 0x0
	jr z, Scrollbar_Done
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 12)
	ld xde, (xsp + 8)
	call 0xFA4409
	ld xwa, (xsp + 4)
	ld wa, (xwa + 40)
	extz xwa
	ld xbc, 0x1E5000A
	push xbc
	lds32 xbc, 0
	push xbc
	ld xbc, (xsp + 24)
	ld xde, (xsp + 24)
	call 0xFAA135

Scrollbar_Done:
	lds32 xhl, 0
	jr Scrollbar_Return

Scrollbar_Case1C00001:
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld xbc, (xhl + 44)
	ld xwa, (xsp + 8)
	or xwa, xwa
	jr z, Scrollbar_SkipInit
	ldw (xbc), 0x0
	jr Scrollbar_InitDone

Scrollbar_SkipInit:
	ldw (xbc), 0x1

Scrollbar_InitDone:
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 12)
	ld xde, (xsp + 8)
	jr Scrollbar_ErrorExit

Scrollbar_Error:
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 12)
	ld xde, (xsp + 8)

Scrollbar_ErrorExit:
	call 0xFA4409

Scrollbar_Return:
	pop xiz
	lda xsp, (xsp + 16)
	ret

