	ld bc, (xde)
	exts xbc
	push xbc
	ld xbc, (xsp + 16)
	ld xde, 0xFFFFFFFF
	call 0xFAA257
	ld wa, (xiz + 26)
	extz xwa
	ld xbc, 0x1C00017
	push xbc
	ld bc, (xiz + 28)
	exts xbc
	push xbc
	ld xbc, (xsp + 16)
	ld xde, 0xFFFFFFFF
	call 0xFAA135

Bounds_Done:
