Sound_Navigate_Entry:
	ld (xsp + 4), wa
	cpw (xsp + 4), 0xF
	jr le, Sound_Navigate_Init
	cpw (xsp + 4), 0x15
	jrl lt, Sound_Navigate_Return
	cpw (xsp + 4), 0x16
	jrl gt, Sound_Navigate_Return

Sound_Navigate_Init:
	ldw (xsp + 12), 0x0
	ld xwa, (xsp + 20)
	srl xwa, 0
	ldi_werp 0xE2, 0
	ld (xsp + 10), wa
	ld wa, (xsp + 4)
	lds bc, 0
	call SndParam_LookupViaEncode
	ld (xsp + 17), l
	ld wa, (xsp + 4)
	ldw bc, 0x20
	call SndParam_LookupViaEncode
	lda xwa, (xsp + 14)
	ld (xwa + 4), l
	ld bc, (xsp + 4)
	ld (xwa + 2), c
	call SndParam_FetchOscTableEntry
	lda xbc, (xsp + 14)
	ld a, (xbc)
	extz wa
	ld (xsp + 8), wa
	ld a, (xbc + 1)
	ldfr_berp A, 0xF8
	extz iz
	ld wa, (xsp + 4)
	ld bc, (xsp + 8)
	calr GetSoundBankCount
	ld (xsp + 6), hl
	add iz, (xsp + 10)

Sound_Navigate_SearchLoop:
	cps iz, 0
	jr ge, Sound_Navigate_ScanForward
	cpw (xsp + 8), 0x0
	jr le, Sound_Navigate_AtBottom
	ld wa, (xsp + 8)
	ldfr_werp WA, 0xFA
	ld (xsp + 10), iz
	ld hl, (xsp + 6)
	cpi_werp 0xFA, 0
	jrl le, Sound_Navigate_UpdateState

Sound_Navigate_ScanBackward:
	dec1_werp 0xFA
	ld wa, (xsp + 4)
	ldto_werp BC, 0xFA
	calr GetSoundBankCount
	ld wa, hl
	inc 1, wa
	add (xsp + 10), wa
	cp hl, 0xFFFF
	jr nz, Sound_Navigate_BackwardCheck
	cpi_werp 0xFA, 0
	jr gt, Sound_Navigate_BackwardCheck
	ld wa, (xsp + 8)
	ldfr_werp WA, 0xFA
	ldw (xsp + 10), 0x0
	ld hl, (xsp + 6)
	jr Sound_Navigate_UpdateState

Sound_Navigate_BackwardCheck:
	cp hl, 0xFFFF
	jr nz, Sound_Navigate_UpdateState
	cpi_werp 0xFA, 0
	jr gt, Sound_Navigate_ScanBackward
	jr Sound_Navigate_UpdateState

Sound_Navigate_AtBottom:
	lds iz, 0
	jrl Sound_Navigate_SetDone

Sound_Navigate_ScanForward:
	cp iz, (xsp + 6)
	jrl le, Sound_Navigate_SetDone
	cpw (xsp + 8), 0x11
	jrl ge, Sound_Navigate_AtTop
	ld wa, (xsp + 8)
	ldfr_werp WA, 0xFA
	ld (xsp + 10), iz
	ld hl, (xsp + 6)
	cp_erpw 0xFA, 0x11, 0x00
	jr ge, Sound_Navigate_UpdateState

Sound_Navigate_ForwardLoop:
	inc1_werp 0xFA
	inc 1, hl
