; Handler for event 0x1C00030 within GroupBoxProc.
; Calls BoxProc, then queries widget status (event 0x1E00024).
; Falls through to GroupBoxProc_StartSSFPresentation regardless of result.
GroupBoxProc_Ev1C00030:
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, (xsp + 34)
	calr BoxProc
	ld xwa, (xsp + 38)
	ld xbc, 0x1E00024
	ld xde, 0x1600029
	call 0xFA9660
	or xhl, xhl
	jr z, GroupBoxProc_StartSSFPresentation
	ld xde, (xsp + 30)
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00009
	call 0xFA9660
	ld xde, (xsp + 30)
	set 7, de
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00009
	call 0xFA9660
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, 0x1C00034
	call 0xFA9660

; Builds an SSF presentation workspace and sends event 0x1C0001C via direct
; SendEvent (FA9660).  This is the CRITICAL path that allows
; AcPresentationControlProc to pass its 0xB80A type-tag check and start
; SSF playback.
;
; The workspace (at XSP+14) is populated byte-by-byte from XSP+30/31:
;   workspace[0] = byte at (XSP+31)   -- must be 0x0A for tag 0x0000B80A
;   workspace[1] = byte at (XSP+30)   -- must be 0xB8
;   workspace[2..3] = shifted/zero bytes
;
; Reached via event 0x1C00038 (direct) or event 0x1C00030 (via
; GroupBoxProc_Ev1C00030 fall-through).
GroupBoxProc_StartSSFPresentation:
	ld xwa, (xsp + 38)
	call 0xFA44BE
	ld xwa, 0x1C0001C
	call 0xFA44C4
	lda xwa, (xsp + 18)
	call 0xFA44CA
	lda xbc, (xsp + 30)
	ld xde, xbc
	inc 1, xde
	lda xwa, (xsp + 14)
	ld c, (xbc)
	ld (xwa + 3), c
	ld_spib C, 0xE8
	ld (xwa + 2), c
	ld_spib C, 0xE8
	ld (xwa + 1), c
	ld c, (xde)
	ld (xwa), c
	lda xbc, (xsp + 10)
	lda xde, (xsp + 8)
	call SndParam_ResolveWidget
	cp hl, 0xFFFF
	jrl z, GroupBox_ReturnZero

; Loop body: iterates over SSF items via FCD437, builds workspace fields,
; and sends event 0x1C0001C for each item via direct SendEvent.
; Loops until FCD4FF reports no more items (HL == 0xFFFF).
GroupBoxProc_SSFItemLoop:
	ld xwa, (xsp + 10)
	ld (xsp + 18), xwa
	ld xwa, (xsp + 10)
	call SndParam_LookupReadOnly
	lda xde, (xsp + 18)
	ld (xde + 4), hl
	ldw (xde + 6), 0x0
	lds32 xwa, 0
	ld (xde + 8), xwa
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C0001C
	call 0xFA9660
	lda xwa, (xsp + 14)
	lda xbc, (xsp + 10)
	lda xde, (xsp + 8)
	call SndParam_ResolveWidget
	cp hl, 0xFFFF
	jr nz, GroupBoxProc_SSFItemLoop
	jrl GroupBox_ReturnZero

	; --- Event 0x1E0006E: Cancel/Back handler ---
	; Iterates the 17-entry widget structure array at 0x0274E8
	; (28-byte entries: stride = (ix*8 - ix)*4 = ix*28).
	; If event param (XWA) is nonzero: activates entries and sends 0x1C00026.
	; If event param is zero: deactivates entries and sends 0x1C00026.
	; Each entry has: byte[0]=active, byte[1]=enabled, dword[2]=workspace,
	; dword[6]=event(0x1C00007), dword[10]=focus_id, offset[14]=secondary.
GroupBox_CancelBack:
	lds iz, 0

GroupBox_CancelBack_Loop:
	ld ix, iz
	extz xix
	lda_24 xiy, 0x0274e8
	ld xde, xix
	sll xde, 3
	sub xde, xix
	sll xde, 2
	ld xbc, xiy
	add xbc, xde
	ld xwa, (xsp + 30)
	or xwa, xwa
	jrl z, GroupBox_CancelBack_Deactivate
	ld (xsp + 4), xix
	ld xhl, xbc
	ld xwa, (xsp + 38)
	ld (xbc + 2), xwa
	ld xwa, 0x1C00007
	ld (xbc + 6), xwa
	ld (xbc + 10), xix
	lda xwa, (xde + 14)
	add xiy, xwa
	ld xwa, (xsp + 38)
	ld (xiy + 2), xwa
	ld xwa, 0x1C00007
	ld (xiy + 6), xwa
	ld wa, iz
	add wa, 0x80
	extz xwa
	ld (xiy + 10), xwa
	cp (xbc), 0x0
	jr z, GroupBox_CancelBack_ActivateSecondary
	lda xwa, (xhl + 1)
	cp (xwa), 0x0
	jr nz, GroupBox_CancelBack_ActivateSecondary
	ld (xwa), 0x1
	ld xwa, 0x1C00026
	push xwa
	ld xwa, (xsp + 8)
	push xwa
	ld xwa, 0x10
	ld xbc, (xsp + 46)
	ld xde, (xsp + 46)
	call 0xFAA135

GroupBox_CancelBack_ActivateSecondary:
	ld bc, iz
	extz xbc
	ld xwa, xbc
	sll xwa, 3
	sub xwa, xbc
	sll xwa, 2
	lda xbc, (xwa + 14)
	ld xwa, 0x274E8
	add xwa, xbc
	cp (xwa), 0x0
	jrl z, GroupBox_CancelBack_LoopNext
	inc 1, xwa
	cp (xwa), 0x0
	jrl nz, GroupBox_CancelBack_LoopNext
	ld (xwa), 0x1
	ld xwa, 0x1C00026
	push xwa
	ld wa, iz
	add wa, 0x80
	extz xwa
	push xwa
	ld xwa, 0x10
	ld xbc, (xsp + 46)
	ld xde, (xsp + 46)
	call 0xFAA135
	jr GroupBox_CancelBack_LoopNext

GroupBox_CancelBack_Deactivate:
	ld xwa, xbc
	cp (xbc), 0x0
	jr z, GroupBox_CancelBack_DeactivateSecondary
	inc 1, xwa
	cp (xwa), 0x0
	jr z, GroupBox_CancelBack_DeactivateSecondary
	ld (xwa), 0x0
	ld xwa, 0x1C00026
	push xwa
	push xix
	ld xwa, 0x10
	ld xbc, (xsp + 46)
	ld xde, (xsp + 46)
	call 0xFAA257

GroupBox_CancelBack_DeactivateSecondary:
	ld bc, iz
	extz xbc
	ld xwa, xbc
	sll xwa, 3
	sub xwa, xbc
	sll xwa, 2
	lda xbc, (xwa + 14)
	ld xwa, 0x274E8
	add xwa, xbc
	cp (xwa), 0x0
	jr z, GroupBox_CancelBack_LoopNext
	inc 1, xwa
	cp (xwa), 0x0
	jr z, GroupBox_CancelBack_LoopNext
	ld (xwa), 0x0
	ld xwa, 0x1C00026
	push xwa
	ld wa, iz
	add wa, 0x80
	extz xwa
	push xwa
	ld xwa, 0x10
	ld xbc, (xsp + 46)
	ld xde, (xsp + 46)
	call 0xFAA257

GroupBox_CancelBack_LoopNext:
	inc 1, iz
	cp iz, 0x10
	jrl ule, GroupBox_CancelBack_Loop
	jrl GroupBox_ReturnZero

	; --- Event 0x1E0006F: Dial Enable ---
	; Stores WA (from XBC param) into dial enable register at 0x03EF50.
GroupBox_DialEnable:
	ld wa, bc
	calr SetDialEnable
	jrl GroupBox_ReturnZero

	; --- Event 0x1E00070: Dial Down ---
	; Registers down-direction parameters (workspace, event 0x1C00007, param)
	; into dial state at 0x03EF56/5E/66 and updates dial focus.
GroupBox_DialDown:
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, 0x1C00007
	calr SetDialDown
	jrl GroupBox_ReturnZero

	; --- Event 0x1E00071: Dial Up ---
	; Registers up-direction parameters (workspace, event 0x1C00007, param)
	; into dial state at 0x03EF52/5A/62 and updates dial focus.
GroupBox_DialUp:
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, 0x1C00007
	calr SetDialUp
	jrl GroupBox_ReturnZero

	; --- Event 0x1E00088: Get Dial Focus ---
	; Returns current dial focus value from 0x03EF6A in XHL.
GroupBox_GetDialFocus:
	calr GetDialFocus
	jrl GroupBox_Epilogue

	; --- Event 0x1E00087: Set Dial Focus ---
	; Stores dial focus (XWA) at 0x03EF6A and broadcasts 0x1C0002C.
GroupBox_SetDialFocus:
	calr SetDialFocus
	jrl GroupBox_ReturnZero

	; --- Events 0x1E00079/0x1E00078: UP/DOWN Navigation ---
	; Calls 0xFA5867 (lookup), then dispatches 0x1E000B4 via FA9660.
	; Falls through to loop that broadcasts 0x1C00009 (close/hide) to
	; all active entries in the 0x0274E8 structure array.
GroupBox_NavUpDown:
	call 0xFA5867
	ld xwa, xhl
	ld xde, (xsp + 30)
	ld xbc, (xsp + 34)
	jr GroupBox_NavDispatch
	call UIRender_RetStub1
	jrl GroupBox_ReturnZero
	call UIRender_RetStub2
	jrl GroupBox_ReturnZero
	lds wa, 0
	calr SetDialEnable
	ld xwa, 0xFFFFFFFF
	st32_24 0x03ef6a, xwa
	call 0xFA9F08
	ld xwa, (xsp + 38)
	ld xbc, 0x1E000B4
	lds32 xde, 0

GroupBox_NavDispatch:
	call 0xFA9660
	jr GroupBox_ReturnZero
	lds iz, 0

GroupBox_CloseAll_Loop:
	ld de, iz
	extz xde
	ld xwa, xde
	sll xwa, 3
	sub xwa, xde
	sll xwa, 2
	ld xbc, 0x274E8
	add xbc, xwa
	cp (xbc), 0x0
	jr z, GroupBox_CloseAll_Secondary
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00009
	call 0xFA9660

GroupBox_CloseAll_Secondary:
	ld wa, iz
	extz xwa
	ld xbc, xwa
	sll xbc, 3
	sub xbc, xwa
	sll xbc, 2
	lda xwa, (xbc + 14)
	ld xbc, 0x274E8
	add xbc, xwa
	cp (xbc), 0x0
	jr z, GroupBox_CloseAll_Next
	ld de, iz
	add de, 0x80
	extz xde
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00009
	call 0xFA9660

GroupBox_CloseAll_Next:
	inc 1, iz
	cp iz, 0x10
	jr ule, GroupBox_CloseAll_Loop
	jr GroupBox_ReturnZero

	; --- Event 0x1C00036: Display Update ---
	; Enables display (FAA761 with WA=1), calls UpdateScreen, then disables.
GroupBox_DisplayUpdate:
	lds wa, 1
	call SetNeedUpdate
	call UpdateScreen
	lds wa, 0

GroupBox_DisableDisplay:
	call SetNeedUpdate

GroupBox_ReturnZero:
	lds32 xhl, 0
	jr GroupBox_Epilogue

GroupBox_ForwardToBoxProc:
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, (xsp + 34)
	calr BoxProc

GroupBox_Epilogue:
	popw iz
	lda xsp, (xsp + 40)
	ret

SetDialEnable:
	st16_24 0x03ef50, xwa
	ret

LABEL_F9A541:
	ld16_24 xhl, 0x03ef50
	ret

SetDialFocus:
	ld xde, xwa
	cpdm32_24 257898, xde
	ret z
	st32_24 0x03ef6a, xde
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C0002C
	call 0xFA9660
	ret

GetDialFocus:
	cpdi16_24 257872, 0
	jr nz, LABEL_F9A573
	ld xhl, 0xFFFFFFFF
	ret

LABEL_F9A573:
	ld32_24 xhl, 0x03ef6a
	ret

SetDialUp:
	st32_24 0x03ef52, xwa
	st32_24 0x03ef5a, xbc
	st32_24 0x03ef62, xde
	jr SetDialFocus

SetDialDown:
	st32_24 0x03ef56, xwa
	st32_24 0x03ef5e, xbc
	st32_24 0x03ef66, xde
	jr SetDialFocus

SetAutoIncDefault:
	dec 4, xsp
	push xiz
	call 0xFA44AC
	ld xiz, xhl
	call 0xFA44B2
	ld (xsp + 4), xhl
	call 0xFA44B8
	ld xde, xhl
