ScreenProc:
	lda xsp, (xsp - 12)
	push xiz
	ld xiz, xde
	ld (xsp + 8), xbc
	ld (xsp + 12), xwa
	ld xwa, (xsp + 8)
	cp xwa, 0x1E0004A
	jrl z, Screen_GetDefault
	cp xwa, 0x1E00048
	jrl z, Screen_ReturnZero
	cp xwa, 0x1E0004B
	jrl z, Screen_GetStoredValue
	cp xwa, 0x1E00049
	jrl z, Screen_SetStoredValue
	cp xwa, 0x1C00007
	jrl z, Screen_OK
	cp xwa, 0x1C00009
	jrl z, Screen_Deactivate
	cp xwa, 0x1C0000D
	jrl z, Screen_Paint
	cp xwa, 0x1C00002
	jrl z, Screen_Close
	cp xwa, 0x1C00001
	jr z, Screen_Init
	ld xwa, (xsp + 12)
	ld xbc, (xsp + 8)
	ld xde, xiz
	jrl Screen_ForwardToGroupBox

