	ld xwa, xhl
	ld xbc, 0x1E0004B
	lds32 xde, 0
	call 0xFA9660
	cp xhl, 0xFFFFFFFF
	jr nz, Screen_Init_RegisterChild
	call 0xFA9A77
	ld xwa, xhl
	ld xbc, 0x1E00014
	ld xde, 0x1600033
	call 0xFA9660
	or xhl, xhl
	jr nz, Screen_Init_Setup

