	ld xbc, 0x1C00002
	ld xde, xiz
	call 0xFA9660
	call 0xFA9A77
	ld xwa, xhl
	ld xbc, 0x1E00014
	ld xde, 0x1600033
	call 0xFA9660
	or xhl, xhl
