	cpw (xwa + 40), 0x0
	jr z, PsGridBox_Select_StoreSel
	st_dri3b A, 0xFD, 0x3E, 0x01
	ld_sril XWA, (xsp + 0x014e)
	calr GetClientBox
	st_dri3b A, 0xFD, 0x3E, 0x01
	ld wa, (xbc + 2)
	st_dri3w WA, 0xFD, 0x30, 0x01
	ld wa, (xbc + 6)
	st_dri3w WA, 0xFD, 0x2C, 0x01
	ldw (xsp + 12), 0x1
	ld xwa, (xsp + 20)
	cpw (xwa + 38), 0x1
	jr ule, PsGridBox_Select_StoreSel

PsGridBox_Select_ScrollLoop:
	ld de, (xsp + 12)
	extz xde
	add xde, xde
	ld xwa, (xsp + 20)
	lda xhl, (xwa + 50)
	ld xwa, (xhl)
	ld xbc, (xwa)
	add xbc, xde
	st_dri3b W, 0xFD, 0x2E, 0x01
	ld bc, (xbc)
	ld (xwa), bc
	ld xbc, (xhl)
	ld xhl, (xbc)
	add xhl, xde
	st_dri3b A, 0xFD, 0x2A, 0x01
	ld de, (xhl)
	ld (xbc), de
	ldw de, 0xFF
	call 0xFAA98A
	incm 1, (xsp + 12)
	ld xwa, (xsp + 20)
	ld bc, (xsp + 12)
	cp bc, (xwa + 38)
	jr c, PsGridBox_Select_ScrollLoop

PsGridBox_Select_StoreSel:
	ld xde, (xsp + 20)
	ld xbc, (xde + 42)
	ld_sril XWA, (xsp + 0x0146)
	ld (xbc), wa
	cpw (xsp + 18), 0xFFFF
	jr z, PsGridBox_Select_SendCurr
	ld bc, (xsp + 18)
	extz xbc
	ld xwa, (xde + 46)
	ld wa, (xwa)
	extz xwa
	sll xwa, 0
	ld xde, xwa
	add xde, xbc
	ld_sril XWA, (xsp + 0x014e)
	ld xbc, 0x1E0008D
	call 0xFA9660

PsGridBox_Select_SendCurr:
	ld xde, (xsp + 20)
	ld xwa, (xde + 42)
	ld bc, (xwa)
	extz xbc
	ld xwa, (xde + 46)
	ld wa, (xwa)
	extz xwa
	sll xwa, 0
	ld xde, xwa
	add xde, xbc
	ld_sril XWA, (xsp + 0x014e)
	ld xbc, 0x1E0008D
	call 0xFA9660
	st_dri3b A, 0xFD, 0x3E, 0x01
	ld_sril XWA, (xsp + 0x014e)
	calr GetClientBox
	ld xde, (xsp + 20)
	lda xbc, (xde + 42)
	ld xwa, (xbc)
	ld hl, (xwa)
	exts xhl
	add xhl, xhl
	lda xde, (xde + 54)
	ld xwa, (xde)
	ld xwa, (xwa)
	add xwa, xhl
	ld hl, (xwa)
	inc 1, hl
	st_dri3b W, 0xFD, 0x3E, 0x01
	ld (xwa + 2), hl
	incm 1, (xwa)
	decm 1, (xwa + 4)
	ld xbc, (xbc)
	ld hl, (xbc)
	inc 1, hl
	exts xhl
	add xhl, xhl
	ld xbc, (xde)
	ld xbc, (xbc)
	add xbc, xhl
	ld bc, (xbc)
	inc 2, bc
	ld (xwa + 6), bc
	pushw 0xF2
	lds bc, 1
	lds de, 2
	calr DrawDesignFrame
	jrl PsGridBox_ReturnZero

PsGridBox_Scroll:
	ld_sril XWA, (xsp + 0x014e)
	ld_sril XBC, (xsp + 0x014a)
	ld_sril XDE, (xsp + 0x0146)
	calr VwBoxProc
	ld_sril XWA, (xsp + 0x014e)
	call 0xFA6266
	ld de, (xhl + 26)
	cp de, 0xFFFF
	jrl z, PsGridBox_ReturnZero
	ld bc, de
	exts xbc
	cp_sril_rm XBC, 0xFD, 0x46, 0x01
	jrl z, PsGridBox_ReturnZero
	ld_sril XWA, (xsp + 0x0146)
	sub wa, de
	cp wa, (xhl + 38)
	jrl nc, PsGridBox_ReturnZero
	ld_sril XWA, (xsp + 0x0146)
	sub xwa, xbc
	ld bc, wa
	extz xbc
	sll xbc, 0
	ld xwa, (xhl + 42)
	ld de, (xwa)
	extz xde
	add xde, xbc
	ld_sril XWA, (xsp + 0x014e)
	ld xbc, 0x1E0008E
	jrl PsGridBox_DispatchEvent
	ld_sril XWA, (xsp + 0x014e)
	call 0xFA6266
	ld (xsp + 20), xhl
	ld_sril XWA, (xsp + 0x0146)
	ld xiy, xwa
	lda xix, (xsp + 24)
	lds bc, 4
	ldirw
	lda xde, (xsp + 24)
	cpw (xde), 0xFFFF
	jr nz, PsGridBox_Scroll_DefaultCol
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 46)
	ld wa, (xwa)
	ld (xde), wa

PsGridBox_Scroll_DefaultCol:
	lda xhl, (xde + 2)
	cpw (xhl), 0xFFFF
	jr nz, PsGridBox_Scroll_CalcBounds
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 42)
	ld wa, (xwa)
	ld (xhl), wa

PsGridBox_Scroll_CalcBounds:
	ld bc, (xhl)
	exts xbc
	add xbc, xbc
	ld xiy, (xsp + 20)
	lda xix, (xiy + 54)
	ld xwa, (xix)
	ld xwa, (xwa)
	add xwa, xbc
	ld bc, (xwa)
	inc 3, bc
	st_dri3b W, 0xFD, 0x3E, 0x01
	ld (xwa + 2), bc
	ld iz, (xde)
	exts xiz
	add xiz, xiz
	lda xiy, (xiy + 50)
	ld xbc, (xiy)
	ld xbc, (xbc)
	add xbc, xiz
	ld bc, (xbc)
	inc 4, bc
	ld (xwa), bc
	ld de, (xde)
	inc 1, de
	exts xde
	add xde, xde
	ld xbc, (xiy)
	ld xbc, (xbc)
	add xbc, xde
	ld bc, (xbc)
	dec 4, bc
	ld (xwa + 4), bc
	ld de, (xhl)
	inc 1, de
	exts xde
	add xde, xde
	ld xbc, (xix)
	ld xbc, (xbc)
	add xbc, xde
	ld bc, (xbc)
	dec 1, bc
	ld (xwa + 6), bc
	st_dri3b A, 0xFD, 0x32, 0x01
	calr GetBoxCenter
	calr GetDialFocus
	cp_sril_rm XHL, 0xFD, 0x4E, 0x01
	jr nz, PsGridBox_Scroll_Unfocused
	lda xbc, (xsp + 24)
	ld xde, (xsp + 20)
	ld xwa, (xde + 42)
	ld wa, (xwa)
	cp wa, (xbc + 2)
	jr nz, PsGridBox_Scroll_Unfocused
	ld xwa, (xde + 46)
	ld wa, (xwa)
	cp wa, (xbc)
	jr nz, PsGridBox_Scroll_Unfocused
	lds de, 1
	jr PsGridBox_Scroll_Render

PsGridBox_Scroll_Unfocused:
	lds de, 0

PsGridBox_Scroll_Render:
	st_dri3b C, 0xFD, 0x3E, 0x01
	st_dri3b A, 0xFD, 0x32, 0x01
	ld xix, (xsp + 20)
	ld xwa, (xix + 28)
	push xwa
	pushm (xix + 32)
	ld xwa, xix
	pushm (xwa + 22)
	ld a, (xwa + 34)
	extz wa
	pushw wa
	pushw de
	ld xde, (xsp + 40)
	ld xwa, xhl
	call 0xFAD084
	jrl PsGridBox_ReturnZero
	lda xde, (xsp + 24)
	ld_sril XWA, (xsp + 0x0146)
	srl xwa, 0
	ldi_werp 0xE2, 0
	ld (xde), wa
	lda xbc, (xde + 2)
	ld_sril XWA, (xsp + 0x0146)
	ld (xbc), wa
	lda xwa, (xsp + 32)
	ld (xde + 4), xwa
	pushm (xbc)
	pushm (xde)
	pushw 0xEA
	pushw 0xA1EC
	push xwa
	call Audio_SendCommand
	lda xsp, (xsp + 12)
	lda xde, (xsp + 24)
	ld_sril XWA, (xsp + 0x014e)
	ld xbc, 0x1E0008C
	jrl PsGridBox_DispatchEvent
	ld xwa, 0xEAA1F2
	jr PsGridBox_Scroll_CopyStr
	ld xwa, 0xEAA212

PsGridBox_Scroll_CopyStr:
	push xwa
	ld_sril XWA, (xsp + 0x014a)
	push xwa
	call Strcpy
	inc 8, xsp
	jrl PsGridBox_ReturnZero
	ld_sril XWA, (xsp + 0x014e)
	call 0xFA6266
	ld (xsp + 20), xhl
	ld_sril XWA, (xsp + 0x0146)
	srl xwa, 0
	ldi_werp 0xE2, 0
	ld iz, wa
	cp iz, 0xFFFF
	jr nz, PsGridBox_Scroll_DefaultRow
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 46)
	ld iz, (xwa)

PsGridBox_Scroll_DefaultRow:
	ld_sril XWA, (xsp + 0x0146)
	ld (xsp + 18), wa
	cpw (xsp + 18), 0xFFFF
	jr nz, PsGridBox_Scroll_CheckRowChange
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 42)
	ld wa, (xwa)
	ld (xsp + 18), wa

PsGridBox_Scroll_CheckRowChange:
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 42)
	ld wa, (xwa)
	cp wa, (xsp + 18)
	jr z, PsGridBox_Scroll_CheckColChange
	ld de, (xsp + 18)
	exts xde
	ld_sril XWA, (xsp + 0x014e)
	ld xbc, 0x1C0000E
	call 0xFA9660

PsGridBox_Scroll_CheckColChange:
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 46)
	cp (xwa), iz
	jrl z, PsGridBox_ReturnZero
	ldw iz, 0xFFFF
	cpw (xwa), 0x0
	jr le, PsGridBox_Scroll_StoreCol
	ld iz, (xwa)

PsGridBox_Scroll_StoreCol:
	ld_sril XBC, (xsp + 0x0146)
	srl xbc, 0
	ldi_werp 0xE6, 0
	cp bc, 0xFFFF
	jr z, PsGridBox_Scroll_SendOldCell
	ld (xwa), bc

PsGridBox_Scroll_SendOldCell:
	cp iz, 0xFFFF
	jr z, PsGridBox_Scroll_SendNewCell
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 42)
	ld bc, (xwa)
	extz xbc
	ld wa, iz
	extz xwa
	sll xwa, 0
	ld xde, xwa
	add xde, xbc
	ld_sril XWA, (xsp + 0x014e)
	ld xbc, 0x1E0008D
	call 0xFA9660

PsGridBox_Scroll_SendNewCell:
	ld xde, (xsp + 20)
	ld xwa, (xde + 42)
	ld bc, (xwa)
	extz xbc
	ld xwa, (xde + 46)
	ld wa, (xwa)
	extz xwa
	sll xwa, 0
	ld xde, xwa
	add xde, xbc
	ld_sril XWA, (xsp + 0x014e)
	ld xbc, 0x1E0008D

PsGridBox_DispatchEvent:
	call 0xFA9660
	jrl PsGridBox_ReturnZero
	ld_sril XWA, (xsp + 0x014e)
	call 0xFA6266
	ld xwa, (xhl + 42)
	ld bc, (xwa)
	extz xbc
	ld xwa, (xhl + 46)
	ld wa, (xwa)
	extz xwa
	sll xwa, 0
	add xwa, xbc
	ld xhl, xwa
	jr PsGridBox_Return
	ld_sril XWA, (xsp + 0x014e)
	call 0xFA6266
	ld de, (xhl + 26)
	cp de, 0xFFFF
	jrl z, PsGridBox_ReturnZero
	ld wa, de
	exts xwa
	cp_sril_rm XWA, 0xFD, 0x46, 0x01
	jrl z, PsGridBox_ReturnZero
	ld_sril XWA, (xsp + 0x0146)
	sub wa, de
	cp wa, (xhl + 38)
	jrl nc, PsGridBox_ReturnZero
	lds32 xhl, 1
	jr PsGridBox_Return

PsGridBox_Default:
	ld_sril XWA, (xsp + 0x014e)
	ld_sril XBC, (xsp + 0x014a)
	ld_sril XDE, (xsp + 0x0146)
	calr VwBoxProc

PsGridBox_Return:
	pop xiz
	st_dri3b L, 0xFD, 0x4E, 0x01
	ret

AcGridBoxProc:
	lda xsp, (xsp - 16)
	push xiz
	ld (xsp + 12), xde
	ld xiz, xbc
	ld (xsp + 16), xwa
	ld xwa, xiz
	cp xiz, 0x1E0008D
	jrl z, AcGridBox_CellSelect
	cp xiz, 0x1E0008B
	jrl z, AcGridBox_GetRowText
	cp xiz, 0x1E0008A
	jrl z, AcGridBox_GetColText
	cp xiz, 0x1C00001
	jr z, AcGridBox_Init
	sub xwa, 0x1C00017
	cp xwa, 0x0
	jrl lt, AcGridBox_Default
	cp xwa, 0x6
	jrl gt, AcGridBox_Default
	add xwa, xwa
	add xwa, 0xEAA258
	ld wa, (xwa)
	lda_24 xix, 0xf9e9b3
	jp_dri 8, 0x07, 0xF0, 0xE0

AcGridBox_Init:
	ld xwa, (xsp + 16)
	ld xbc, xiz
	ld xde, (xsp + 12)
	calr PsGridBoxProc
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld (xsp + 8), xhl
	ld xwa, (xsp + 16)
	ld xbc, 0x1E0008F
	lds32 xde, 0
	call 0xFA9660
	ld (xsp + 4), xhl
	ld xwa, (xsp + 8)
	ld bc, (xwa + 26)
	ld xwa, (xsp + 4)
	srl xwa, 0
	ldi_werp 0xE2, 0
	add wa, bc
	ld de, wa
	extz xde
	ld xwa, (xsp + 16)
	ld xbc, 0x1C00017
	calr SetDialUp
	ld xwa, (xsp + 8)
	ld bc, (xwa + 26)
	ld xwa, (xsp + 4)
	srl xwa, 0
	ldi_werp 0xE2, 0
	add wa, bc
	ld de, wa
	extz xde
	ld xwa, (xsp + 16)
	ld xbc, 0x1C00018
	calr SetDialDown
	lds wa, 1
	jrl AcGridBox_EnableDials
	ld xwa, (xsp + 16)
	ld xbc, xiz
	ld xde, (xsp + 12)
	calr PsGridBoxProc
	ld xwa, (xsp + 16)
	ld xbc, 0x1E00050
	ld xde, (xsp + 12)
	call 0xFA9660
	or xhl, xhl
	jr z, AcGridBox_ScrollUp_Alt
	ld xwa, (xsp + 16)
	ld xbc, 0x1E0008F
	lds32 xde, 0
	call 0xFA9660
	dec 1, hl
	extz xhl
	add xhl, 0xFFFF0000
	ld xwa, (xsp + 16)
	ld xbc, 0x1C0000E
	ld xde, xhl
	call 0xFA9660
	ld xwa, (xsp + 16)
	ld xbc, 0x1C00019
	ld xde, (xsp + 12)
	calr SetAutoInc
	jrl AcGridBox_ReturnZero

AcGridBox_ScrollUp_Alt:
	ld xwa, (xsp + 16)
	ld xbc, 0x1E00091
	ld xde, (xsp + 12)
	call 0xFA9660
	or xhl, xhl
	jrl z, AcGridBox_ReturnZero
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld xwa, (xhl + 70)
	ld xbc, xiz
	ld xde, (xsp + 12)
	call 0xFA49B7
	ld xwa, (xsp + 16)
	ld xbc, 0x1C00019
	ld xde, (xsp + 12)
	calr SetAutoInc
	ld xwa, (xsp + 16)
	ld xbc, 0x1C00017
	ld xde, (xsp + 12)
	calr SetDialUp
	ld xwa, (xsp + 16)
	ld xbc, 0x1C00018
	ld xde, (xsp + 12)
	calr SetDialDown
	lds wa, 1
	jrl AcGridBox_EnableDials
	ld xwa, (xsp + 16)
	ld xbc, xiz
	ld xde, (xsp + 12)
	calr PsGridBoxProc
	ld xwa, (xsp + 16)
	ld xbc, 0x1E00050
	ld xde, (xsp + 12)
	call 0xFA9660
	or xhl, xhl
	jr z, AcGridBox_ScrollDown_Alt
	ld xwa, (xsp + 16)
	ld xbc, 0x1E0008F
	lds32 xde, 0
	call 0xFA9660
	inc 1, hl
	extz xhl
	add xhl, 0xFFFF0000
	ld xwa, (xsp + 16)
	ld xbc, 0x1C0000E
	ld xde, xhl
	call 0xFA9660
	ld xwa, (xsp + 16)
	ld xbc, 0x1C0001A
	ld xde, (xsp + 12)
	calr SetAutoInc
	jrl AcGridBox_ReturnZero

AcGridBox_ScrollDown_Alt:
	ld xwa, (xsp + 16)
	ld xbc, 0x1E00091
	ld xde, (xsp + 12)
	call 0xFA9660
	or xhl, xhl
	jr z, AcGridBox_ReturnZero
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld xwa, (xhl + 70)
	ld xbc, xiz
	ld xde, (xsp + 12)
	call 0xFA49B7
	ld xwa, (xsp + 16)
	ld xbc, 0x1C0001A
	ld xde, (xsp + 12)
	calr SetAutoInc
	ld xwa, (xsp + 16)
	ld xbc, 0x1C00017
	ld xde, (xsp + 12)
	calr SetDialUp
	ld xwa, (xsp + 16)
	ld xbc, 0x1C00018
	ld xde, (xsp + 12)
	calr SetDialDown
	lds wa, 1

AcGridBox_EnableDials:
	calr SetDialEnable
	jr AcGridBox_ReturnZero

AcGridBox_GetColText:
	ld xwa, (xsp + 16)
	ld xiz, 0x3E
	jr AcGridBox_CopyText

AcGridBox_GetRowText:
	ld xwa, (xsp + 16)
	ld xiz, 0x42

AcGridBox_CopyText:
	call 0xFA6266
	add xhl, xiz
	ld xwa, (xhl)
	push xwa
	ld xwa, (xsp + 16)
	push xwa
	call Strcpy
	inc 8, xsp
	jr AcGridBox_ReturnZero

AcGridBox_CellSelect:
	ld xwa, (xsp + 16)
	call 0xFA6266
	ld xwa, (xhl + 70)
	ld xbc, xiz
	ld xde, (xsp + 12)
	call 0xFA49B7

AcGridBox_ReturnZero:
	lds32 xhl, 0
	jr AcGridBox_Return

AcGridBox_Default:
	ld xwa, (xsp + 16)
	ld xbc, xiz
	ld xde, (xsp + 12)
	calr PsGridBoxProc

AcGridBox_Return:
	pop xiz
	lda xsp, (xsp + 16)
	ret

GridCheck:
	lda xsp, (xsp - 18)
	ld xwa, xbc
	cp xbc, 0x1E0008D
	jr z, GridCheck_CellSelect
	lds32 xhl, 0
	sub xwa, 0x1C00017
	cp xwa, 0x0
	jr lt, GridCheck_Return
	cp xwa, 0x6
	jr gt, GridCheck_Return
	add xwa, xwa
	add xwa, 0xEAA26C
	ld wa, (xwa)
	lda_24 xix, 0xf9ebfc
	jp_dri 8, 0x07, 0xF0, 0xE0

GridCheck_JumpEnd:
	jr	t, 0x3d

GridCheck_CellSelect:
	lda xbc, (xsp + 10)
	ld xwa, xde
	srl xwa, 0
	ldi_werp 0xE2, 0
	ld (xbc), wa
	lda xwa, (xbc + 2)
	ld (xwa), de
	lda xde, (xsp)
	ld (xbc + 4), xde
	pushm (xwa)
	pushm (xbc)
	pushw 0xEA
	pushw 0xA266
	push xde
	call Audio_SendCommand
	lda xsp, (xsp + 12)
	call 0xFA44D0
	ld xwa, xhl
	lda xde, (xsp + 10)
	ld xbc, 0x1E0008C
	call 0xFA9660
	lds32 xhl, 0

GridCheck_Return:
	lda xsp, (xsp + 18)
	ret

PsEditBoxProc:
	st_dri3b L, 0xFD, 0xE4, 0xFD
	push xiz
	st_dri3l XDE, 0xFD, 0x18, 0x02
	ld xiz, xbc
	st_dri3l XWA, 0xFD, 0x1C, 0x02
	cp xiz, 0x1E0003C
	jrl z, PsEditBox_CanScroll
	cp xiz, 0x1C00018
	jrl z, PsEditBox_ScrollDown
	cp xiz, 0x1C00017
	jrl z, PsEditBox_ScrollUp
	cp xiz, 0x1C0001B
	jrl z, PsEditBox_Release
	cp xiz, 0x1C00007
	jrl z, PsEditBox_OK
	cp xiz, 0x1E0003A
	jrl z, PsEditBox_GetText
	cp xiz, 0x1C0000F
	jrl z, PsEditBox_Confirm
	cp xiz, 0x1C0000E
	jrl z, PsEditBox_Select
	cp xiz, 0x1C0000D
	jrl z, PsEditBox_Paint
	cp xiz, 0x1C00001
	jrl z, PsEditBox_Init
	cp xiz, 0x1E0004D
	jrl nz, PsEditBox_Default
	ld_sril XWA, (xsp + 0x021c)
	call 0xFA6266
	ld xiz, xhl
	lda xwa, (xiz + 46)
	ld xbc, (xwa)
	ld bc, (xbc)
	exts xbc
	cp_sril_rm XBC, 0xFD, 0x18, 0x02
	jr z, PsEditBox_SetIndex_CheckDial
	ld xbc, (xwa)
	ld_sril XWA, (xsp + 0x0218)
	ld (xbc), wa
	ld_sril XWA, (xsp + 0x021c)
	ld xbc, 0x1C0000E
	lds32 xde, 0
	call 0xFA9660
	ld_sril XWA, (xsp + 0x021c)
	ld xbc, 0x1C0000F
	lds32 xde, 0
	call 0xFA9660

PsEditBox_SetIndex_CheckDial:
	ld xwa, (xiz + 46)
	cpw (xwa), 0x1
	jrl nz, PsEditBox_ReturnZero
	cpw (xiz + 44), 0x0
	jr z, PsEditBox_ReturnZero
	ld de, (xiz + 26)
	exts xde
	ld_sril XWA, (xsp + 0x021c)
	ld xbc, 0x1C00017
	calr SetDialUp
	ld de, (xiz + 26)
	exts xde
	ld_sril XWA, (xsp + 0x021c)
	ld xbc, 0x1C00018
	calr SetDialDown
	lds wa, 1
	jr PsEditBox_Init_EnableDials

PsEditBox_Init:
	ld_sril XWA, (xsp + 0x021c)
	ld xbc, xiz
