	lds wa, 4

AcTitleMenu_Confirm_SetRight:
	ld_sriw DE, (xsp + 0x0120)
	sub de, wa
	ld (xbc), de
	lda xbc, (xsp + 12)
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 42)
	call 0xFB2640
	lda xwa, (xsp + 12)
	st_dri3b A, 0xFD, 0x14, 0x01
	ld de, (xbc + 4)
	sub de, (xbc)
	ld xbc, (xsp + 8)
	ld xbc, (xbc + 28)
	call 0xFB275A
	ld (xsp + 6), hl
	lda xwa, (xsp + 12)
	push xwa
	call Strlen
	inc 4, xsp
	ld de, (xsp + 6)
	st_dri3b A, 0xFD, 0x28, 0x01
	ld xix, (xsp + 8)
	lda xwa, (xix + 50)
	cp de, hl
	jr nz, AcTitleMenu_Confirm_MultiLine
	ld xwa, (xwa)	; <-- ICON ID
	or xwa, xwa
	jr z, AcTitleMenu_Confirm_SingleLine

	cpw (xbc), 0x0
	jr z, AcTitleMenu_Confirm_SingleLine

	lda xwa, (xsp + 12)
	ld xbc, (xix + 28)
	call 0xFB26D1
	ld_sriw WA, (xsp + 0x0118)
	sub wa, hl
	dec 5, wa
	st_dri3w WA, 0xFD, 0x2C, 0x01

AcTitleMenu_Confirm_SingleLine:
	st_dri3b W, 0xFD, 0x1C, 0x01
	ld bc, (xwa + 2)
	ld wa, (xwa + 6)
	sub wa, bc
	exts xwa
	divs wa, 0x2
	add bc, wa
	ld wa, (xsp + 4)
	exts xwa
	divs wa, 0x2
	sub bc, wa
	ld wa, bc
	inc 2, wa
	st_dri3b A, 0xFD, 0x2C, 0x01
	ld (xbc + 2), wa
	st_dri3b W, 0xFD, 0x14, 0x01
	lda xde, (xsp + 12)
	ld xix, (xsp + 8)
	ld xhl, (xix + 28)
	push xhl
	pushm (xix + 32)
	pushw 0xF7
	jrl AcTitleMenu_Confirm_RenderTop

AcTitleMenu_Confirm_MultiLine:
	ld hl, (xsp + 6)
	dec 1, hl
	lda xde, (xsp + 12)
	stib_dri 0x07, 0xE8, 0xEC, 0x00
	ld xwa, (xwa)
	or xwa, xwa
	jr z, AcTitleMenu_Confirm_RenderBottom
	cpw (xbc), 0x0
	jr z, AcTitleMenu_Confirm_RenderBottom
	ld wa, (xsp + 6)
	exts xwa
	add xwa, xde
	push xwa
	call Strlen
	ld iz, hl
	lda xwa, (xsp + 16)
	push xwa
	call Strlen
	inc 8, xsp
	ld xwa, (xsp + 8)
	ld xbc, (xwa + 28)
	lda xwa, (xsp + 12)
	cp hl, iz
	jr ugt, AcTitleMenu_Confirm_MultiAdjust
	ld de, (xsp + 6)
	st_dri3b W, 0x07, 0xE0, 0xE8

AcTitleMenu_Confirm_MultiAdjust:
	call 0xFB26D1
	ld_sriw WA, (xsp + 0x0118)
	sub wa, hl
	dec 5, wa
	st_dri3w WA, 0xFD, 0x2C, 0x01

AcTitleMenu_Confirm_RenderBottom:
	st_dri3b W, 0xFD, 0x1C, 0x01
	ld bc, (xwa + 2)
	ld wa, (xwa + 6)
	sub wa, bc
	exts xwa
	divs wa, 0x4
	add bc, wa
	ld wa, (xsp + 4)
	exts xwa
	divs wa, 0x2
	sub bc, wa
	ld wa, bc
	inc 2, wa
	st_dri3b A, 0xFD, 0x2C, 0x01
	ld (xbc + 2), wa
	st_dri3b W, 0xFD, 0x14, 0x01
	lda xde, (xsp + 12)
	ld xix, (xsp + 8)
	ld xhl, (xix + 28)
	push xhl
	pushm (xix + 32)
	pushw 0xF7
	call 0xFACACA
	st_dri3b W, 0xFD, 0x1C, 0x01
	ld bc, (xwa + 2)
	ld wa, (xwa + 6)
	sub wa, bc
	exts xwa
	divs wa, 0x4
	muls wa, 0x3
	add bc, wa
	ld wa, (xsp + 4)
	exts xwa
	divs wa, 0x2
	sub bc, wa
	ld wa, bc
	inc 2, wa
	st_dri3b A, 0xFD, 0x2C, 0x01
	ld (xbc + 2), wa
	st_dri3b W, 0xFD, 0x14, 0x01
	lda xhl, (xsp + 12)
	ld de, (xsp + 6)
	exts xde
	add xde, xhl
	ld xix, (xsp + 8)
	ld xhl, (xix + 28)
	push xhl
	pushm (xix + 32)
	pushw 0xF7

AcTitleMenu_Confirm_RenderTop:
	call 0xFACACA
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 50)	; ICON ID
	or xwa, xwa
	jrl z, AcTitleMenu_OK_Done

	st_dri3b A, 0xFD, 0x24, 0x01
	st_dri3b W, 0xFD, 0x1C, 0x01
	cp_sriw_im 0xFD, 0x28, 0x01, 0x00, 0x00
	jr z, AcTitleMenu_Confirm_IconNoOrient
	ld wa, (xwa + 4)
	sub wa, 0x1A
	ld (xbc), wa
	jr AcTitleMenu_Confirm_DrawIcon

AcTitleMenu_Confirm_IconNoOrient:
	ld wa, (xwa)
	inc 2, wa
	ld (xbc), wa

AcTitleMenu_Confirm_DrawIcon:
	st_dri3b W, 0xFD, 0x1C, 0x01
	ld bc, (xwa + 2)
	ld wa, (xwa + 6)
	sub wa, bc
	exts xwa
	divs wa, 0x2
	add bc, wa
	sub bc, 0xB
	st_dri3b C, 0xFD, 0x24, 0x01
	lda xde, (xhl + 2)
	ld (xde), bc
	st_dri3b W, 0xFD, 0x0C, 0x01
	ld bc, (xhl)
	dec 2, bc
