	push xiz
	ld xiz, xwa
	cp xbc, 0x1C0000F
	jr z, VwMenuBox_Confirm
	cp xbc, 0x1C0000D
	jr z, VwMenuBox_Paint
	ld xwa, xiz
	calr PsMenuBoxProc
	jrl VwMenuBox_Return

