	ld_sriw HL, (xsp + 0x011a)
	add hl, wa
	ld (xbc), hl
	st_dri3w HL, 0xFD, 0x12, 0x01
	st_dri3b A, 0xFD, 0x16, 0x01
	ld xwa, (xde)
	or xwa, xwa
	jr z, VwMenuBox_Confirm_NoIconRight
	cp_sriw_im 0xFD, 0x26, 0x01, 0x00, 0x00
	jr z, VwMenuBox_Confirm_NoIconRight
	ldw wa, 0x1C
	jr VwMenuBox_Confirm_SetRight

