	ld xix, (xsp + 6)
	lda xwa, (xix + 46)
	cp de, hl
	jr nz, VwMenuBox_Confirm_MultiLine
	ld xwa, (xwa)
	or xwa, xwa
	jr z, VwMenuBox_Confirm_SingleLine
	cpw (xbc), 0x0
	jr z, VwMenuBox_Confirm_SingleLine
	lda xwa, (xsp + 10)
	ld xbc, (xix + 28)
