PsEditSwBox_HitTest:
	ld xwa, xiz
	call 0xFA6266
	ld (xsp + 4), xhl
	ld xwa, xiz
	call 0xFA5EA5
	cps hl, 0
	jrl z, PsEditSwBox_ReturnZero
	ld xwa, 0x2600024
	ld xbc, 0x1E00029
	ld xde, (xsp + 20)
	call 0xFA9660
	ld xwa, (xsp + 4)
	ld wa, (xwa + 36)
	extz xwa
	cp xwa, xhl
	jr nz, PsEditSwBox_ReturnZero
	lds32 xhl, 1
	jr PsEditSwBox_Return

PsEditSwBox_Repaint:
	ld xwa, xiz
	ld xde, (xsp + 20)
	calr VwBoxProc
	ld xwa, xiz
	call 0xFA5EA5
	cps hl, 0
	jr z, PsEditSwBox_Repaint_UpdateBounds
	ld xwa, xiz
	ld xbc, 0x1C0000C
	lds32 xde, 0
	call 0xFA9660
	jr PsEditSwBox_ReturnZero

