;
; Output:
;   HL = pixel color (8-bit index, zero-extended to 16-bit)
;        Returns 0 if coordinates fail validation
; =============================================================================
ReadPixel:
	push xiz
	ld xiz, xwa
	ld xwa, xiz
	calr IsPointOnScreen
	cps hl, 0
	jr z, LABEL_FAA7E0
	ld wa, (xiz + 2)
	exts xwa
	ld xbc, xwa
	sll xbc, 2
	add xbc, xwa
	sll xbc, 6
	ld wa, (xiz)
	exts xwa
	add xwa, xbc
	ld xbc, 0x43C00
	add xbc, xwa
	ld l, (xbc)
	extz hl
	jr LABEL_FAA7E2

LABEL_FAA7E0:
	lds hl, 0

LABEL_FAA7E2:
	pop xiz
	ret

; =============================================================================
; ModifyPixel - Write a pixel to offscreen buffer 1
;
; Sets a single pixel at (x, y) in OFFSCREEN_BUFFER_1 (0x43C00).
; Color 0xF7 is treated as transparent (no-op). Color 0xF5 triggers a
; read-back from a secondary buffer (at address stored at 0x0304B2).
;
; Input:
;   XWA = pointer to coordinate pair: word[0]=x, word[2]=y
;   BC  = color index (low byte)
;
; Address calculation: OFFSCREEN_BUFFER_1 + y*320 + x
; =============================================================================
ModifyPixel:
	dec 4, xsp
	pushw iz
	ld iz, bc
	ld (xsp + 2), xwa
	ld xwa, (xsp + 2)
	calr IsPointOnScreen
	cps hl, 0
	jr z, LABEL_FAA840
	cp iz, 0xF7
	jr z, LABEL_FAA840
	cp iz, 0xF5
	jr nz, LABEL_FAA81C
	ld xwa, (xsp + 2)
	ld bc, (xwa + 2)
	muls bc, 0x140
	add bc, (xwa)
	extz xbc
	addda32_24 xbc, 197714
	ld a, (xbc)
	ldfr_berp A, 0xF8
	extz iz

LABEL_FAA81C:
	ld xde, (xsp + 2)
	ld wa, (xde + 2)
	exts xwa
	ld xbc, xwa
	sll xbc, 2
	add xbc, xwa
	sll xbc, 6
	ld wa, (xde)
	exts xwa
	add xwa, xbc
	ld xbc, 0x43C00
	add xbc, xwa
	ldto_berp A, 0xF8
	ld (xbc), a

LABEL_FAA840:
	popw iz
	inc 4, xsp
	ret

; =============================================================================
; ModifyPixelEx - Extended pixel operation with multiple drawing modes
;
; Performs a pixel operation at (x, y) in OFFSCREEN_BUFFER_1 (0x43C00)
; using one of several drawing modes specified by DE.
;
; Input:
;   XWA = pointer to coordinate pair: word[0]=x, word[2]=y
;   BC  = color index (low byte)
;   DE  = drawing mode:
;         < 0x201: use translated buffer pointer
;         0x201: direct write  â€” buffer[y*320+x] = color
;         0x202: clear pixel   â€” buffer[y*320+x] = 0x00
;         0x203: OR operation  â€” buffer[y*320+x] |= color
;         0x204: AND operation â€” buffer[y*320+x] &= color
;         0x205: XOR operation â€” buffer[y*320+x] ^= color
;
; Special colors:
;   0xF7 = transparent (no-op)
;   0xF5 = read-back from secondary buffer (0x0304B2)
; =============================================================================
ModifyPixelEx:
	dec 6, xsp
	pushw iz
	ld (xsp + 2), de
	ld iz, bc
	ld (xsp + 4), xwa
	ld xwa, (xsp + 4)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawLine_Epilogue
	ld wa, iz
	calr IsColorValid
	cps hl, 0
	jrl z, DrawLine_Epilogue
	ld xwa, (xsp + 4)
	ld bc, iz
	calr ClampColorToRange
	ld iz, hl
	cp iz, 0xF7
	jrl z, DrawLine_Epilogue
	cp iz, 0xF5
	jr nz, LABEL_FAA895
	ld xwa, (xsp + 4)
	ld bc, (xwa + 2)
	muls bc, 0x140
	add bc, (xwa)
	extz xbc
	addda32_24 xbc, 197714
	ld a, (xbc)
	ldfr_berp A, 0xF8
	extz iz

LABEL_FAA895:
	cpw (xsp + 2), 0x201
	jr ge, LABEL_FAA8CF
	ld xwa, (xsp + 4)
	ld bc, (xsp + 2)
	calr ClampColorToRange
	ld (xsp + 2), hl
	ld xde, (xsp + 4)
	ld wa, (xde + 2)
	exts xwa
	ld xbc, xwa
	sll xbc, 2
	add xbc, xwa
	sll xbc, 6
	ld wa, (xde)
	exts xwa
	add xwa, xbc
	ld xbc, 0x43C00
	add xbc, xwa
	ld wa, (xsp + 2)
	ld (xbc), a
	jrl DrawLine_Epilogue

LABEL_FAA8CF:
	ldto_berp C, 0xF8
	cpw (xsp + 2), 0x205
	jrl z, LABEL_FAA965
	lda_24 xde, 0x043c00
	cpw (xsp + 2), 0x204
	jr z, LABEL_FAA947
	ld xhl, xde
	ld xiy, (xsp + 4)
	lda xix, (xiy + 2)
	ld wa, (xix)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	cpw (xsp + 2), 0x203
	jr z, LABEL_FAA938
	cpw (xsp + 2), 0x202
	jr z, LABEL_FAA91D
	cpw (xsp + 2), 0x201
	jr nz, DrawLine_Epilogue
	ld wa, (xiy)
	exts xwa
	add xwa, xde
	add xhl, xwa
	ld (xhl), c
	jr DrawLine_Epilogue

LABEL_FAA91D:
	ld wa, (xix)
	ld bc, wa
	exts xbc
	ld xde, xbc
	sll xde, 2
	add xde, xbc
	sll xde, 6
	exts xwa
	add xwa, xde
	add xhl, xwa
	ld (xhl), 0x0
	jr DrawLine_Epilogue

LABEL_FAA938:
	ld xwa, (xsp + 4)
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	add xhl, xwa
	or (xhl), c
	jr DrawLine_Epilogue

LABEL_FAA947:
	ld xix, (xsp + 4)
	ld wa, (xix + 2)
	exts xwa
	ld xhl, xwa
	sll xhl, 2
	add xhl, xwa
	sll xhl, 6
	ld wa, (xix)
	exts xwa
	add xwa, xhl
	add xde, xwa
	and (xde), c
	jr DrawLine_Epilogue

LABEL_FAA965:
	ld xhl, (xsp + 4)
	ld wa, (xhl + 2)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld wa, (xhl)
	exts xwa
	add xwa, xde
	ld xde, 0x43C00
	add xde, xwa
	xor (xde), c

DrawLine_Epilogue:
	popw iz
	inc 6, xsp
	ret

; =============================================================================
; DrawLine - Draw a line between two points (Bresenham algorithm)
;
; Draws a line from point A to point B on OFFSCREEN_BUFFER_1 (0x43C00).
; Uses Bresenham's line algorithm with separate fast paths for horizontal,
; vertical, and diagonal lines.
;
; Input:
;   XWA = pointer to point A: word[0]=x1, word[2]=y1
;   XBC = pointer to point B: word[0]=x2, word[2]=y2
;   DE  = color index (low byte)
;
; Special color 0xF5 reads the pixel from a secondary buffer instead of
; using a fixed color (used for pattern/texture line drawing).
;
; Calls SetChangeRect on completion to mark the drawn region as dirty.
; =============================================================================
DrawLine:
	dec 6, xsp
	push xiz
	ld (xsp + 4), de
	ld (xsp + 6), xbc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawLine_DeferredPath
	cpdi16_24 197710, 0
	jr z, DrawLine_Return
	ld xwa, xiz
	ld xbc, (xsp + 6)
	ld de, (xsp + 4)
	calr DrawLine_Impl
	jr DrawLine_Return

DrawLine_DeferredPath:
	ldw wa, 0xE
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfaa9e3
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	ldiw
	ldiw
	ld xbc, (xsp + 6)
	ld xiy, xbc
	lda xix, (xwa + 8)
	ldiw
	ldiw
	ld bc, (xsp + 4)
	ld (xwa + 12), bc
	calr DisplayCmd_DequeueAndExecute

DrawLine_Return:
	pop xiz
	inc 6, xsp
	ret

DrawLine_ParamBlock:
	.byte 0xb8, 0x04, 0x33, 0xb8, 0x08, 0x31, 0x98, 0x0c
	.byte 0x22, 0xd2, 0x4e, 0x04, 0x03, 0x3f, 0x00, 0x00
	.byte 0xb0, 0xf6, 0xeb, 0x88, 0x1e, 0x01, 0x00, 0x0e

DrawLine_Impl:
	lda xsp, (xsp - 66)
	push xiz
	ld (xsp + 60), de
	ld (xsp + 62), xbc
	ld (xsp + 66), xwa
	ld xwa, (xsp + 66)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawLine_Impl_Return
	ld xwa, (xsp + 62)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawLine_Impl_Return
	ld xde, 0xFFFFFFFF
	ld xwa, (xsp + 62)
	ld bc, (xwa)
	ld xwa, (xsp + 66)
	cp bc, (xwa)
	jr le, DrawLine_Impl_XStepPositive
	lds32 xde, 1

DrawLine_Impl_XStepPositive:
	ld (xsp + 12), xde
	ld xbc, 0xFFFFFFFF
	ld xwa, (xsp + 62)
	ld wa, (xwa + 2)
	ld (xsp + 46), wa
	ld xwa, (xsp + 66)
	ld wa, (xwa + 2)
	ld (xsp + 44), wa
	ld wa, (xsp + 46)
	cp wa, (xsp + 44)
	jr le, DrawLine_Impl_YStepPositive
	lds32 xbc, 1

DrawLine_Impl_YStepPositive:
	ld (xsp + 16), xbc
	ld xwa, (xsp + 12)
	cp xwa, 0x1
	jr nz, DrawLine_Impl_CalcDxReverse
	ld xwa, (xsp + 62)
	ld bc, (xwa)
	ld xwa, (xsp + 66)
	sub bc, (xwa)
	jr DrawLine_Impl_CalcDxDone

DrawLine_Impl_CalcDxReverse:
	ld xwa, (xsp + 66)
	ld bc, (xwa)
	ld xwa, (xsp + 62)
	sub bc, (xwa)

DrawLine_Impl_CalcDxDone:
	exts xbc
	ld (xsp + 4), xbc
	ld xwa, (xsp + 16)
	cp xwa, 0x1
	jr nz, DrawLine_Impl_CalcDyReverse
	ld wa, (xsp + 46)
	sub wa, (xsp + 44)
	jr DrawLine_Impl_CalcDyDone

DrawLine_Impl_CalcDyReverse:
	ld wa, (xsp + 44)
	sub wa, (xsp + 46)

DrawLine_Impl_CalcDyDone:
	exts xwa
	ld (xsp + 8), xwa
	ld xwa, (xsp + 4)
	or xwa, xwa
	jr nz, DrawLine_Impl_CopyStartPos
	ld xwa, (xsp + 8)
	or xwa, xwa
	jrl z, DrawLine_Impl_Return

DrawLine_Impl_CopyStartPos:
	ld xwa, (xsp + 66)
	ld xiy, xwa
	lda xix, (xsp + 56)
	ldiw
	ldiw
	lda_24 xwa, 0x043c00
	ld (xsp + 36), xwa
	ld (xsp + 20), xwa
	ld xwa, (xsp + 4)
	ld (xsp + 40), xwa
	sla xwa, 0
	ld (xsp + 40), xwa
	ld xbc, (xsp + 8)
	sla xbc, 0
	ld wa, (xsp + 46)
	exts xwa
	ld (xsp + 44), xwa
	ld xwa, xbc
	ld xbc, (xsp + 4)
	call Math_DivideSigned32
	ld (xsp + 28), xhl
	ld xwa, (xsp + 40)
	ld xbc, (xsp + 8)
	call Math_DivideSigned32
	ld (xsp + 24), xhl
	ld xbc, (xsp + 44)
	ld (xsp + 32), xbc
	ld xwa, xbc
	sll xwa, 2
	ld (xsp + 32), xwa
	add (xsp + 32), xbc
	ld xwa, (xsp + 32)
	sll xwa, 6
	ld (xsp + 32), xwa
	ld xwa, (xsp + 4)
	ld bc, wa
	inc 1, bc
	cpw (xsp + 60), 0xF5
	jrl z, DrawLine_Impl_PatternSetup
	or xwa, xwa
	jr nz, DrawLine_Impl_HorizontalCheck
	lds32 xbc, 0
	ld xwa, (xsp + 8)
	cp xwa, 0x0
	jrl lt, DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_VerticalLoop:
	lda xde, (xsp + 56)
	lda xwa, (xde + 2)
	ld (xsp + 44), xwa
	ld wa, (xwa)
	exts xwa
	ld xhl, xwa
	sll xhl, 2
	add xhl, xwa
	sll xhl, 6
	ld wa, (xde)
	exts xwa
	add xwa, xhl
	ld xde, (xsp + 36)
	add xde, xwa
	ld wa, (xsp + 60)
	ld (xde), a
	ld xde, (xsp + 16)
	ld xwa, (xsp + 44)
	add (xwa), de
	inc 1, xbc
	cp xbc, (xsp + 8)
	jr le, DrawLine_Impl_VerticalLoop
	jrl DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_HorizontalCheck:
	ld xwa, (xsp + 8)
	or xwa, xwa
	jr nz, DrawLine_Impl_SteepCheck
	ld wa, (xsp + 60)
	extz wa
	pushw bc
	pushw wa
	ld xwa, (xsp + 16)
	cp xwa, 0x1
	jr nz, DrawLine_Impl_HorzCalcNegDir
	lda xwa, (xsp + 60)
	ld bc, (xwa + 2)
	exts xbc
	ld xde, xbc
	sll xde, 2
	add xde, xbc
	sll xde, 6
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	ld xbc, (xsp + 24)
	add xbc, xwa
	push xbc
	jr DrawLine_Impl_HorzMemset

DrawLine_Impl_HorzCalcNegDir:
	ld xwa, (xsp + 66)
	ld bc, (xwa)
	ld xwa, (xsp + 36)
	st_dri3b W, 0x07, 0xE0, 0xE4
	ld xbc, (xsp + 24)
	add xbc, xwa
	push xbc

DrawLine_Impl_HorzMemset:
	call Memset
	inc 8, xsp
	jrl DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_SteepCheck:
	ld xwa, (xsp + 8)
	cp xwa, (xsp + 4)
	jr le, DrawLine_Impl_ShallowSetup
	ld xwa, (xsp + 12)
	ld xbc, (xsp + 24)
	call Math_MultiplyAccumulate
	ld (xsp + 12), xhl
	lda xwa, (xsp + 56)
	ld (xsp + 40), xwa
	ld wa, (xwa)
	exts xwa
	ld (xsp + 4), xwa
	sla xwa, 0
	ld (xsp + 4), xwa
	ld xwa, 0x8000
	add (xsp + 4), xwa
	lds32 xbc, 0
	ld xwa, (xsp + 8)
	cp xwa, 0x0
	jrl lt, DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_SteepLoop:
	ld xhl, (xsp + 40)
	lda xwa, (xhl + 2)
	ld (xsp + 44), xwa
	ld wa, (xwa)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld wa, (xhl)
	exts xwa
	add xwa, xde
	ld xde, (xsp + 36)
	add xde, xwa
	ld wa, (xsp + 60)
	ld (xde), a
	ld xwa, (xsp + 12)
	add (xsp + 4), xwa
	ld xde, (xsp + 4)
	sra xde, 0
	ld (xhl), de
	ld xde, (xsp + 16)
	ld xwa, (xsp + 44)
	add (xwa), de
	inc 1, xbc
	cp xbc, (xsp + 8)
	jr le, DrawLine_Impl_SteepLoop
	jrl DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_ShallowSetup:
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 28)
	call Math_MultiplyAccumulate
	ld (xsp + 16), xhl
	lda xwa, (xsp + 56)
	ld (xsp + 40), xwa
	inc 2, xwa
	ld (xsp + 44), xwa
	ld wa, (xwa)
	exts xwa
	ld (xsp + 8), xwa
	sla xwa, 0
	ld (xsp + 8), xwa
	ld xwa, 0x8000
	add (xsp + 8), xwa
	lds32 xbc, 0
	ld xwa, (xsp + 4)
	cp xwa, 0x0
	jrl lt, DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_ShallowLoop:
	ld xix, (xsp + 44)
	ld wa, (xix)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld xhl, (xsp + 40)
	ld wa, (xhl)
	exts xwa
	add xwa, xde
	ld xde, (xsp + 36)
	add xde, xwa
	ld wa, (xsp + 60)
	ld (xde), a
	ld xwa, (xsp + 16)
	add (xsp + 8), xwa
	ld xde, (xsp + 8)
	sra xde, 0
	ld (xix), de
	ld xde, (xsp + 12)
	add (xhl), de
	inc 1, xbc
	cp xbc, (xsp + 4)
	jr le, DrawLine_Impl_ShallowLoop
	jrl DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_PatternSetup:
	lda xwa, (xsp + 56)
	ld (xsp + 40), xwa
	inc 2, xwa
	ld (xsp + 44), xwa
	ld xwa, (xsp + 4)
	or xwa, xwa
	jr nz, DrawLine_Impl_PatternNonVert
	lds32 xbc, 0
	ld xwa, (xsp + 8)
	cp xwa, 0x0
	jrl lt, DrawLine_Impl_BuildDirtyRect
	ld xwa, (xsp + 40)
	ld (xsp + 32), xwa
	ld xde, (xsp + 44)
	ld xiy, (xsp + 36)
	ld xix, (xsp + 40)
	ld xhl, (xsp + 16)

DrawLine_Impl_PatternVertLoop:
	ld wa, (xde)
	ld (xsp + 46), wa
	ld wa, (xsp + 46)
	exts xwa
	ld xiz, xwa
	sll xiz, 2
	add xiz, xwa
	sll xiz, 6
	ld xwa, (xsp + 32)
	ld wa, (xwa)
	exts xwa
	add xwa, xiz
	ld xiz, xiy
	add xiz, xwa
	ld wa, (xsp + 46)
	muls wa, 0x140
	add wa, (xix)
	extz xwa
	addda32_24 xwa, 197714
	ld a, (xwa)
	ld (xiz), a
	add (xde), hl
	inc 1, xbc
	cp xbc, (xsp + 8)
	jr le, DrawLine_Impl_PatternVertLoop
	jrl DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_PatternNonVert:
	ld xwa, (xsp + 8)
	or xwa, xwa
	jr nz, DrawLine_Impl_PatternDiagCheck
	pushw bc
	ld xwa, (xsp + 14)
	cp xwa, 0x1
	jr nz, DrawLine_Impl_PatternHorzNegDir
	ld xwa, (xsp + 46)
	ld wa, (xwa)
	ld (xsp + 48), wa
	ld bc, (xsp + 48)
	muls bc, 0x140
	ld xde, (xsp + 42)
	add bc, (xde)
	extz xbc
	addda32_24 xbc, 197714
	push xbc
	ld wa, (xsp + 52)
	exts xwa
	ld xbc, xwa
	sll xbc, 2
	add xbc, xwa
	sll xbc, 6
	ld wa, (xde)
	exts xwa
	add xwa, xbc
	ld xbc, (xsp + 26)
	add xbc, xwa
	push xbc
	jr DrawLine_Impl_PatternHorzMemcpy

DrawLine_Impl_PatternHorzNegDir:
	ld xwa, (xsp + 46)
	ld bc, (xwa)
	muls bc, 0x140
	ld xwa, (xsp + 42)
	add bc, (xwa)
	extz xbc
	addda32_24 xbc, 197714
	push xbc
	ld xwa, (xsp + 68)
	ld bc, (xwa)
	ld xwa, (xsp + 38)
	st_dri3b W, 0x07, 0xE0, 0xE4
	ld xbc, (xsp + 26)
	add xbc, xwa
	push xbc

DrawLine_Impl_PatternHorzMemcpy:
	call 0xFF0D99
	lda xsp, (xsp + 10)
	jrl DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_PatternDiagCheck:
	ld xwa, (xsp + 8)
	cp xwa, (xsp + 4)
	jrl le, DrawLine_Impl_PatternShallowSetup
	ld xwa, (xsp + 12)
	ld xbc, (xsp + 24)
	call Math_MultiplyAccumulate
	ld (xsp + 12), xhl
	ld xwa, (xsp + 40)
	ld (xsp + 32), xwa
	ld wa, (xwa)
	exts xwa
	ld (xsp + 4), xwa
	sla xwa, 0
	ld (xsp + 4), xwa
	ld xwa, 0x8000
	add (xsp + 4), xwa
	lds32 xbc, 0
	ld xwa, (xsp + 8)
	cp xwa, 0x0
	jrl lt, DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_PatternSteepLoop:
	ld xhl, (xsp + 32)
	lda xwa, (xhl + 2)
	ld (xsp + 42), xwa
	ld wa, (xwa)
	ld (xsp + 46), wa
	ld wa, (xsp + 46)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld wa, (xhl)
	st_dri3b B, 0x07, 0xE8, 0xE0
	ld xwa, (xsp + 36)
	add xwa, xde
	ld (xsp + 28), xwa
	ld de, (xsp + 46)
	muls de, 0x140
	add de, (xhl)
	ld wa, de
	extz xwa
	addda32_24 xwa, 197714
	ld xde, (xsp + 28)
	ld a, (xwa)
	ld (xde), a
	ld xwa, (xsp + 12)
	add (xsp + 4), xwa
	ld xde, (xsp + 4)
	sra xde, 0
	ld (xhl), de
	ld xde, (xsp + 16)
	ld xwa, (xsp + 42)
	add (xwa), de
	inc 1, xbc
	cp xbc, (xsp + 8)
	jr le, DrawLine_Impl_PatternSteepLoop
	jrl DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_PatternShallowSetup:
	ld xwa, (xsp + 16)
	ld xbc, (xsp + 28)
	call Math_MultiplyAccumulate
	ld (xsp + 16), xhl
	ld xwa, (xsp + 40)
	ld (xsp + 32), xwa
	ld xwa, (xsp + 44)
	ld (xsp + 40), xwa
	ld wa, (xwa)
	exts xwa
	ld (xsp + 8), xwa
	sla xwa, 0
	ld (xsp + 8), xwa
	ld xwa, 0x8000
	add (xsp + 8), xwa
	lds32 xbc, 0
	ld xwa, (xsp + 4)
	cp xwa, 0x0
	jr lt, DrawLine_Impl_BuildDirtyRect

DrawLine_Impl_PatternShallowLoop:
	ld xix, (xsp + 40)
	ld wa, (xix)
	ld (xsp + 46), wa
	ld wa, (xsp + 46)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld xhl, (xsp + 32)
	ld wa, (xhl)
	st_dri3b B, 0x07, 0xE8, 0xE0
	ld xwa, (xsp + 36)
	add xwa, xde
	ld (xsp + 28), xwa
	ld de, (xsp + 46)
	muls de, 0x140
	add de, (xhl)
	ld wa, de
	extz xwa
	addda32_24 xwa, 197714
	ld xde, (xsp + 28)
	ld a, (xwa)
	ld (xde), a
	ld xwa, (xsp + 16)
	add (xsp + 8), xwa
	ld xde, (xsp + 8)
	sra xde, 0
	ld (xix), de
	ld xde, (xsp + 12)
	add (xhl), de
	inc 1, xbc
	cp xbc, (xsp + 4)
	jr le, DrawLine_Impl_PatternShallowLoop

DrawLine_Impl_BuildDirtyRect:
	lda xwa, (xsp + 48)
	ld xde, (xsp + 66)
	ld bc, (xde + 2)
	ld (xwa + 2), bc
	ld bc, (xde)
	ld (xwa), bc
	ld xde, (xsp + 62)
	ld bc, (xde)
	ld (xwa + 4), bc
	ld bc, (xde + 2)
	ld (xwa + 6), bc
	calr SetChangeRect

DrawLine_Impl_Return:
	pop xiz
	lda xsp, (xsp + 66)
	ret

; =============================================================================
; DrawLineEx - Extended line drawing with multiple drawing modes
;
; Like DrawLine, but supports all drawing modes from ModifyPixelEx:
; direct write, clear, OR, AND, XOR. Also supports the 0xF5 pattern mode
; which reads pixel colors from a secondary buffer.
;
; Input:
;   XWA = pointer to point A: word[0]=x1, word[2]=y1
;   XBC = pointer to point B: word[0]=x2, word[2]=y2
;   DE  = drawing mode (same codes as ModifyPixelEx: 0x201-0x205)
;
; Uses Bresenham's algorithm with optimized paths for axis-aligned and
; diagonal lines. Calls SetChangeRect to update dirty region.
; =============================================================================
DrawLineEx:
	lda xsp, (xsp - 50)
	push xiz
	ld (xsp + 44), de
	ld (xsp + 46), xbc
	ld (xsp + 50), xwa
	ld xwa, (xsp + 50)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawLineEx_Return
	ld xwa, (xsp + 46)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawLineEx_Return
	ld xde, 0xFFFFFFFF
	ld xwa, (xsp + 46)
	ld bc, (xwa)
	ld xwa, (xsp + 50)
	cp bc, (xwa)
	jr le, DrawLineEx_XStepPositive
	lds32 xde, 1

DrawLineEx_XStepPositive:
	ld (xsp + 12), xde
	ld xde, 0xFFFFFFFF
	ld xwa, (xsp + 46)
	inc 2, xwa
	ld (xsp + 20), xwa
	ld xwa, (xsp + 50)
	inc 2, xwa
	ld (xsp + 24), xwa
	ld xwa, (xsp + 20)
	ld bc, (xwa)
	ld xwa, (xsp + 24)
	ld hl, (xwa)
	cp bc, hl
	jr le, DrawLineEx_YStepPositive
	lds32 xde, 1

DrawLineEx_YStepPositive:
	ld (xsp + 16), xde
	ld xwa, (xsp + 12)
	cp xwa, 0x1
	jr nz, DrawLineEx_CalcDxReverse
	ld xwa, (xsp + 46)
	ld de, (xwa)
	ld xwa, (xsp + 50)
	sub de, (xwa)
	jr DrawLineEx_CalcDxDone

DrawLineEx_CalcDxReverse:
	ld xwa, (xsp + 50)
	ld de, (xwa)
	ld xwa, (xsp + 46)
	sub de, (xwa)

DrawLineEx_CalcDxDone:
	exts xde
	ld (xsp + 4), xde
	ld xwa, (xsp + 16)
	cp xwa, 0x1
	jr nz, DrawLineEx_CalcDyReverse
	sub bc, hl
	ld hl, bc
	jr DrawLineEx_CalcDyDone

DrawLineEx_CalcDyReverse:
	sub hl, bc

DrawLineEx_CalcDyDone:
	exts xhl
	ld (xsp + 8), xhl
	ld xwa, (xsp + 4)
	or xwa, xwa
	jr nz, DrawLineEx_CopyStartPos
	ld xwa, (xsp + 8)
	or xwa, xwa
	jrl z, DrawLineEx_Return

DrawLineEx_CopyStartPos:
	ld xwa, (xsp + 50)
	ld xiy, xwa
	lda xix, (xsp + 40)
	ldiw
	ldiw
	ld xwa, (xsp + 4)
	or xwa, xwa
	jrl nz, DrawLineEx_HorzCheck
	lds32 xwa, 0
	ld (xsp + 28), xwa
	ld xwa, (xsp + 8)
	cp xwa, 0x0
	jrl lt, DrawLineEx_BuildDirtyRect

DrawLineEx_VertLoop:
	ld wa, (xsp + 58)
	cpw (xsp + 58), 0x205
	jr z, DrawLineEx_VertXorPixel
	cp wa, 0x201
	jrl nz, DrawLineEx_Return
	lda xwa, (xsp + 40)
	ld bc, (xwa + 2)
	exts xbc
	ld xde, xbc
	sll xde, 2
	add xde, xbc
	sll xde, 6
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	ld xbc, 0x43C00
	add xbc, xwa
	ld wa, (xsp + 44)
	ld (xbc), a

DrawLineEx_VertAdvance:
	ld xwa, (xsp + 16)
	add (xsp + 42), wa
	lds32 xwa, 1
	add (xsp + 28), xwa
	ld xwa, (xsp + 28)
	cp xwa, (xsp + 8)
	jr le, DrawLineEx_VertLoop
	jrl DrawLineEx_BuildDirtyRect

DrawLineEx_VertXorPixel:
	lda xwa, (xsp + 40)
	ld bc, (xwa + 2)
	exts xbc
	ld xde, xbc
	sll xde, 2
	add xde, xbc
	sll xde, 6
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	ld xbc, 0x43C00
	add xbc, xwa
	ld wa, (xsp + 44)
	xor (xbc), a
	jr DrawLineEx_VertAdvance

DrawLineEx_HorzCheck:
	ld xwa, (xsp + 8)
	or xwa, xwa
	jrl nz, DrawLineEx_DiagSetup
	lds32 xwa, 0
	ld (xsp + 28), xwa
	ld xwa, (xsp + 4)
	cp xwa, 0x0
	jrl lt, DrawLineEx_BuildDirtyRect

DrawLineEx_HorzLoop:
	ld wa, (xsp + 58)
	cpw (xsp + 58), 0x205
	jr z, DrawLineEx_HorzXorPixel
	cp wa, 0x201
	jrl nz, DrawLineEx_Return
	lda xwa, (xsp + 40)
	ld bc, (xwa + 2)
	exts xbc
	ld xde, xbc
	sll xde, 2
	add xde, xbc
	sll xde, 6
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	ld xbc, 0x43C00
	add xbc, xwa
	ld wa, (xsp + 44)
	ld (xbc), a

DrawLineEx_HorzAdvance:
	ld xwa, (xsp + 12)
	add (xsp + 40), wa
	lds32 xwa, 1
	add (xsp + 28), xwa
	ld xwa, (xsp + 28)
	cp xwa, (xsp + 4)
	jr le, DrawLineEx_HorzLoop
	jrl DrawLineEx_BuildDirtyRect

DrawLineEx_HorzXorPixel:
	lda xwa, (xsp + 40)
	ld bc, (xwa + 2)
	exts xbc
	ld xde, xbc
	sll xde, 2
	add xde, xbc
	sll xde, 6
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	ld xbc, 0x43C00
	add xbc, xwa
	ld wa, (xsp + 44)
	xor (xbc), a
	jr DrawLineEx_HorzAdvance

DrawLineEx_DiagSetup:
	lda xwa, (xsp + 40)
	ld (xsp + 28), xwa
	ld xwa, (xsp + 8)
	cp xwa, (xsp + 4)
	jrl le, DrawLineEx_ShallowSetup
	ld xwa, (xsp + 4)
	sla xwa, 0
	ld xbc, (xsp + 8)
	call Math_DivideSigned32
	ld xiz, xhl
	ld xwa, (xsp + 12)
	ld xbc, xiz
	call Math_MultiplyAccumulate
	ld (xsp + 12), xhl
	ld xbc, (xsp + 28)
	ld xwa, xbc
	ld wa, (xwa)
	exts xwa
	ld (xsp + 4), xwa
	sla xwa, 0
	ld (xsp + 4), xwa
	ld xwa, 0x8000
	add (xsp + 4), xwa
	lds32 xwa, 0
	ld (xsp + 28), xwa
	ld xwa, (xsp + 8)
	cp xwa, 0x0
	jrl lt, DrawLineEx_BuildDirtyRect

DrawLineEx_SteepLoop:
	ld iz, (xsp + 58)
	lda xiy, (xbc + 2)
	ld wa, (xiy)
	exts xwa
	ld xix, xwa
	sll xix, 2
	add xix, xwa
	sll xix, 6
	ld de, (xsp + 44)
	lda_24 xhl, 0x043c00
	cpw (xsp + 58), 0x205
	jr z, DrawLineEx_SteepXorPixel
	cp iz, 0x201
	jrl nz, DrawLineEx_Return
	ld wa, (xbc)
	exts xwa
	add xwa, xix
	add xhl, xwa
	ld (xhl), e

DrawLineEx_SteepAdvance:
	ld xwa, (xsp + 12)
	add (xsp + 4), xwa
	ld xwa, (xsp + 4)
	sra xwa, 0
	ld (xbc), wa
	ld xwa, (xsp + 16)
	add (xiy), wa
	lds32 xwa, 1
	add (xsp + 28), xwa
	ld xwa, (xsp + 28)
	cp xwa, (xsp + 8)
	jr le, DrawLineEx_SteepLoop
	jrl DrawLineEx_BuildDirtyRect

DrawLineEx_SteepXorPixel:
	ld wa, (xbc)
	exts xwa
	add xwa, xix
	add xhl, xwa
	xor (xhl), e
	jr DrawLineEx_SteepAdvance

DrawLineEx_ShallowSetup:
	ld xwa, (xsp + 8)
	sla xwa, 0
	ld xbc, (xsp + 4)
	call Math_DivideSigned32
	ld xiz, xhl
	ld xwa, (xsp + 16)
	ld xbc, xiz
	call Math_MultiplyAccumulate
	ld (xsp + 16), xhl
	ld xbc, (xsp + 28)
	ld xwa, xbc
	lda xde, (xwa + 2)
	ld wa, (xde)
	exts xwa
	ld (xsp + 8), xwa
	sla xwa, 0
	ld (xsp + 8), xwa
	ld xwa, 0x8000
	add (xsp + 8), xwa
	lds32 xwa, 0
	ld (xsp + 28), xwa
	ld xwa, (xsp + 4)
	cp xwa, 0x0
	jr lt, DrawLineEx_BuildDirtyRect

DrawLineEx_ShallowLoop:
	ld iz, (xsp + 58)
	ld wa, (xsp + 44)
	ldfr_berp A, 0xF0
	lda_24 xiy, 0x043c00
	ld wa, (xde)
	exts xwa
	ld xhl, xwa
	sll xhl, 2
	add xhl, xwa
	sll xhl, 6
	cpw (xsp + 58), 0x205
	jr z, DrawLineEx_ShallowXorPixel
	cp iz, 0x201
	jr nz, DrawLineEx_Return
	ld wa, (xbc)
	exts xwa
	add xwa, xhl
	add xiy, xwa
	ldto_berp A, 0xF0
	ld (xiy), a

DrawLineEx_ShallowAdvance:
	ld xwa, (xsp + 16)
	add (xsp + 8), xwa
	ld xwa, (xsp + 8)
	sra xwa, 0
	ld (xde), wa
	ld xwa, (xsp + 12)
	add (xbc), wa
	lds32 xwa, 1
	add (xsp + 28), xwa
	ld xwa, (xsp + 28)
	cp xwa, (xsp + 4)
	jr le, DrawLineEx_ShallowLoop

DrawLineEx_BuildDirtyRect:
	lda xwa, (xsp + 32)
	ld xbc, (xsp + 24)
	ld bc, (xbc)
	ld (xwa + 2), bc
	ld xbc, (xsp + 50)
	ld bc, (xbc)
	ld (xwa), bc
	ld xbc, (xsp + 46)
	ld bc, (xbc)
	ld (xwa + 4), bc
	ld xbc, (xsp + 20)
	ld bc, (xbc)
	ld (xwa + 6), bc
	calr SetChangeRect
	jr DrawLineEx_Return

DrawLineEx_ShallowXorPixel:
	ld wa, (xbc)
	exts xwa
	add xwa, xhl
	add xiy, xwa
	ldto_berp A, 0xF0
	xor (xiy), a
	jr DrawLineEx_ShallowAdvance

DrawLineEx_Return:
	pop xiz
	lda xsp, (xsp + 50)
	retd 0x2

; =============================================================================
; DrawBox - Draw a filled rectangle on the offscreen buffer
;
; Fills a rectangular area defined by a 4-word bounding box with a solid color.
; Clips to screen bounds (0,0)-(319,239).
;
; Input:
;   XWA = pointer to bounding box: {x_min, y_min, x_max, y_max} (4 words)
;   BC  = fill color (low byte)
;
; Output:
;   Rectangle filled in OFFSCREEN_BUFFER_1 (0x43C00)
;   SetChangeRect called with filled region
; =============================================================================
DrawBox:
	dec 2, xsp
	push xiz
	ld (xsp + 4), bc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawBox_DeferredPath
	cpdi16_24 197710, 0
	jr z, DrawBox_Return
	ld xwa, xiz
	ld bc, (xsp + 4)
	calr DrawBox_Impl
	jr DrawBox_Return

DrawBox_DeferredPath:
	ldw wa, 0xE
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfab2ba
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	lds bc, 4
	ldirw
	ld bc, (xsp + 4)
	ld (xwa + 12), bc
	calr DisplayCmd_DequeueAndExecute

DrawBox_Return:
	pop xiz
	inc 2, xsp
	ret

DrawBox_ParamBlock:
	.byte 0xb8, 0x04, 0x32, 0x98, 0x0c, 0x21, 0xd2, 0x4e
	.byte 0x04, 0x03, 0x3f, 0x00, 0x00, 0xb0, 0xf6, 0xea
	.byte 0x88, 0x1e, 0x01, 0x00, 0x0e

DrawBox_Impl:
	lda xsp, (xsp - 16)
	pushw iz
	ld (xsp + 12), bc
	ld (xsp + 14), xwa
	ld xwa, (xsp + 14)
	lda xbc, (xwa + 4)
	ld wa, (xwa)
	cp wa, (xbc)
	jrl gt, DrawBox_Impl_Return
	ld xwa, (xsp + 14)
	lda xhl, (xwa + 2)
	lda xde, (xwa + 6)
	ld wa, (xhl)
	cp wa, (xde)
	jrl gt, DrawBox_Impl_Return
	cps wa, 0
	jr ge, DrawBox_Impl_ClipYMin
	ldw (xhl), 0x0

DrawBox_Impl_ClipYMin:
	ld xwa, (xsp + 14)
	cpw (xwa), 0x0
	jr ge, DrawBox_Impl_ClipXMin
	ldw (xwa), 0x0

DrawBox_Impl_ClipXMin:
	cpw (xbc), 0x140
	jr lt, DrawBox_Impl_ClipXMax
	ldw (xbc), 0x13F

DrawBox_Impl_ClipXMax:
	cpw (xde), 0xF0
	jr lt, DrawBox_Impl_ClipYMax
	ldw (xde), 0xEF

DrawBox_Impl_ClipYMax:
	cpw (xsp + 12), 0xF7
	jrl z, DrawBox_Impl_Return
	ld hl, (xhl)
	ld wa, hl
	exts xwa
	ld xix, xwa
	sll xix, 2
	add xix, xwa
	sll xix, 6
	ld xwa, (xsp + 14)
	ld wa, (xwa)
	exts xwa
	add xwa, xix
	ld xiy, 0x43C00
	add xiy, xwa
	ld (xsp + 2), xiy
	ld bc, (xbc)
	ld xwa, (xsp + 14)
	sub bc, (xwa)
	inc 1, bc
	ld (xsp + 10), bc
	cpw (xsp + 12), 0xF5
	jr z, DrawBox_Impl_PatternSetup
	ld iz, hl
	cp hl, (xde)
	jr gt, DrawBox_Impl_SetChangeRect

DrawBox_Impl_FillRowLoop:
	pushm (xsp + 10)
	pushm (xsp + 14)
	ld xwa, (xsp + 6)
	push xwa
	call Memset
	inc 8, xsp
	ld xwa, (xsp + 2)
	st_dri3b W, 0xE1, 0x40, 0x01
	ld (xsp + 2), xwa
	inc 1, iz
	ld xwa, (xsp + 14)
	cp iz, (xwa + 6)
	jr le, DrawBox_Impl_FillRowLoop
	jr DrawBox_Impl_SetChangeRect

DrawBox_Impl_PatternSetup:
	ld32_24 xwa, 0x030452
	ld (xsp + 6), xwa
	ld xwa, (xsp + 14)
	ld wa, (xwa)
	exts xwa
	add xix, xwa
	add (xsp + 6), xix
	ld iz, hl
	cp hl, (xde)
	jr gt, DrawBox_Impl_SetChangeRect

DrawBox_Impl_PatternRowLoop:
	pushm (xsp + 10)
	ld xwa, (xsp + 8)
	push xwa
	ld xwa, (xsp + 8)
	push xwa
	call 0xFF0D99
	lda xsp, (xsp + 10)
	ld xwa, 0x140
	add (xsp + 6), xwa
	ld xwa, (xsp + 2)
	st_dri3b W, 0xE1, 0x40, 0x01
	ld (xsp + 2), xwa
	inc 1, iz
	ld xwa, (xsp + 14)
	cp iz, (xwa + 6)
	jr le, DrawBox_Impl_PatternRowLoop

DrawBox_Impl_SetChangeRect:
	ld xwa, (xsp + 14)
	calr SetChangeRect

DrawBox_Impl_Return:
	popw iz
	lda xsp, (xsp + 16)
	ret

; =============================================================================
; DrawFrame - Draw a rectangle outline (border only, no fill)
;
; Draws the border of a rectangle defined by a 4-word bounding box.
; Renders 4 lines (top, bottom, left, right edges) using the specified color.
;
; Input:
;   XWA = pointer to bounding box: {x_min, y_min, x_max, y_max} (4 words)
;   BC  = border color (low byte)
; =============================================================================
DrawFrame:
	dec 2, xsp
	push xiz
	ld (xsp + 4), bc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawFrame_DeferredPath
	cpdi16_24 197710, 0
	jr z, DrawFrame_Return
	ld xwa, xiz
	ld bc, (xsp + 4)
	calr DrawFrame_Impl
	jr DrawFrame_Return

DrawFrame_DeferredPath:
	ldw wa, 0xE
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfab425
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	lds bc, 4
	ldirw
	ld bc, (xsp + 4)
	ld (xwa + 12), bc
	calr DisplayCmd_DequeueAndExecute

DrawFrame_Return:
	pop xiz
	inc 2, xsp
	ret

DrawFrame_ParamBlock:
	.byte 0xb8, 0x04, 0x32, 0x98, 0x0c, 0x21, 0xd2, 0x4e
	.byte 0x04, 0x03, 0x3f, 0x00, 0x00, 0xb0, 0xf6, 0xea
	.byte 0x88, 0x1e, 0x01, 0x00, 0x0e

DrawFrame_Impl:
	lda xsp, (xsp - 44)
	push xiz
	ld (xsp + 42), bc
	ld (xsp + 44), xwa
	ld xwa, (xsp + 44)
	inc 2, xwa
	ld (xsp + 38), xwa
	cpw (xwa), 0x0
	jr ge, DrawFrame_Impl_ClipYMin
	ld xwa, (xsp + 38)
	ldw (xwa), 0x0

DrawFrame_Impl_ClipYMin:
	ld xwa, (xsp + 44)
	cpw (xwa), 0x0
	jr ge, DrawFrame_Impl_ClipXMin
	ldw (xwa), 0x0

DrawFrame_Impl_ClipXMin:
	ld xwa, (xsp + 44)
	inc 4, xwa
	ld (xsp + 30), xwa
	cpw (xwa), 0x140
	jr lt, DrawFrame_Impl_ClipXMax
	ld xwa, (xsp + 30)
	ldw (xwa), 0x13F

DrawFrame_Impl_ClipXMax:
	ld xwa, (xsp + 44)
	inc 6, xwa
	ld (xsp + 26), xwa
	cpw (xwa), 0xF0
	jr lt, DrawFrame_Impl_ClipYMax
	ld xwa, (xsp + 26)
	ldw (xwa), 0xEF

DrawFrame_Impl_ClipYMax:
	ld xwa, (xsp + 38)
	ld wa, (xwa)
	ld (xsp + 34), wa
	ld wa, (xsp + 34)
	exts xwa
	ld xbc, xwa
	sll xbc, 2
	add xbc, xwa
	sll xbc, 6
	cpw (xsp + 42), 0xF5
	jrl z, DrawFrame_Impl_PatternSetup
	ld wa, (xsp + 42)
	extz wa
	ld (xsp + 40), wa
	ld (xsp + 36), xbc
	ld xwa, (xsp + 26)
	ld wa, (xwa)
	cp wa, (xsp + 34)
	jr nz, DrawFrame_Impl_SolidTwoEdges
	ld xwa, (xsp + 30)
	ld bc, (xwa)
	ld xwa, (xsp + 44)
	sub bc, (xwa)
	inc 1, bc
	pushw bc
	pushm (xsp + 42)
	ld bc, (xwa)
	ld xwa, (xsp + 40)
	st_dri3b W, 0x07, 0xE0, 0xE4
	ld xbc, 0x43C00
	add xbc, xwa
	push xbc
	call Memset
	inc 8, xsp
	jrl DrawFrame_Impl_SetChangeRect

DrawFrame_Impl_SolidTwoEdges:
	ld xwa, (xsp + 30)
	ld bc, (xwa)
	ld xwa, (xsp + 44)
	sub bc, (xwa)
	inc 1, bc
	pushw bc
	pushm (xsp + 42)
	ld bc, (xwa)
	ld xwa, (xsp + 40)
	st_dri3b W, 0x07, 0xE0, 0xE4
	ld xbc, 0x43C00
	add xbc, xwa
	push xbc
	call Memset
	ld xde, (xsp + 52)
	ld bc, (xde + 4)
	sub bc, (xde)
	inc 1, bc
	pushw bc
	ld wa, (xsp + 52)
	extz wa
	pushw wa
	ld wa, (xde + 6)
	exts xwa
	ld xbc, xwa
	sll xbc, 2
	add xbc, xwa
	sll xbc, 6
	ld wa, (xde)
	exts xwa
	add xwa, xbc
	ld xbc, 0x43C00
	add xbc, xwa
	push xbc
	call Memset
	lda xsp, (xsp + 16)
	ldw (xsp + 28), 0xFFFF
	ld xbc, (xsp + 44)
	lda xwa, (xbc + 6)
	ld (xsp + 30), xwa
	ld wa, (xwa)
	ld (xsp + 40), wa
	ld wa, (xbc + 2)
	ld (xsp + 38), wa
	ld wa, (xsp + 40)
	cp wa, (xsp + 38)
	jr le, DrawFrame_Impl_SolidYStepPositive
	ldw (xsp + 28), 0x1

DrawFrame_Impl_SolidYStepPositive:
	ld wa, (xsp + 28)
	ld (xsp + 26), wa
	ld wa, (xsp + 38)
	add wa, (xsp + 28)
	cp wa, (xsp + 40)
	jrl z, DrawFrame_Impl_SetChangeRect
	ld xhl, (xsp + 44)
	lda xwa, (xhl + 4)
	ld (xsp + 34), xwa
	ld wa, (xsp + 28)
	add wa, (xsp + 38)
	exts xwa
	ld (xsp + 38), xwa
	ld xbc, xwa
	ld xwa, (xsp + 34)
	ld de, (xwa)
	cp de, (xhl)
	jr nz, DrawFrame_Impl_SolidTwoSideCheck
	ld xiy, (xsp + 44)
	lda_24 xix, 0x043c00
	ld hl, (xsp + 42)
	ld xwa, (xsp + 38)
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	jr DrawFrame_Impl_SolidOneSideCheck

DrawFrame_Impl_SolidOneSideLoop:
	ld wa, (xiy)
	exts xwa
	add xwa, xde
	ld xiz, xix
	add xiz, xwa
	ld (xiz), l
	inc 1, xbc
	add xde, 0x140

DrawFrame_Impl_SolidOneSideCheck:
	ld xwa, (xsp + 30)
	ld wa, (xwa)
	sub wa, (xsp + 28)
	exts xwa
	cp xbc, xwa
	jr ule, DrawFrame_Impl_SolidOneSideLoop
