DrawFrame_Impl_SolidTwoSideLoop:
	ld xhl, xbc
	sll xhl, 2
	add xhl, xbc
	sll xhl, 6
	ld xwa, (xsp + 44)
	ld wa, (xwa)
	st_dri3b B, 0x07, 0xEC, 0xE0
	lda_24 xwa, 0x043c00
	ld (xsp + 38), xwa
	add xwa, xde
	ld xix, xwa
	ld de, (xsp + 42)
	ld (xix), e
	ld xwa, (xsp + 34)
	ld wa, (xwa)
	exts xwa
	add xwa, xhl
	ld xhl, (xsp + 38)
	add xhl, xwa
	ld (xhl), e
	inc 1, xbc

DrawFrame_Impl_SolidTwoSideCheck:
	ld xwa, (xsp + 30)
	ld wa, (xwa)
	sub wa, (xsp + 26)
	exts xwa
	cp xbc, xwa
	jr ule, DrawFrame_Impl_SolidTwoSideLoop
	jrl DrawFrame_Impl_SetChangeRect

DrawFrame_Impl_PatternSetup:
	ld (xsp + 38), xbc
	ld xwa, (xsp + 26)
	ld wa, (xwa)
	cp wa, (xsp + 34)
	jr nz, DrawFrame_Impl_PatternTwoEdges
	ld xwa, (xsp + 30)
	ld bc, (xwa)
	ld xde, (xsp + 44)
	sub bc, (xde)
	inc 1, bc
	pushw bc
	ld wa, (xde)
	exts xwa
	ld xbc, (xsp + 40)
	add xbc, xwa
	addda32_24 xbc, 197714
	push xbc
	ld bc, (xde)
	ld xwa, (xsp + 44)
	st_dri3b W, 0x07, 0xE0, 0xE4
	ld xbc, 0x43C00
	add xbc, xwa
	push xbc
	call 0xFF0D99
	lda xsp, (xsp + 10)
	jrl DrawFrame_Impl_SetChangeRect

DrawFrame_Impl_PatternTwoEdges:
	ld xwa, (xsp + 30)
	ld bc, (xwa)
	ld xde, (xsp + 44)
	sub bc, (xde)
	inc 1, bc
	pushw bc
	ld wa, (xde)
	exts xwa
	ld xbc, (xsp + 40)
	add xbc, xwa
	addda32_24 xbc, 197714
	push xbc
	ld bc, (xde)
	ld xwa, (xsp + 44)
	st_dri3b W, 0x07, 0xE0, 0xE4
	ld xbc, 0x43C00
	add xbc, xwa
	push xbc
	call 0xFF0D99
	ld xhl, (xsp + 54)
	ld bc, (xhl + 4)
	sub bc, (xhl)
	inc 1, bc
	pushw bc
	ld de, (xhl)
	exts xde
	ld wa, (xhl + 6)
	exts xwa
	ld xbc, xwa
	sll xbc, 2
	add xbc, xwa
	sll xbc, 6
	ld xwa, xbc
	add xwa, xde
	addda32_24 xwa, 197714
	push xwa
	ld wa, (xhl)
	exts xwa
	add xwa, xbc
	ld xbc, 0x43C00
	add xbc, xwa
	push xbc
	call 0xFF0D99
	lda xsp, (xsp + 20)
	ldw (xsp + 4), 0xFFFF
	ld xde, (xsp + 44)
	lda xwa, (xde + 6)
	ld (xsp + 22), xwa
	ld bc, (xwa)
	ld de, (xde + 2)
	cp bc, de
	jr le, DrawFrame_Impl_PatternYStepPositive
	ldw (xsp + 4), 0x1

DrawFrame_Impl_PatternYStepPositive:
	ld wa, de
	add wa, (xsp + 4)
	cp wa, bc
	jrl z, DrawFrame_Impl_SetChangeRect
	ld xhl, (xsp + 44)
	lda xwa, (xhl + 4)
	ld (xsp + 26), xwa
	ld wa, (xsp + 4)
	add wa, de
	exts xwa
	ld (xsp + 30), xwa
	ld xbc, xwa
	lda_24 xwa, 0x043c00
	ld (xsp + 34), xwa
	ld (xsp + 38), xbc
	ld xwa, xbc
	sll xwa, 2
	add xwa, xbc
	ld (xsp + 38), xwa
	sll xwa, 6
	ld (xsp + 38), xwa
	ld xbc, (xsp + 30)
	ld xwa, (xsp + 26)
	ld de, (xwa)
	cp de, (xhl)
	jr nz, DrawFrame_Impl_PatternTwoSideSetup
	ld xwa, xhl
	ld (xsp + 30), xwa
	ld xhl, (xsp + 34)
	ld xix, (xsp + 44)
	ld xde, (xsp + 38)
	jr DrawFrame_Impl_PatternOneSideCheck

DrawFrame_Impl_PatternOneSideLoop:
	ld xwa, (xsp + 30)
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	ld xiz, xhl
	add xiz, xwa
	ld wa, (xix)
	exts xwa
	ld xiy, xde
	add xiy, xwa
	addda32_24 xiy, 197714
	ld a, (xiy)
	ld (xiz), a
	inc 1, xbc
	add xde, 0x140

DrawFrame_Impl_PatternOneSideCheck:
	ld xwa, (xsp + 22)
	ld wa, (xwa)
	sub wa, (xsp + 4)
	exts xwa
	cp xbc, xwa
	jr ule, DrawFrame_Impl_PatternOneSideLoop
	jr DrawFrame_Impl_SetChangeRect

DrawFrame_Impl_PatternTwoSideSetup:
	ld xwa, (xsp + 44)
	ld (xsp + 10), xwa
	ld xhl, (xsp + 34)
	ld (xsp + 6), xhl
	ld (xsp + 14), xwa
	ld xde, (xsp + 26)
	ld (xsp + 30), xde
	ld (xsp + 18), xhl
	ld (xsp + 34), xde
	ld xde, (xsp + 38)
	jr DrawFrame_Impl_PatternTwoSideCheck

DrawFrame_Impl_PatternTwoSideLoop:
	ld xwa, (xsp + 10)
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	ld xix, (xsp + 6)
	add xix, xwa
	ld xwa, (xsp + 14)
	ld wa, (xwa)
	exts xwa
	ld xhl, xde
	add xhl, xwa
	addda32_24 xhl, 197714
	ld a, (xhl)
	ld (xix), a
	ld xwa, (xsp + 30)
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	ld xix, (xsp + 18)
	add xix, xwa
	ld xwa, (xsp + 34)
	ld wa, (xwa)
	exts xwa
	ld xhl, xde
	add xhl, xwa
	addda32_24 xhl, 197714
	ld a, (xhl)
	ld (xix), a
	inc 1, xbc
