	pop xiz
	lda xsp, (xsp + 44)
	ret

; =============================================================================
; DrawFrameEx - Draw styled rectangle frame with XOR support
;
; Extended frame drawing that supports multiple rendering styles.
; Clips bounding box to screen (0,0)-(319,239) before drawing.
; Supports XOR mode for invertible selection rectangles.
;
; Input:
;   XWA = pointer to bounding box: {x_min, y_min, x_max, y_max} (4 words)
;   BC  = border color (low byte)
;   DE  = drawing mode (0x201=write, 0x205=XOR, etc.)
; =============================================================================
DrawFrameEx:
	lda xsp, (xsp - 14)
	push xiz
	ld (xsp + 14), de
	ld (xsp + 16), bc
	lda xde, (xwa + 2)
	cpw (xde), 0x0
	jr ge, DrawFrameEx_ClipYMin
	ldw (xde), 0x0

DrawFrameEx_ClipYMin:
	cpw (xwa), 0x0
	jr ge, DrawFrameEx_ClipXMin
	ldw (xwa), 0x0

DrawFrameEx_ClipXMin:
	lda xbc, (xwa + 4)
	ld (xsp + 8), xbc
	cpw (xbc), 0x140
	jr lt, DrawFrameEx_ClipXMax
	ld xbc, (xsp + 8)
	ldw (xbc), 0x13F

DrawFrameEx_ClipXMax:
	lda xbc, (xwa + 6)
	ld (xsp + 4), xbc
	cpw (xbc), 0xF0
	jr lt, DrawFrameEx_ClipYMax
	ld xbc, (xsp + 4)
	ldw (xbc), 0xEF

DrawFrameEx_ClipYMax:
	ld xbc, (xsp + 4)
	ld bc, (xbc)
	cp bc, (xde)
	jr nz, DrawFrameEx_MultiRowTopBottom
	ld hl, (xwa)
	ld xbc, (xsp + 8)
	cp hl, (xbc)
	jrl gt, DrawFrameEx_SetChangeRect

DrawFrameEx_SingleRowLoop:
	ld iy, (xsp + 14)
	ld ix, (xde)
	exts xix
	ld xbc, xix
	sll xbc, 2
	add xbc, xix
	sll xbc, 6
	st_dri3b A, 0x07, 0xE4, 0xEC
	cpw (xsp + 14), 0x205
	jr z, DrawFrameEx_SingleRowXorPixel
	cp iy, 0x201
	jrl nz, DrawFrameEx_Return
	ld xix, 0x43C00
	add xix, xbc
	ld bc, (xsp + 16)
	ld (xix), c

DrawFrameEx_SingleRowAdvance:
	inc 1, hl
	ld xbc, (xsp + 8)
	cp hl, (xbc)
	jr le, DrawFrameEx_SingleRowLoop
	jrl DrawFrameEx_SetChangeRect

DrawFrameEx_SingleRowXorPixel:
	ld xix, 0x43C00
	add xix, xbc
	ld bc, (xsp + 16)
	xor (xix), c
	jr DrawFrameEx_SingleRowAdvance

DrawFrameEx_MultiRowTopBottom:
	ld hl, (xwa)
	ld xbc, (xsp + 8)
	cp hl, (xbc)
	jr gt, DrawFrameEx_SidesSetup

DrawFrameEx_TopBottomLoop:
	ld iy, (xsp + 14)
	ld ix, (xde)
	exts xix
	ld xbc, xix
	sll xbc, 2
	add xbc, xix
	sll xbc, 6
	st_dri3b A, 0x07, 0xE4, 0xEC
	cpw (xsp + 14), 0x205
	jr z, DrawFrameEx_TopBottomXorPixel
	cp iy, 0x201
	jrl nz, DrawFrameEx_Return
	lda_24 xix, 0x043c00
	ld xiy, xix
	add xiy, xbc
	ld bc, (xsp + 16)
	ldfr_berp C, 0xEE
	ld (xiy), c
	ld xbc, (xsp + 4)
	ld bc, (xbc)
	exts xbc
	ld xiy, xbc
	sll xiy, 2
	add xiy, xbc
	sll xiy, 6
	st_dri3b A, 0x07, 0xF4, 0xEC
	add xix, xbc
	ldto_berp C, 0xEE
	ld (xix), c

DrawFrameEx_TopBottomAdvance:
	inc 1, hl
	ld xbc, (xsp + 8)
	cp hl, (xbc)
	jr le, DrawFrameEx_TopBottomLoop

DrawFrameEx_SidesSetup:
	ld xhl, 0xFFFFFFFF
	ld xbc, (xsp + 4)
	ld bc, (xbc)
	ld ix, (xde)
	cp bc, ix
	jr le, DrawFrameEx_SidesStepComputed
	lds32 xhl, 1

DrawFrameEx_SidesStepComputed:
	ld xiy, xhl
	ld de, bc
	exts xde
	ld bc, ix
	exts xbc
	add xbc, xhl
	cp xbc, xde
	jrl z, DrawFrameEx_SetChangeRect
	ld de, iy
	ld hl, de
	add hl, ix
	ld xbc, (xsp + 8)
	ld bc, (xbc)
	cp bc, (xwa)
	jrl nz, DrawFrameEx_TwoColSetup
	ld (xsp + 12), de
	jr DrawFrameEx_SingleColCheck

DrawFrameEx_TopBottomXorPixel:
	lda_24 xix, 0x043c00
	ld xiy, xix
	add xiy, xbc
	ld bc, (xsp + 16)
	ldfr_berp C, 0xEE
	xor (xiy), c
	ld xbc, (xsp + 4)
	ld bc, (xbc)
	exts xbc
	ld xiy, xbc
	sll xiy, 2
	add xiy, xbc
	sll xiy, 6
	st_dri3b A, 0x07, 0xF4, 0xEC
	add xix, xbc
	ldto_berp C, 0xEE
	xor (xix), c
	jr DrawFrameEx_TopBottomAdvance

DrawFrameEx_SingleColLoop:
	ld bc, (xsp + 14)
	lda_24 xde, 0x043c00
	cpw (xsp + 14), 0x205
	jr z, DrawFrameEx_SingleColXorPixel
	cp bc, 0x201
	jrl nz, DrawFrameEx_Return
	ld bc, hl
	exts xbc
	ld xix, xbc
	sll xix, 2
	add xix, xbc
	sll xix, 6
	ld bc, (xwa)
	exts xbc
	add xbc, xix
	add xde, xbc
	ld bc, (xsp + 16)
	ld (xde), c

DrawFrameEx_SingleColAdvance:
	inc 1, hl

DrawFrameEx_SingleColCheck:
	ld xbc, (xsp + 4)
	ld bc, (xbc)
	sub bc, (xsp + 12)
	cp hl, bc
	jr le, DrawFrameEx_SingleColLoop
	jr DrawFrameEx_SetChangeRect

DrawFrameEx_SingleColXorPixel:
	ld bc, hl
	exts xbc
	ld xix, xbc
	sll xix, 2
	add xix, xbc
	sll xix, 6
	ld bc, (xwa)
	exts xbc
	add xbc, xix
	add xde, xbc
	ld bc, (xsp + 16)
	xor (xde), c
	jr DrawFrameEx_SingleColAdvance

DrawFrameEx_TwoColSetup:
	ld (xsp + 12), de
	jr DrawFrameEx_TwoColCheck

DrawFrameEx_TwoColLoop:
	ld iz, (xsp + 14)
	ld iy, hl
	exts xiy
	ld de, (xsp + 16)
	ld xix, xiy
	sll xix, 2
	add xix, xiy
	sll xix, 6
	cpw (xsp + 14), 0x205
	jr z, DrawFrameEx_TwoColXorPixel
	cp iz, 0x201
	jr nz, DrawFrameEx_Return
	ld bc, (xwa)
	exts xbc
	add xbc, xix
	lda_24 xiy, 0x043c00
	ld xiz, xiy
	add xiz, xbc
	ld (xiz), e
	ld xbc, (xsp + 8)
	ld bc, (xbc)
	exts xbc
	add xbc, xix
	add xiy, xbc
	ld (xiy), e

DrawFrameEx_TwoColAdvance:
	inc 1, hl

DrawFrameEx_TwoColCheck:
	ld xbc, (xsp + 4)
	ld bc, (xbc)
	sub bc, (xsp + 12)
	cp hl, bc
	jr le, DrawFrameEx_TwoColLoop

DrawFrameEx_SetChangeRect:
	calr SetChangeRect
	jr DrawFrameEx_Return

DrawFrameEx_TwoColXorPixel:
	ld bc, (xwa)
	exts xbc
	add xbc, xix
	lda_24 xiy, 0x043c00
	ld xiz, xiy
	add xiz, xbc
	xor (xiz), e
	ld xbc, (xsp + 8)
	ld bc, (xbc)
	exts xbc
	add xbc, xix
	add xiy, xbc
	xor (xiy), e
	jr DrawFrameEx_TwoColAdvance

DrawFrameEx_Return:
	pop xiz
	lda xsp, (xsp + 14)
	ret

; =============================================================================
; MovePixels - Copy a rectangular pixel region within the offscreen buffer
;
; Copies a rectangular block of pixels from a source region to a destination
; region within OFFSCREEN_BUFFER_1 (0x43C00). Used for scrolling, sprite
; movement, and UI element repositioning.
;
; Input:
;   XWA = pointer to source rect: word[0]=src_x, word[2]=src_y,
;         word[4]=dest_x, word[6]=dest_y
;   XBC = pointer to size: word[0]=width, word[2]=height
;
; Copies pixel-by-pixel with nested row/column loops.
; Calls SetChangeRect on completion.
; =============================================================================
MovePixels:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xbc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, MovePixels_DeferredPath
	cpdi16_24 197710, 0
	jr z, MovePixels_Return
	ld xwa, xiz
	ld xbc, (xsp + 4)
	calr MovePixels_Impl
	jr MovePixels_Return

MovePixels_DeferredPath:
	ldw wa, 0x10
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfabaa0
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	lds bc, 4
	ldirw
	ld xbc, (xsp + 4)
	ld xiy, xbc
	lda xix, (xwa + 12)
	ldiw
	ldiw
	calr DisplayCmd_DequeueAndExecute

MovePixels_Return:
	pop xiz
	inc 4, xsp
	ret

MovePixels_ParamBlock:
	.byte 0xb8, 0x04, 0x32, 0xb8, 0x0c, 0x31, 0xd2, 0x4e
	.byte 0x04, 0x03, 0x3f, 0x00, 0x00, 0xb0, 0xf6, 0xea
	.byte 0x88, 0x1e, 0x01, 0x00, 0x0e

MovePixels_Impl:
	lda xsp, (xsp - 22)
	push xiz
	ld (xsp + 22), xbc
	ld bc, (xwa + 4)
	ld (xsp + 4), bc
	ld bc, (xwa)
	sub (xsp + 4), bc
	jrl lt, MovePixels_Impl_Return
	lda xbc, (xwa + 2)
	ld (xsp + 10), xbc
	ld bc, (xwa + 6)
	ld (xsp + 6), bc
	ld xbc, (xsp + 10)
	ld bc, (xbc)
	sub (xsp + 6), bc
	jrl lt, MovePixels_Impl_Return
	ldw (xsp + 8), 0x0
	cpw (xsp + 6), 0x0
	jr lt, MovePixels_Impl_SetChangeRect

MovePixels_Impl_RowLoop:
	lds hl, 0
	cpw (xsp + 4), 0x0
	jr lt, MovePixels_Impl_RowAdvance

MovePixels_Impl_ColLoop:
	lda xix, (xsp + 18)
	ld bc, (xwa)
	add bc, hl
	ld (xix), bc
	lda xde, (xix + 2)
	ld xbc, (xsp + 10)
	ld bc, (xbc)
	add bc, (xsp + 8)
	ld (xde), bc
	lda xiy, (xsp + 14)
	ld xbc, (xsp + 22)
	ld bc, (xbc)
	add bc, hl
	ld (xiy), bc
	ld xbc, (xsp + 22)
	ld bc, (xbc + 2)
	add bc, (xsp + 8)
	ld (xiy + 2), bc
	exts xbc
	ld xiz, xbc
	sll xiz, 2
	add xiz, xbc
	sll xiz, 6
	ld bc, (xiy)
	exts xbc
	add xbc, xiz
	lda_24 xiy, 0x043c00
	ld xiz, xiy
	add xiz, xbc
	ld bc, (xde)
	exts xbc
	ld xde, xbc
	sll xde, 2
	add xde, xbc
	sll xde, 6
	ld bc, (xix)
	exts xbc
	add xbc, xde
	add xiy, xbc
	ld c, (xiy)
	ld (xiz), c
	inc 1, hl
	cp hl, (xsp + 4)
	jr le, MovePixels_Impl_ColLoop

MovePixels_Impl_RowAdvance:
	incm 1, (xsp + 8)
	ld bc, (xsp + 8)
	cp bc, (xsp + 6)
	jr le, MovePixels_Impl_RowLoop

MovePixels_Impl_SetChangeRect:
	calr SetChangeRect

MovePixels_Impl_Return:
	pop xiz
	lda xsp, (xsp + 22)
	ret

; =============================================================================
; DrawWall - Fill entire screen / draw wallpaper
;
; Copies the full framebuffer (2 Ã— 38400 words = 2 half-screens) from a
; source address at 0x030452 to OFFSCREEN_BUFFER_1 (0x43C00), then marks
; the entire screen as changed (0,0)-(319,239).
;
; This is used for drawing full-screen backgrounds (wallpaper/splash).
; =============================================================================
DrawWall:
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawWall_DirectPath
	sti16_24 0x030450, 0x0001
	sti16_24 0x03044e, 0x0001
	jr DrawWall_DoCopy

DrawWall_DirectPath:
	sti16_24 0x030450, 0x0000
	cpdi16_24 197710, 0
	jr z, DrawWall_SetCopyFlag

DrawWall_WaitVblankBefore:
	lds wa, 1
	call 0xEF1F0F
	lds wa, 3
	call TaskSched_YieldToQueue
	cpdi16_24 197710, 0
	jr nz, DrawWall_WaitVblankBefore

DrawWall_SetCopyFlag:
	sti16_24 0x030450, 0x0001
	cpdi16_24 197710, 0
	jr nz, DrawWall_Deferred

DrawWall_WaitVblankAfter:
	lds wa, 1
	call 0xEF1F0F
	lds wa, 3
	call TaskSched_YieldToQueue
	cpdi16_24 197710, 0
	jr z, DrawWall_WaitVblankAfter

DrawWall_Deferred:
	lds wa, 4
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfabbe5
	ld (xwa), xbc
	jrl DisplayCmd_DequeueAndExecute
	jr __jrt_nop_FABBE7
__jrt_nop_FABBE7:

DrawWall_DoCopy:
	lda xsp, (xsp - 12)
	push xiz
	ld32_24 xiz, 0x030452
	lda_24 xwa, 0x043c00
	ld (xsp + 4), xwa
	pushw 0x9600
	push xiz
	push xwa
	call 0xFF0D99
	ld xwa, 0x9600
	add (xsp + 14), xwa
	add xiz, 0x9600
	pushw 0x9600
	push xiz
	ld xwa, (xsp + 20)
	push xwa
	call 0xFF0D99
	lda xsp, (xsp + 20)
	lda xwa, (xsp + 8)
	ldw (xwa + 2), 0x0
	ldw (xwa), 0x0
	ldw (xwa + 4), 0x13F
	ldw (xwa + 6), 0xEF
	calr SetChangeRect
	pop xiz
	lda xsp, (xsp + 12)
	ret

; =============================================================================
; DrawBitmap - Draw an indexed bitmap/sprite from the bitmap table
;
; Draws a bitmap from the ROM bitmap descriptor table at 0x913000.
; Each descriptor is 8 bytes: {word width, word height, long pixel_data_ptr}.
; Pixel data is stored as packed 16-bit entries (2 pixels per word).
; Color 0xF7 is treated as transparent (pixel skipped).
;
; Input:
;   XWA = pointer to position: word[0]=x, word[2]=y
;   XBC = bitmap index (used as: table[index * 8])
;
; Output:
;   Bitmap rendered to OFFSCREEN_BUFFER_1 (0x43C00)
;   SetChangeRect called with bitmap bounding box
;
; Returns immediately if bitmap index is 0xFFFFFFFF (no bitmap).
; Clips against screen bottom edge (y >= 240 â†’ skip row).
; =============================================================================
DrawBitmap:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xbc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawBitmap_DeferredPath
	cpdi16_24 197710, 0
	jr z, DrawBitmap_Return
	ld xwa, xiz
	ld xbc, (xsp + 4)
	calr DrawBitmap_Impl
	jr DrawBitmap_Return

DrawBitmap_DeferredPath:
	ldw wa, 0xC
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfabc83
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	ldiw
	ldiw
	ld xbc, (xsp + 4)
	ld (xwa + 8), xbc
	calr DisplayCmd_DequeueAndExecute

DrawBitmap_Return:
	pop xiz
	inc 4, xsp
	ret

DrawBitmap_ParamBlock:
	.byte 0xb8, 0x04, 0x32, 0xa8, 0x08, 0x21, 0xd2, 0x4e
	.byte 0x04, 0x03, 0x3f, 0x00, 0x00, 0xb0, 0xf6, 0xea
	.byte 0x88, 0x1e, 0x01, 0x00, 0x0e

DrawBitmap_Impl:
	lda xsp, (xsp - 26)
	push xiz
	ld xiz, xbc
	ld (xsp + 26), xwa
	cp xiz, 0xFFFFFFFF
	jrl z, DrawBitmap_Impl_Return
	ld xwa, (xsp + 26)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawBitmap_Impl_Return
	ld xhl, xiz
	sll xhl, 3
	add xhl, 0x913000
	ld xix, (xhl + 4)
	ldw (xsp + 4), 0x0
	jrl DrawBitmap_Impl_RowCheck

DrawBitmap_Impl_RowLoop:
	lda xbc, (xsp + 22)
	lda xwa, (xbc + 2)
	ld (xsp + 10), xwa
	ld xwa, (xsp + 26)
	ld wa, (xwa + 2)
	add wa, (xsp + 4)
	ld iy, wa
	ld xwa, (xsp + 10)
	ld (xwa), iy
	cp iy, 0xF0
	jrl ge, DrawBitmap_Impl_BuildDirtyRect
	ld wa, iy
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld xwa, (xsp + 26)
	ld wa, (xwa)
	exts xwa
	add xwa, xde
	lda_24 xiz, 0x043c00
	ld xde, xiz
	add xde, xwa
	ld (xsp + 6), xde
	lds iy, 0
	jr DrawBitmap_Impl_ColLoop

DrawBitmap_Impl_PixelPair:
	ld wa, (xix)
	srl wa, 8
	cp wa, 0xF7
	jr z, DrawBitmap_Impl_LoTransparent
	cp (xix), 0xF7
	jr z, DrawBitmap_Impl_HiTransparent
	ld xde, (xsp + 6)
	ld wa, (xix)
	ld (xde), wa
	jr DrawBitmap_Impl_PixelAdvance

DrawBitmap_Impl_HiTransparent:
	ld xwa, (xsp + 26)
	ld wa, (xwa)
	add wa, de
	inc 1, wa
	ld (xbc), wa
	ld xwa, (xsp + 10)
	ld wa, (xwa)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld wa, (xbc)
	exts xwa
	add xwa, xde
	ld xde, xiz
	add xde, xwa
	ld wa, (xix)
	srl wa, 8
	ld (xde), a
	jr DrawBitmap_Impl_PixelAdvance

DrawBitmap_Impl_LoTransparent:
	cp (xix), 0xF7
	jr z, DrawBitmap_Impl_PixelAdvance
	ld xwa, (xsp + 26)
	ld wa, (xwa)
	add wa, de
	ld (xbc), wa
	ld xwa, (xsp + 10)
	ld wa, (xwa)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld wa, (xbc)
	exts xwa
	add xwa, xde
	ld xde, xiz
	add xde, xwa
	ld a, (xix)
	ld (xde), a

DrawBitmap_Impl_PixelAdvance:
	inc 2, xix
	lds32 xwa, 2
	add (xsp + 6), xwa
	inc 1, iy

DrawBitmap_Impl_ColLoop:
	ld wa, (xhl)
	exts xwa
	divs wa, 0x2
	ld de, iy
	add de, de
	cp iy, wa
	jrl c, DrawBitmap_Impl_PixelPair
	ld wa, (xhl)
	exts xwa
	divs wa, 0x2
	ldto_werp WA, 0xE2
	cps wa, 0
	jr z, DrawBitmap_Impl_RowAdvance
	cp (xix), 0xF7
	jr z, DrawBitmap_Impl_OddPixelSkip
	ld xwa, (xsp + 26)
	ld wa, (xwa)
	add wa, de
	ld (xbc), wa
	ld xwa, (xsp + 10)
	ld wa, (xwa)
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld wa, (xbc)
	exts xwa
	add xwa, xde
	add xiz, xwa
	ld a, (xix)
	ld (xiz), a

DrawBitmap_Impl_OddPixelSkip:
	inc 2, xix

DrawBitmap_Impl_RowAdvance:
	incm 1, (xsp + 4)

DrawBitmap_Impl_RowCheck:
	lda xde, (xhl + 2)
	ld wa, (xde)
	cp (xsp + 4), wa
	jrl c, DrawBitmap_Impl_RowLoop

DrawBitmap_Impl_BuildDirtyRect:
	lda xwa, (xsp + 14)
	ld xiy, (xsp + 26)
	lda xix, (xiy + 2)
	ld bc, (xix)
	ld (xwa + 2), bc
	ld bc, (xiy)
	ld (xwa), bc
	ld hl, (xhl)
	add hl, (xiy)
	ld (xwa + 4), hl
	ld bc, (xde)
	add bc, (xix)
	ld (xwa + 6), bc
	calr SetChangeRect

DrawBitmap_Impl_Return:
	pop xiz
	lda xsp, (xsp + 26)
	ret

; =============================================================================
; DrawBitmapFast - Optimized bitmap drawing (no transparency check)
;
; Like DrawBitmap but skips the per-pixel 0xF7 transparency check.
; Faster for opaque bitmaps that don't require transparency.
;
; Input:
;   XWA = pointer to position: word[0]=x, word[2]=y
;   XBC = bitmap index (table at 0x913000, 8 bytes per entry)
; =============================================================================
DrawBitmapFast:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xbc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawBitmapFast_DeferredPath
	cpdi16_24 197710, 0
	jr z, DrawBitmapFast_Return
	ld xwa, xiz
	ld xbc, (xsp + 4)
	calr DrawBitmapFast_Impl
	jr DrawBitmapFast_Return

DrawBitmapFast_DeferredPath:
	ldw wa, 0xC
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfabe5a
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	ldiw
	ldiw
	ld xbc, (xsp + 4)
	ld (xwa + 8), xbc
	calr DisplayCmd_DequeueAndExecute

DrawBitmapFast_Return:
	pop xiz
	inc 4, xsp
	ret

DrawBitmapFast_ParamBlock:
	.byte 0xb8, 0x04, 0x32, 0xa8, 0x08, 0x21, 0xd2, 0x4e
	.byte 0x04, 0x03, 0x3f, 0x00, 0x00, 0xb0, 0xf6, 0xea
	.byte 0x88, 0x1e, 0x01, 0x00, 0x0e

DrawBitmapFast_Impl:
	lda xsp, (xsp - 24)
	push xiz
	ld xiz, xbc
	ld (xsp + 24), xwa
	cp xiz, 0xFFFFFFFF
	jrl z, DrawBitmapFast_Impl_Return
	ld xwa, (xsp + 24)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawBitmapFast_Impl_Return
	ld xhl, (xsp + 24)
	ld bc, (xhl + 2)
	ld wa, bc
	exts xwa
	ld xde, xwa
	sll xde, 2
	add xde, xwa
	sll xde, 6
	ld wa, (xhl)
	exts xwa
	add xwa, xde
	ld xde, 0x43C00
	add xde, xwa
	ld (xsp + 12), xde
	ld (xsp + 8), bc
	sll xiz, 3
	add xiz, 0x913000
	ld xwa, (xiz + 4)
	ld (xsp + 4), xwa
	ldw (xsp + 10), 0x0
	jr DrawBitmapFast_Impl_RowCheck

DrawBitmapFast_Impl_RowLoop:
	cpw (xsp + 8), 0xF0
	jr nc, DrawBitmapFast_Impl_BuildDirtyRect
	ld wa, (xiz)
	pushw wa
	ld xwa, (xsp + 6)
	push xwa
	ld xwa, (xsp + 18)
	push xwa
	call 0xFF0D99
	lda xsp, (xsp + 10)
	ld wa, (xiz)
	exts xwa
	divs wa, 0x2
	ldto_werp WA, 0xE2
	add wa, (xiz)
	exts xwa
	divs wa, 0x2
	exts xwa
	add xwa, xwa
	add (xsp + 4), xwa
	ld xwa, (xsp + 12)
	st_dri3b W, 0xE1, 0x40, 0x01
	ld (xsp + 12), xwa
	incm 1, (xsp + 8)
	incm 1, (xsp + 10)

DrawBitmapFast_Impl_RowCheck:
	lda xde, (xiz + 2)
	ld wa, (xde)
	cp (xsp + 10), wa
	jr c, DrawBitmapFast_Impl_RowLoop

DrawBitmapFast_Impl_BuildDirtyRect:
	lda xwa, (xsp + 16)
	ld xiy, (xsp + 24)
	lda xhl, (xiy + 2)
	ld bc, (xhl)
	ld (xwa + 2), bc
	ld bc, (xiy)
	ld (xwa), bc
	ld ix, (xiz)
	add ix, (xiy)
	ld (xwa + 4), ix
	ld bc, (xde)
	add bc, (xhl)
	ld (xwa + 6), bc
	calr SetChangeRect

DrawBitmapFast_Impl_Return:
	pop xiz
	lda xsp, (xsp + 24)
	ret

; =============================================================================
; DrawIcons - Draw icon sprite from the icon descriptor table
;
; Draws an icon from the ROM icon descriptor table at 0x938000.
; Same format as bitmap table (8 bytes/entry: width, height, data_ptr)
; but uses a separate base address for UI icons.
;
; Input:
;   XWA = pointer to position: word[0]=x, word[2]=y
;   XBC = icon index (used as: table[index * 8])
;
; Returns immediately if icon index is 0 (no icon).
; =============================================================================
DrawIcons:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xbc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawIcons_DeferredPath
	cpdi16_24 197710, 0
	jr z, DrawIcons_Return
	ld xwa, xiz
	ld xbc, (xsp + 4)
	calr DrawIcons_Impl
	jr DrawIcons_Return

DrawIcons_DeferredPath:
	ldw wa, 0xC
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfabf86
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	ldiw
	ldiw
	ld xbc, (xsp + 4)
	ld (xwa + 8), xbc
	calr DisplayCmd_DequeueAndExecute

DrawIcons_Return:
	pop xiz
	inc 4, xsp
	ret

DrawIcons_ParamBlock:
	.byte 0xb8, 0x04, 0x32, 0xa8, 0x08, 0x21, 0xd2, 0x4e
	.byte 0x04, 0x03, 0x3f, 0x00, 0x00, 0xb0, 0xf6, 0xea
	.byte 0x88, 0x1e, 0x01, 0x00, 0x0e

DrawIcons_Impl:
	lda xsp, (xsp - 36)
	push xiz
	ld (xsp + 32), xbc
	ld (xsp + 36), xwa
	ld xwa, (xsp + 32)	; ICON ID
	or xwa, xwa
	jrl z, DrawIcons_Impl_Return

	ld xwa, (xsp + 36)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawIcons_Impl_Return
	ld xwa, (xsp + 32)	; ICON ID
	ld (xsp + 4), xwa
	sll xwa, 3
	ld (xsp + 4), xwa	; 8 * ICON ID
	ld xwa, 0x938000	; <-- base address for icon data
				;    (this is at the end of the
				;     "table_data" ROM at IC1 and IC3)
	add (xsp + 4), xwa
	ld xwa, (xsp + 4)
	ld xwa, (xwa + 4)
	ld (xsp + 8), xwa
	lda xwa, (xsp + 30)
	ld (xsp + 16), xwa
	ld xde, (xsp + 36)
	lda xwa, (xde + 2)
	ld (xsp + 12), xwa
	ld xbc, (xsp + 16)
	ld wa, (xwa)
	ld (xbc), wa
	ld xwa, (xsp + 12)
	ld wa, (xwa)
	exts xwa
	ld xbc, xwa
	sll xbc, 2
	add xbc, xwa
	sll xbc, 6
	ld wa, (xde)
	exts xwa
	add xwa, xbc
	ld xhl, 0x43C00
	add xhl, xwa
	lds de, 0

DrawIcons_Impl_RowLoop:
	ld xwa, (xsp + 16)
	cpw (xwa), 0xF0
	jr ge, DrawIcons_Impl_BuildDirtyRect
	ld xiz, xhl
	lds iy, 0

DrawIcons_Impl_ColLoop:
	st_dpib D, 0xF9
	ld xwa, (xsp + 8)
	ld_spib C, 0xE0
	ld (xsp + 8), xwa
	ld a, c
	extz wa
	add wa, wa
	lda_24 xbc, 0xeaabf2
	ld_sriw3 WA, 0x07, 0xE4, 0xE0
	ld (xix), wa
	inc 1, iy
	cp iy, 0xC
	jr lt, DrawIcons_Impl_ColLoop
	ld xwa, (xsp + 16)
	incm 1, (xwa)
	st_dri3b C, 0xED, 0x40, 0x01
	inc 1, de
	cp de, 0x18
	jr lt, DrawIcons_Impl_RowLoop

DrawIcons_Impl_BuildDirtyRect:
	lda xwa, (xsp + 20)
	ld xhl, (xsp + 12)
	ld bc, (xhl)
	ld (xwa + 2), bc
	ld xiy, (xsp + 36)
	ld bc, (xiy)
	ld (xwa), bc
	ld xix, (xsp + 4)
	ld de, (xix)
	add de, (xiy)
	ld (xwa + 4), de
	ld de, (xix + 2)
	add de, (xhl)
	ld (xwa + 6), de
	calr SetChangeRect

DrawIcons_Impl_Return:
	pop xiz
	lda xsp, (xsp + 36)
	ret

DrawFrameSP:
	dec 4, xsp
	push xiz
	ld (xsp + 4), de
	ld (xsp + 6), bc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawFrameSP_DeferredPath
	cpdi16_24 197710, 0
	jr z, DrawFrameSP_Return
	ld xwa, xiz
	ld bc, (xsp + 6)
	ld de, (xsp + 4)
	calr DrawFrameSP_Impl
	jr DrawFrameSP_Return

DrawFrameSP_DeferredPath:
	ldw wa, 0xC
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfac0cf
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	ldiw
	ldiw
	ld bc, (xsp + 6)
	ld (xwa + 8), bc
	ld bc, (xsp + 4)
	ld (xwa + 10), bc
	calr DisplayCmd_DequeueAndExecute

DrawFrameSP_Return:
	pop xiz
	inc 4, xsp
	ret

DrawFrameSP_ParamBlock:
	.byte 0xb8, 0x04, 0x33, 0x98, 0x08, 0x21, 0x98, 0x0a
	.byte 0x22, 0xd2, 0x4e, 0x04, 0x03, 0x3f, 0x00, 0x00
	.byte 0xb0, 0xf6, 0xeb, 0x88, 0x1e, 0x01, 0x00, 0x0e

DrawFrameSP_Impl:
	lda xsp, (xsp - 34)
	ld (xsp + 26), de
	ld (xsp + 28), bc
	ld (xsp + 30), xwa
	ld xwa, (xsp + 30)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawFrameSP_Impl_Return
	ld bc, (xsp + 28)
	extz xbc
	sll xbc, 3
	add xbc, 0x934000
	ld xwa, (xbc + 4)
	ld (xsp), xwa
	ldw (xsp + 4), 0x0
	lda xwa, (xbc + 2)
	ld (xsp + 6), xwa
	cpw (xwa), 0x0
	jrl le, DrawFrameSP_Impl_BuildDirtyRect

DrawFrameSP_Impl_RowLoop:
	lda xde, (xsp + 22)
	lda xwa, (xde + 2)
	ld (xsp + 10), xwa
	ld xwa, (xsp + 30)
	ld hl, (xwa + 2)
	add hl, (xsp + 4)
	ld xwa, (xsp + 10)
	ld (xwa), hl
	cp hl, 0xF0
	jrl ge, DrawFrameSP_Impl_BuildDirtyRect
	lds hl, 0
	cpw (xbc), 0x0
	jr le, DrawFrameSP_Impl_OddWidthPad

DrawFrameSP_Impl_ColLoop:
	ld xwa, (xsp + 30)
	ld wa, (xwa)
	add wa, hl
	ld (xde), wa
	ld xwa, (xsp)
	ld a, (xwa)
	ldfr_berp A, 0xEE
	cp_erpb 0xEE, 0xF7
	jr z, DrawFrameSP_Impl_PixelAdvance
	lda_24 xiy, 0x043c00
	ld xwa, (xsp + 10)
	ld wa, (xwa)
	exts xwa
	ld xix, xwa
	sll xix, 2
	add xix, xwa
	sll xix, 6
	cp_erpb 0xEE, 0xF6
	jr nz, DrawFrameSP_Impl_DrawNormal
	ld wa, (xde)
	exts xwa
	add xwa, xix
	add xiy, xwa
	ld wa, (xsp + 26)
	ld (xiy), a
	jr DrawFrameSP_Impl_PixelAdvance

DrawFrameSP_Impl_DrawNormal:
	ld wa, (xde)
	exts xwa
	add xwa, xix
	add xiy, xwa
	ld xwa, (xsp)
	ld a, (xwa)
	ld (xiy), a

DrawFrameSP_Impl_PixelAdvance:
	lds32 xwa, 1
	add (xsp), xwa
	inc 1, hl
	cp hl, (xbc)
	jr lt, DrawFrameSP_Impl_ColLoop

DrawFrameSP_Impl_OddWidthPad:
	ld wa, (xbc)
	exts xwa
	divs wa, 0x2
	add wa, wa
	cp wa, (xbc)
	jr z, DrawFrameSP_Impl_RowAdvance
	lds32 xwa, 1
	add (xsp), xwa

DrawFrameSP_Impl_RowAdvance:
	incm 1, (xsp + 4)
	ld xwa, (xsp + 6)
	ld de, (xsp + 4)
	cp de, (xwa)
	jrl lt, DrawFrameSP_Impl_RowLoop

DrawFrameSP_Impl_BuildDirtyRect:
	lda xwa, (xsp + 14)
	ld xix, (xsp + 30)
	lda xhl, (xix + 2)
	ld de, (xhl)
	ld (xwa + 2), de
	ld de, (xix)
	ld (xwa), de
	ld de, (xbc)
	add de, (xix)
	ld (xwa + 4), de
	ld xbc, (xsp + 6)
	ld bc, (xbc)
	add bc, (xhl)
	ld (xwa + 6), bc
	calr SetChangeRect

DrawFrameSP_Impl_Return:
	lda xsp, (xsp + 34)
	ret

; =============================================================================
; DrawBitmapSP - Draw bitmap with special positioning/effects
;
; Like DrawBitmap but with additional parameters for sprite-like rendering
; with per-pixel color mapping and separate foreground/background handling.
;
; Input:
;   XWA = pointer to position: word[0]=x, word[2]=y
;   XBC = bitmap index
;   Stack: additional rendering parameters
; =============================================================================
DrawBitmapSP:
	dec 6, xsp
	push xiz
	ld (xsp + 4), de
	ld (xsp + 6), xbc
	ld xiz, xwa
	calr IS_XSP_INSIDE_4K_REGION_AT_1C032
	cps hl, 0
	jr z, DrawBitmapSP_DeferredPath
	cpdi16_24 197710, 0
	jr z, DrawBitmapSP_Return
	pushm (xsp + 14)
	ld xwa, xiz
	ld xbc, (xsp + 8)
	ld de, (xsp + 6)
	calr DrawBitmapSP_Impl
	jr DrawBitmapSP_Return

DrawBitmapSP_DeferredPath:
	ldw wa, 0x10
	calr DrawQueue_Alloc
	ld xwa, xhl
	lda_24 xbc, 0xfac24a
	ld (xwa), xbc
	ld xiy, xiz
	lda xix, (xwa + 4)
	ldiw
	ldiw
	ld xbc, (xsp + 6)
	ld (xwa + 8), xbc
	ld bc, (xsp + 4)
	ld (xwa + 12), bc
	ld bc, (xsp + 14)
	ld (xwa + 14), bc
	calr DisplayCmd_DequeueAndExecute

DrawBitmapSP_Return:
	pop xiz
	inc 6, xsp
	retd 0x2
	lda xbc, (xwa + 4)
	ld xhl, (xwa + 8)
	ld de, (xwa + 12)
	ld wa, (xwa + 14)
	cpdi16_24 197710, 0
	ret z
	pushw wa
	ld xwa, xbc
	ld xbc, xhl
	calr DrawBitmapSP_Impl
	ret

DrawBitmapSP_Impl:
	lda xsp, (xsp - 26)
	push xiz
	ld (xsp + 20), de
	ld (xsp + 22), xbc
	ld (xsp + 26), xwa
	ld xwa, (xsp + 26)
	calr IsPointOnScreen
	cps hl, 0
	jrl z, DrawBitmapSP_Impl_Return
	ldw (xsp + 4), 0x0
	ld wa, (xsp + 34)
	ld (xsp + 6), wa
	cpw (xsp + 6), 0x0
	jrl ule, DrawBitmapSP_Impl_BuildDirtyRect

DrawBitmapSP_Impl_RowLoop:
	lda xde, (xsp + 16)
	lda xbc, (xde + 2)
	ld xix, (xsp + 26)
	ld hl, (xix + 2)
	add hl, (xsp + 4)
	ld wa, hl
	ld (xbc), hl
	cp hl, 0xF0
	jrl ge, DrawBitmapSP_Impl_BuildDirtyRect
	exts xwa
	ld xhl, xwa
	sll xhl, 2
	add xhl, xwa
	sll xhl, 6
	ld wa, (xix)
	exts xwa
	add xwa, xhl
	lda_24 xhl, 0x043c00
	ld xiy, xhl
	add xiy, xwa
	lds ix, 0
	jrl DrawBitmapSP_Impl_ColLoop

DrawBitmapSP_Impl_PixelPair:
	ld xwa, (xsp + 22)
	ld wa, (xwa)
	srl wa, 8
	cp wa, 0xF7
