	lda_24 xix, 0x03c8e4
	add xwa, xix
	ld w, (xwa)
	res 1, w
	ld a, (xbc)
	and a, 0x2
	or a, w
	ld (xbc), a
	lda xbc, (xde + 6)
	ld xwa, xbc
	sub xwa, xhl
	add xwa, xix
	ld a, (xwa)
	ld (xbc), a

BitMapOut_DetectChanges_CheckMode:
