	extz xde
	add xde, (xsp + 8)
	ldada xwa, 63904
	ld bc, iz
	extz xbc
	add xbc, xwa
	ld a, (xbc)
	ld (xde), a
	ld wa, iz
	extz xwa
	ld xde, 0x3C8E4
	add xde, xwa
	ld a, (xde)
	xor a, (xbc)
	ld c, a
	ld wa, hl
	inc 1, hl
	extz xwa
	add xwa, (xsp + 8)
	ld (xwa), c

BitMapOut_DeltaEncode_NextByte:
