PmBankScreenProc:
	st_dri3b L, 0xFD, 0xE8, 0xFE
	push xiz
	st_dri3l XDE, 0xFD, 0x14, 0x01
	ld xiz, xbc
	st_dri3l XWA, 0xFD, 0x18, 0x01
	cp xiz, 0x1C00007
	jrl z, PmBank_OK
	cp xiz, 0x1C20002
	jrl z, PmBank_BankChanged
