	jrl z, PmBank_Confirm
	cp xiz, 0x1C0000E
	jrl z, PmBank_Select
	cp xiz, 0x1C0000D
	jr z, PmBank_Paint
	cp xiz, 0x1E2000E
	jr z, PmBank_EnumNotify
	cp xiz, 0x1C0000B
	jr z, PmBank_Show
	cp xiz, 0x1C00001
	jrl nz, PmBank_Default
	ld_sril XWA, (xsp + 0x0118)
	ld xbc, xiz
	ld_sril XDE, (xsp + 0x0114)
	jr PmBank_ForwardToHandler

