	stda8 37093, w
	ldb c, 0xB1
	ld b, a
	ldw de, 0x4000
	call MIDI_DispatchCC_Guarded
	ld wa, (xsp)
	stda8 37093, w
	ldb c, 0xB2
	ld b, a
