; =============================================================================
; SoundParam_NotifyChange -- Notify UI of sound parameter change
; =============================================================================
; Hashes parameter ID and triggers UI refresh for affected widgets.
; Called after preset loads: 0x4002 for reverb, 0x4006 for EQ.
; Args: xwa = parameter ID
SoundParam_NotifyChange:
	lda xsp, (xsp - 10)
	push xiz
	ld (xsp + 10), de
	ld (xsp + 12), bc
	ldw (xsp + 4), 0x0
	ld xiz, xwa
	lds32 xwa, 0
	ld (xsp + 6), xwa
	ld xhl, xiz
	and xhl, 0xFF
	ld xwa, xhl
	sll xwa, 9
	add xwa, xhl
	ld xhl, xiz
	srl xhl, 8
	and xhl, 0xFF
	add xhl, xwa
	ld xwa, xhl
	sll xwa, 9
	add xwa, xhl
	ld xhl, xiz
	srl xhl, 0
	and xhl, 0x1F
	add xhl, xwa
	ld xwa, xhl
	ld xbc, 0x7FF
	call DivMod32
	ld ix, hl
	jr SndParam_ProbeEntry

SndParam_ProbeCheckMatch:
	lds bc, 0
	cp xiz, xde
	jr z, SndParam_ProbeMatchFound
	ldw bc, 0xFFFF
	jr SndParam_ProbeAdvance

SndParam_ProbeMatchFound:
	cp bc, 0xFFFF
	jr z, SndParam_ProbeAdvance
	ld xwa, (xwa + 4)
	ld (xsp + 6), xwa

SndParam_ProbeAdvance:
	inc 1, hl
	cp hl, 0x7FF
	jr ugt, SndParam_DispatchCallback
	ld wa, ix
	inc 3, wa
	extz xwa
	div wa, 0x7FF
	ldto_werp IX, 0xE2

SndParam_ProbeEntry:
	ld bc, ix
	extz xbc
	sll xbc, 3
	ld xwa, 0x34100
	add xwa, xbc
	ld xde, (xwa)
	cp xde, 0xFFFFFF
	jr nz, SndParam_ProbeCheckMatch

SndParam_DispatchCallback:
	ld xwa, (xsp + 6)
	or xwa, xwa
	jr z, SndParam_NotFound
	cpw (xsp + 10), 0x5
	jr z, SndParam_DispatchTypeDE5
	ld c, (xwa + 13)
	cp c, 0x9
	jr nc, SndParam_NotFound
	extz bc
	sla bc, 2
	lda_24 xde, 0xee10ec
	st_dri3b C, 0x07, 0xE8, 0xE4
	ld bc, (xsp + 12)
	ld de, (xsp + 10)
	ld xhl, (xhl)
	call (xhl)
	ld xbc, xhl
	cpw (xbc), 0xFFFF
	jr z, SndParam_NotFound
	ld wa, (xbc + 2)
	cps wa, 1
	jr z, SndParam_CallbackType1
	cps wa, 0
	jr nz, SndParam_Epilogue
	ld wa, (xsp + 10)
	calr SndParam_WidgetNotifyType0
	jr SndParam_Epilogue

SndParam_CallbackType1:
	ld wa, (xsp + 10)
	calr SndParam_WidgetNotifyType1
	jr SndParam_Epilogue

SndParam_NotFound:
	ldw (xsp + 4), 0xFFFF

SndParam_Epilogue:
	ld hl, (xsp + 4)
	pop xiz
	lda xsp, (xsp + 10)
	ret

SndParam_DispatchTypeDE5:
	ld c, (xwa + 16)
	cps c, 6
	jr nc, SndParam_Epilogue
	extz bc
	sla bc, 2
	lda_24 xde, 0xee1148
	st_dri3b B, 0x07, 0xE8, 0xE4
	ld bc, (xsp + 12)
	ld xhl, (xde)
	call (xhl)
	ld (xsp + 4), hl
	jr SndParam_Epilogue

SndParam_NotifyAndReturn:
	pushw iz
	ld iz, de
	calr SndParam_EncodeAddress
	ld xwa, xhl
	ld bc, iz
	ld de, (xsp + 6)
	calr SoundParam_NotifyChange
	popw iz
	retd 0x2

SndParam_LookupByKey:
	lda xsp, (xsp - 10)
	push xiz
	ld (xsp + 10), de
	ld (xsp + 12), bc
	ldw (xsp + 4), 0x0
	ld xiz, xwa
	lds32 xwa, 0
	ld (xsp + 6), xwa
	ld xhl, xiz
	and xhl, 0xFF
	ld xwa, xhl
	sll xwa, 9
	add xwa, xhl
	ld xhl, xiz
	srl xhl, 8
	and xhl, 0xFF
	add xhl, xwa
	ld xwa, xhl
	sll xwa, 9
	add xwa, xhl
	ld xhl, xiz
	srl xhl, 0
	and xhl, 0x1F
	add xhl, xwa
	ld xwa, xhl
	ld xbc, 0x7FF
	call DivMod32
	ld ix, hl
	jr SndParam_Lkp2_ProbeEntry

SndParam_Lkp2_ProbeCheck:
	lds bc, 0
	cp xiz, xde
	jr z, SndParam_Lkp2_MatchFound
