	lda xsp, (xsp - 16)
	push xiz
	ld (xsp + 18), a
	pushw 0x800
	call Malloc
	inc 2, xsp
	ld (xsp + 6), xhl
	ld xwa, (xsp + 6)
	or xwa, xwa
	jr nz, DataBuf_AllocAndLoadFormatted_AllocOk
	ldw hl, 0xFF38
	jrl DataBuf_AllocAndLoadFormatted_Return

DataBuf_AllocAndLoadFormatted_AllocOk:
	pushw 0x800
	ld c, (xsp + 20)
	extz bc
	sla bc, 11
	lda_24 xwa, 0x0ab000
	st_dri3b W, 0x07, 0xE0, 0xE4
	push xwa
	ld xwa, (xsp + 12)
	push xwa
	call 0xFF0D99
