	ld xwa, (xsp + 6)
	st_dri3b W, 0xE1, 0xE0, 0x02
	ld (xsp + 10), xwa
	ld a, (xsp + 18)
	extz wa
	inc 1, wa
	calr DataBuf_InitSlotFromPreset
	ld c, (xsp + 18)
	extz bc
	sla bc, 11
	lda_24 xwa, 0x0ab000
	st_dri3b W, 0x07, 0xE0, 0xE4
	ld (xsp + 14), xwa
	ld xwa, 0x2E0
	add (xsp + 14), xwa
	ldw (xsp + 4), 0x0

DataBuf_TransferVoiceParams_Loop:
	ld wa, (xsp + 4)
	extz xwa
