DataBuf_CopyVoiceBlock24:
	ld xde, xwa
	ld a, (xde + 2)
	ld (xbc + 2), a
	ld a, (xde + 3)
	and a, 0x7F
	andmi8 (xbc + 3), 0x80
	or (xbc + 3), a
	ld a, (xde + 4)
	and a, 0x7F
	andmi8 (xbc + 4), 0x80
	or (xbc + 4), a
	lda xix, (xbc + 5)
	lda xhl, (xde + 5)
	ldcfm 7, (xhl)
