; --- MIDI_BuildControlPacket: Construct a 4-byte MIDI control packet ---
; Two entry points building MIDI packets from a parameter structure (XIZ):
; 1) Full packet: reads MIDI map value from table at 0xBCCC (via 0xFD6EB6),
;    adjusts by subtracting 0x20, ORs with (xiz+6) for status byte,
;    copies controller number from *(xiz+7), computes data byte via
;    lookup (0xFD822D), copies channel from (xiz+8).
; 2) Simple packet: same status byte construction but data byte 2 = 0.
; Output: 4-byte packet pointer + source struct pointer stored to (XWA).
MidiPkt_BuildControl:
	lda	xsp, (xsp-12)
	push	xiz
	ld	xiz, xwa
	ldda32	xwa, 48300
	ldw	bc, 10
	call	16604854
	sub	l, 32
	ld	c, l
	ld	l, (xiz+6)
	or	l, c
	lda	xbc, (xsp+12)
	ld	(xbc), l
	lda	xde, (xiz+7)
	ld	a, (xde)
	ld	(xbc+1), a
	extz	hl
	ld	c, (xde)
	ld	wa, hl
	call	16609965
	lda	xbc, (xsp+12)
	ld	(xbc+2), l
	ld	a, (xiz+8)
	ld	(xbc+3), a
	lda	xwa, (xsp+4)
	ld	(xwa), xbc
	ld	(xwa+4), xiz
	calr	2277
	pop	xiz
	lda	xsp, (xsp+12)
	ret
	lda	xsp, (xsp-12)
	push	xiz
	ld	xiz, xwa
	ldda32	xwa, 48300
	ldw	bc, 10
	call	16604854
	sub	l, 32
	ld	a, (xiz+6)
	or	a, l
	lda	xbc, (xsp+12)
	ld	(xbc), a
	ld	a, (xiz+7)
	ld	(xbc+1), a
	ld	(xbc+2), 0
	ld	a, (xiz+8)
	ld	(xbc+3), a
	lda	xwa, (xsp+4)
	ld	(xwa), xbc
	ld	(xwa+4), xiz
	calr	1512
	pop	xiz
	lda	xsp, (xsp+12)
	ret
	lda	xsp, (xsp-16)
	push	xiz
