; ============================================================================
; SndPart_SetParam - Set a sound part parameter by code
; ============================================================================
; Input:  WA = part number, DE = new value, BC = parameter code
; Output: None
; Dispatches on ~20 parameter codes to update part tables or send via MIDI.
; ============================================================================
SndPart_SetParam:
	dec 2, xsp
	pushw iz
	ld iz, de
	ld (xsp + 2), wa
	cp bc, 0x78
	jrl z, LABEL_FEB2B0
	cp bc, 0x1B2
	jrl z, LABEL_FEB2A6
	cp bc, 0x603
	jrl z, LABEL_FEB28C
	cp bc, 0x602
	jrl z, LABEL_FEB272
	cp bc, 0x1B0
	jrl z, LABEL_FEB268
	cp bc, 0x82
	jrl z, LABEL_FEB259
	cp bc, 0x81
	jrl z, LABEL_FEB24A
	cp bc, 0x80
	jrl z, LABEL_FEB23B
	cp bc, 0x5E
	jrl z, LABEL_FEB229
	cp bc, 0x5D
	jrl z, LABEL_FEB219
	cp bc, 0x5B
	jrl z, LABEL_FEB209
	cp bc, 0x600
	jrl z, LABEL_FEB1F9
	cp bc, 0x40
	jrl z, LABEL_FEB1D9
	cp bc, 0xB
	jr z, LABEL_FEB1C9
	cp bc, 0xA
	jr z, LABEL_FEB1B9
	cps bc, 7
	jr z, LABEL_FEB19A
	cps bc, 1
	jr z, LABEL_FEB18B
	cp bc, 0x20
	jr z, LABEL_FEB179
	cps bc, 0
	jrl nz, LABEL_FEB2BB
	ld wa, (xsp + 2)
	add wa, wa
	ldada xbc, 53200
	extz xwa
	add xwa, xbc
	ld (xwa), iz
	jrl LABEL_FEB2BB

LABEL_FEB179:
	ld wa, (xsp + 2)
	add wa, wa
	ldada xbc, 53264
	extz xwa
	add xwa, xbc
	ld (xwa), iz
	jrl LABEL_FEB2BB

LABEL_FEB18B:
	ld bc, iz
	ld wa, (xsp + 2)
	ld de, bc
	lds bc, 1
	calr MIDI_SendControlChange
	jrl LABEL_FEB2BB

