; ============================================================================
; MIDI_SendControlChange - Send a MIDI Control Change message
; ============================================================================
; Input:  A = MIDI channel, C = controller number, E = value
; Output: None (sends via SubCPU comm)
; Builds [4, 0xB0, chan, ctrl, val] packet, transmits via MIDI_SendCmdPacket.
; ============================================================================
MIDI_SendControlChange:
	dec 6, xsp
	ld (xsp + 256), 0x4
	ld (xsp + 1), 0xB0
	ld (xsp + 2), a
	ld (xsp + 3), c
	ld (xsp + 4), e
	lda xwa, (xsp)
	call MIDI_SendCmdPacket
	call LABEL_FEBF79
	inc 6, xsp
	ret

MIDI_SendPitchBend:
	dec 6, xsp
	ld (xsp + 256), 0x4
	ld (xsp + 1), 0xE0
	ld (xsp + 2), a
	ld a, c
	res 7, a
	ld (xsp + 3), a
	and bc, 0x3FFF
	srl bc, 7
	ld a, c
	ld (xsp + 4), a
	lda xwa, (xsp)
	call MIDI_SendCmdPacket
	call LABEL_FEBF79
	inc 6, xsp
	ret

MIDI_SendChannelPressure:
	dec 6, xsp
	ld (xsp + 256), 0x4
	ld (xsp + 1), 0xD0
	ld (xsp + 2), a
	ld (xsp + 3), 0x0
	ld (xsp + 4), c
	lda xwa, (xsp)
	call MIDI_SendCmdPacket
	call LABEL_FEBF79
	inc 6, xsp
	ret

