	lda xsp, (xsp - 12)
	pushw iz
	ld (xsp + 12), wa
	ld iz, (xsp + 18)
	cp iz, 0xFFFF
	jr nz, LABEL_FEBB9A
	lds iz, 0
	jr LABEL_FEBBA5

LABEL_FEBB9A:
	lds wa, 0
	cps iz, 0
	jr z, LABEL_FEBBA3
	ldw wa, 0x7F

LABEL_FEBBA3:
	ld iz, wa

LABEL_FEBBA5:
	ld (xsp + 10), c
	ld (xsp + 8), e
	lda xwa, (xsp + 10)
	ld xde, xwa
	lda xwa, (xsp + 8)
	ld xbc, xwa
	ld xwa, xde
	call SndParam_ApplyMaskClamp
	ld (xsp + 2), 0x5
	ld (xsp + 3), 0xC0
	ld wa, (xsp + 12)
	ld (xsp + 4), a
	ld a, (xsp + 10)
	ld (xsp + 5), a
	ld a, (xsp + 8)
	ld (xsp + 6), a
	ldto_berp A, 0xF8
