	lds hl, 0
	jr LABEL_FEBF60

LABEL_FEBF4C:
	ldada xde, 53392
	ld bc, hl
	inc 1, bc
	ld_srib3 C, 0x07, 0xE0, 0xE4
	lda_dri3 XHL, 0x07, 0xE8, 0xEC
	inc 1, hl

LABEL_FEBF60:
	ld c, (xwa)
	extz bc
	cp hl, bc
	jr lt, LABEL_FEBF4C
	ld a, (xwa)
	extz wa
	ld xde, 0xD090
	ld bc, wa
	lds wa, 0
	jp sendCOMM

LABEL_FEBF79:
	ret

