StrSearch_Init:
	ld xbc, (xsp + 4)
	lds hl, 0
	jr StrSearch_CheckHaystackEnd

StrSearch_LoadNeedle:
	ld xde, (xsp + 8)
	jr StrSearch_CheckNeedleEnd

StrSearch_CompareChar:
	ld a, (xde)
	cp a, (xbc)
	ret z
	inc 1, xde

StrSearch_CheckNeedleEnd:
	cp (xde), 0x0
	jr nz, StrSearch_CompareChar
	inc 1, xbc
	inc 1, hl

StrSearch_CheckHaystackEnd:
	cp (xbc), 0x0
	jr nz, StrSearch_LoadNeedle
	ret

ParseInt16:
	ld xhl, (xsp + 4)
	lds iy, 0
	lds ix, 0
	lda_24 xbc, 0xeed778
	jr ParseInt16_CheckWhitespace

ParseInt16_SkipWhitespace:
	inc 1, xhl

ParseInt16_CheckWhitespace:
	ld a, (xhl)
	extz wa
	bit_dri 3, 0x07, 0xE4, 0xE0
	jr nz, ParseInt16_SkipWhitespace
	cp (xhl), 0x2D
	jr nz, ParseInt16_CheckMinus
	lds ix, 1
	jr ParseInt16_SkipSign

ParseInt16_CheckMinus:
	cp (xhl), 0x2B
	jr nz, ParseInt16_DigitLoop

ParseInt16_SkipSign:
	inc 1, xhl

ParseInt16_DigitLoop:
	ld_spib E, 0xEC
	exts de
	ld a, e
	extz wa
	bit_dri 2, 0x07, 0xE4, 0xE0
	jr z, ParseInt16_ApplySign
	sub de, 0x30
	muls iy, 0xA
	add iy, de
	jr ParseInt16_DigitLoop

ParseInt16_ApplySign:
	cps ix, 0
	jr z, ParseInt16_Positive
	ld wa, iy
	neg wa
	ld hl, wa
	jr ParseInt16_Return

ParseInt16_Positive:
	ld hl, iy

ParseInt16_Return:
	ret

ParseInt32:
	ld xhl, (xsp + 4)
	lds32 xiy, 0
	lds ix, 0
	lda_24 xbc, 0xeed778
	jr ParseInt32_CheckWhitespace

ParseInt32_SkipWhitespace:
	inc 1, xhl

ParseInt32_CheckWhitespace:
	ld a, (xhl)
	extz wa
	bit_dri 3, 0x07, 0xE4, 0xE0
	jr nz, ParseInt32_SkipWhitespace
	cp (xhl), 0x2D
	jr nz, ParseInt32_CheckMinus
	lds ix, 1
	jr ParseInt32_SkipSign

ParseInt32_CheckMinus:
	cp (xhl), 0x2B
	jr nz, ParseInt32_DigitLoop

ParseInt32_SkipSign:
	inc 1, xhl

ParseInt32_DigitLoop:
	ld_spib E, 0xEC
	exts de
	ld a, e
	extz wa
	bit_dri 2, 0x07, 0xE4, 0xE0
	jr z, ParseInt32_ApplySign
	sub de, 0x30
	ld wa, de
	exts xwa
	ld xde, xiy
	sla xde, 2
	add xde, xiy
	add xde, xde
	ld xiy, xde
	add xiy, xwa
	jr ParseInt32_DigitLoop

ParseInt32_ApplySign:
	cps ix, 0
	jr z, ParseInt32_Positive
	ld xwa, xiy
	cpl wa
	cpl_werp 0xE2
	inc 1, xwa
	ld xhl, xwa
	jr ParseInt32_Return

ParseInt32_Positive:
	ld xhl, xiy

ParseInt32_Return:
	ret

Math_MultiplyAccumulate:
	ldto_werp HL, 0xE2
	mul xhl, xbc
	ldto_werp DE, 0xE6
	mul xde, xwa
	add xhl, xde
	ldfr_werp HL, 0xEE
	lds hl, 0
	mul xwa, xbc
	add xhl, xwa
	ret

; =============================================================================
; Audio_SendCommand -- Send sound parameter command to Sub CPU
; =============================================================================
; Primary interface for all Main CPU -> Sub CPU audio parameter updates.
; Acquires audio lock #7, formats command via Audio_CommandEncoder (printf-like
; format string parser), writes to ring buffer at 0xBD3C via AssswbWr.
; Referenced by 197+ locations (every Lsw* function, preset loaders, etc.).
; Args: xwa = format string pointer, stack = format arguments
Audio_SendCommand:
	dec 4, xsp
	pushw iz
	lds wa, 7
	call 0xEF1FEE
	ld xwa, (xsp + 10)
	st32_24 0x03c21c, xwa
	ld xwa, (xsp + 10)
	ld (xwa), 0x0
	lda xwa, (xsp + 14)
	inc 4, xwa
	ld (xsp + 2), xwa
	pushw 0xFF
	pushw 0xAD8
	lda xwa, (xsp + 6)
	push xwa
	ld xwa, (xsp + 22)
	push xwa
	call Audio_CommandEncoder
	lda xsp, (xsp + 12)
	ld iz, hl
	lds wa, 7
	call 0xEF1F0F
	ld hl, iz
	popw iz
	inc 4, xsp
	ret

LABEL_FF0AB4:
	ld	xwa, (xsp+4)
	st32_24	246300, xwa
	ld	xwa, (xsp+4)
	ld	(xwa), 0
	pushw	255
	pushw	2776
	lda	xwa, (xsp+16)
	push	xwa
	ld	xwa, (xsp+16)
	push	xwa
	call	16715848
	lda	xsp, (xsp+12)
	ret
	ld32_24	xbc, 246300
	lds32	xwa, 1
	addm32_24	246300, xwa
	ld	wa, (xsp+4)
	ld	(xbc), a
	ld32_24	xwa, 246300
	ld	(xwa), 0
	ret

Free:
	ld xwa, (xsp + 4)
	or xwa, xwa
	ret z
	lds wa, 1
	call TaskSched_WaitForEvent
	ld xbc, (xsp + 4)
	dec 6, xbc
	ld32_24 xwa, 0x03d52c
	or xwa, xwa
	jr nz, LABEL_FF0B1C
	lds32 xwa, 0
	ld (xbc), xwa
	st32_24 0x03d52c, xbc
	lds wa, 1
	jp TaskSched_SignalEvent

LABEL_FF0B1C:
	ld32_24 xix, 0x03d52c
	ld xde, xix
	or xix, xix
	jr z, LABEL_FF0B33

LABEL_FF0B27:
	cp xbc, xix
	jr ule, LABEL_FF0B33
	ld xde, xix
	ld xix, (xix)
	or xix, xix
	jr nz, LABEL_FF0B27

LABEL_FF0B33:
	cp xbc, xix
	jr nz, LABEL_FF0B3D
	lds wa, 1
	jp TaskSched_SignalEvent

LABEL_FF0B3D:
	ld hl, (xbc + 4)
